INSERT INTO m259_art VALUES
(0,0,$m259$قانون البنك المركزى والجهاز المصرفى 194/2020 > الديباجة$m259$,$m259$الجريدة الرسمية - العدد 37 مكرر (و) فى 15 سبتمبر سنة 2020
قانون رقم 194 لسنة 2020
بإصدار قانون البنك المركزى والجهاز المصرفى
باسم الشعب
رئيس الجمهورية
قرر مجلس النواب القانون الآتى نصه ، وقد أصدرناه :$m259$,'6310b88ea1acb0086ff8288ed38f69c0'),
(1,-1,$m259$قانون البنك المركزى والجهاز المصرفى 194/2020 > مواد الإصدار > المادة الأولى من قانون الإصدار$m259$,$m259$تسرى أحكام القانون المرافق على البنك المركزى والجهاز المصرفى وشركات الصرافة وشركات تحويل الأموال وشركات الاستعلام والتصنيف الائتمانى وشركات ضمان الائتمان ومشغلى نظم الدفع ومقدمى خدمات الدفع .$m259$,'4f78549d90ec713f41f04b0da4e6677a'),
(2,-1,$m259$قانون البنك المركزى والجهاز المصرفى 194/2020 > مواد الإصدار > المادة الثانية من قانون الإصدار$m259$,$m259$تسرى على البنوك والشركات المخاطبة بأحكام القانون المرافق ، فيما لم يرد فى شأنه نص فيه أو فى اللوائح والقرارات الصادرة تنفيذاً له ، أحكام قانون شركات المساهمة وشركات التوصية بالأسهم والشركات ذات المسئولية المحدودة وشركات الشخص الواحد الصادر بالقانون رقم 159 لسنة 1981
ويكون البنك المركزى هو الجهة الإدارية المختصة ، ومحافظ البنك المركزى هو الوزير المختص فى تطبيق أحكام قانون شركات المساهمة وشركات التوصية بالأسهم والشركات ذات المسئولية المحدودة وشركات الشخص الواحد المشار إليه بالنسبة للجهات الخاضعة لإشرافه طبقًا لأحكام القانون المرافق .
كما تسرى أحكام قانون التجارة الصادر بالقانون رقم 17 لسنة 1999 على معاملات البنوك مع عملائها تجاراً كانوا أو غير تجار أياً كانت طبيعة هذه المعاملات .$m259$,'f870153df7fb3fd8c4d785f6af0c21c5'),
(3,-1,$m259$قانون البنك المركزى والجهاز المصرفى 194/2020 > مواد الإصدار > المادة الثالثة من قانون الإصدار$m259$,$m259$تستبدل عبارة "البنوك المملوكة أسهمها بالكامل للدولة" بعبارة "بنوك القطاع العام" أينما وردت فى القوانين والقرارات المعمول بها .$m259$,'7512b6eaa11d368b1851e7bf65f5e92d'),
(4,-1,$m259$قانون البنك المركزى والجهاز المصرفى 194/2020 > مواد الإصدار > المادة الرابعة من قانون الإصدار$m259$,$m259$يلتزم المخاطبون بأحكام القانون المرافق بتوفيق أوضاعهم طبقًا لأحكامه وذلك خلال مدة لا تجاوز سنة من تاريخ العمل به . ولمجلس إدارة البنك المركزى مد هذه المدة لمدة أو لمدد أخرى لا تجاوز سنتين .$m259$,'e1f43e6290f653be96620bbcc28856f8'),
(5,-1,$m259$قانون البنك المركزى والجهاز المصرفى 194/2020 > مواد الإصدار > المادة الخامسة من قانون الإصدار$m259$,$m259$يصدر مجلس إدارة البنك المركزى اللوائح والقرارات المنفذة لأحكام القانون المرافق ، وتنشر فى الوقائع المصرية ، وإلى أن تصدر هذه اللوائح والقرارات يستمر العمل باللوائح والقرارات القائمة بما لا يتعارض مع أحكامه .$m259$,'4110dbcd81d52d680cb06a33aada7960'),
(6,-1,$m259$قانون البنك المركزى والجهاز المصرفى 194/2020 > مواد الإصدار > المادة السادسة من قانون الإصدار$m259$,$m259$يستمر مجلس إدارة البنك المركزى بتشكيله الحالى فى مباشرة مهامه واختصاصاته إلى حين انتهاء مدته . كما تستمر مجالس إدارة البنوك بتشكيلاتها الحالية فى مباشرة مهامها واختصاصاتها إلى حين انتهاء مدة كل منها .$m259$,'786957b673572f106be5edc94ba85598'),
(7,-1,$m259$قانون البنك المركزى والجهاز المصرفى 194/2020 > مواد الإصدار > المادة السابعة من قانون الإصدار$m259$,$m259$تلغى قانون البنك المركزى والجهاز المصرفى والنقد الصادر بالقانون رقم 88 لسنة 2003 .
وتلغى المادة ( 10 ) من القانون رقم 11 لسنة 1940 بشأن بيع المحال التجارية ورهنها ، والمادة ( 1 ) من القانون رقم 19 لسنة 1975 بتقرير بعض الحقوق والمزايا للبنك الصناعى .
كما تلغى المادة ( 94 ) من قانون شركات المساهمة وشركات التوصية بالأسهم والشركات ذات المسئولية المحدودة وشركات الشخص الواحد الصادر بالقانون رقم 159 لسنة 1981 ، والمادة ( 21 ) من قانون إنشاء البنك المصرى لتنمية الصادرات الصادر بالقانون رقم 95 لسنة 1983
ومع مراعاة أحكام الاتفاقيات الدولية الخاصة بإنشاء بعض البنوك فى جمهورية مصر العربية ، يلغى كل حكم يخالف أحكام هذا القانون والقانون المرافق ، بما فى ذلك الأحكام الواردة بالقوانين الخاصة بإنشاء بعض البنوك فيما يتعلق بالحد الأدنى لرأس المال ، واختصاصات البنك المركزى الرقابية والإشرافية والتدخل المبكر وتسوية أوضاع البنوك المتعثرة ، وسرية الحسابات وقواعد التعامل فى النقد الأجنبى .$m259$,'bca304aeb7aeafdbc5ae73b833e7735a'),
(8,-1,$m259$قانون البنك المركزى والجهاز المصرفى 194/2020 > مواد الإصدار > المادة الثامنة من قانون الإصدار$m259$,$m259$ينشر هذا القانون فى الجريدة الرسمية ، ويعمل به من اليوم التالى لتاريخ نشره .
يبصم هذا القانون بخاتم الدولة ، ويُنفذ كقانون من قوانينها .
صدر برئاسة الجمهورية فى 27 المحرم سنة 1442هـ ( الموافق 15 سبتمبر سنة 2020م ) .
عبد الفتاح السيسى$m259$,'24e40933e64f49351a7ecc9acceca49c'),
(1,0,$m259$قانون البنك المركزى والجهاز المصرفى 194/2020 > الباب الأول: التعريفات$m259$,$m259$يقصد فى تطبيق أحكام هذا القانون بالكلمات والعبارات التالية المعنى المبين قرين كل منها :
البنك المركزى : البنك المركزى المصرى .
مجلس الإدارة : مجلس إدارة البنك المركزى .
المحافظ : محافظ البنك المركزى .
الجهات المرخص لها : البنوك ، وشركات الصرافة ، وشركات الاستعلام والتصنيف الائتمانى ، وشركات تحويل الأموال ، وشركات ضمان الائتمان ، ومشغلو نظم الدفع ، ومقدمو خدمات الدفع .
عمليات السوق المفتوحة : العمليات التى يجريها البنك المركزى لضخ أو سحب السيولة لدى الجهاز المصرفى مثل ربط ودائع أو إصدار شهادات إيداع أو غيرها من الأدوات الأخرى ، وكذا التعامل بالشراء أو بالبيع أو بالبيع مع إعادة الشراء على الأوراق والأدوات المالية التى يصدرها البنك المركزى ، والأوراق والأدوات المالية الحكومية المصرية ، والأوراق المضمونة من الحكومة ، وغيرها من السندات التى يعينها مجلس الإدارة .
البنوك : الشركات وفروع البنوك الأجنبية المرخص لها بمزاولة أعمال البنوك طبقاً لأحكام هذا القانون .
البنوك المتخصصة : البنوك المرخص لها بمزاولة بعض أعمال البنوك طبقاً لأحكام هذا القانون .
البنوك الرقمية : بنوك تقدم الخدمات المصرفية عبر القنوات أو المنصات الرقمية باستخدام التقنيات التكنولوجية الحديثة .
الجهات الأجنبية المناظرة : الجهات الأجنبية التى تمارس اختصاصات مماثلة لكل اختصاصات البنك المركزى المنصوص عليها فى هذا القانون أو بعضها ، سواءً كانت بنوكاً مركزية أو غيرها من الجهات .
الشركات التابعة : الشركات التى يمتلك البنك بطريق مباشر أو غير مباشر القدرة على التحكم فى سياستها المالية والتشغيلية ، أو يكون للبنك حصة ملكية تزيد على ( 50% ) من أسهمها أو من حقوق التصويت .
الشركات الشقيقة : الشركات التى يمتلك البنك بطريق مباشر أو غير مباشر تأثيراً قوياً عليها لا يصل إلى حد السيطرة ، أو يكون للبنك حصة ملكية من ( 20% ) إلى ( 50% ) من أسهمها أو من حقوق التصويت .
الشركة الأم : الشركة التى يكون أى من البنوك بمثابة شركة تابعة أو شقيقة لها .
الرقابة المشتركة : التعاون بين السلطة المختصة بدولة المقر الرئيسى ونظيرتها بالدولة المضيفة فى مجال الرقابة والإشراف والتدخل المبكر وتسوية الأوضاع والتصفية بالنسبة للبنوك ونظم وخدمات الدفع .
الرقابة المجمعة : الرقابة على البنك وشركاته وكياناته التابعة والشقيقة .
أعمال البنوك : كل نشاط يتناول بشكل أساسى واعتيادى قبول الودائع والحصول على التمويل واستثمار هذه الأموال فى تقديم التمويل والتسهيلات الائتمانية أو المساهمة فى رءوس أموال الشركات ، وكل ما يجرى العرف المصرفى على اعتباره من أعمال البنوك .
العقود المالية : العقود التى يكون أحد البنوك طرفاً فيها بهدف الحصول على تمويل أو قروض لأجل من أى نوع ، أو العقود المنظمة للمشتقات المالية المتعلقة بالسلع أو الأوراق أو الأدوات المالية وغيرها بما فى ذلك عقود البيع مع إعادة الشراء والخيارات والمبادلة والعقود المستقبلية والعقود الآجلة .
العميل : كل شخص طبيعى أو اعتبارى يتلقى خدمة من إحدى الجهات المرخص لها طبقاً لأحكام هذا القانون .
المسئولون الرئيسيون : رؤساء وأعضاء مجالس إدارة البنوك والمديرون التنفيذيون المسئولون عن الأنشطة الرئيسية والرقابية التى يصدر بتحديدها وتحديد اختصاصاتها قرار من مجلس الإدارة .
شروط الجدارة والصلاحية : المعايير التى يضعها البنك المركزى للموافقة على تعيين المسئولين الرئيسيين .
المساهم الرئيسى : المساهم المالك لنسبة تزيد على ( 10% ) من رأس المال المصدر للبنك أو من حقوق التصويت ، سواء بمفرده أو من خلال أطرافه المرتبطة .
البنك المعبرى : بنك ينشأ لفترة مؤقتة لتسوية أوضاع أى من البنوك المتعثرة طبقاً لأحكام هذا القانون .
جهات منح الائتمان : الجهات أو الشركات بخلاف البنوك التى تقوم بمنح ائتمان مثل شركات التمويل العقارى والتأجير التمويلى وجمعيات التمويل .
السيطرة الفعلية : قدرة الشخص وأطرافه المرتبطة على تعيين غالبية أعضاء مجلس إدارة شركة ، أو التحكم على أى نحو فى القرارات التى يصدرها مجلس إدارتها ، أو التحكم فى القرارات التى تصدر عن جمعيتها العامة .
الأطراف المرتبطة : الأشخاص الذين يجمع بينهم اتفاق بغرض الاستحواذ أو السيطرة الفعلية على إحدى الشركات ، والأشخاص الطبيعيون وأقاربهم حتى الدرجة الثانية ، وكذا الأشخاص الاعتباريون الخاضعون للسيطرة الفعلية لذات الأشخاص ، وكذلك مجموع الأشخاص الاعتباريين الخاضعين للسيطرة الفعلية لذات الأشخاص الذين يكون بينهم اتفاق على ممارسة حقوقهم فى الجمعية العامة أو مجلس إدارة الشركة بما يؤدى إلى السيطرة الفعلية على أى منهما .
خدمات التعهيد : الخدمات التى تسندها الجهات المرخص لها لطرف ثالث للقيام بأى مهام أو أنشطة نيابة عنها .
المدير المؤقت : الشخص المعين بمعرفة البنك المركزى لإدارة أى من البنوك أو مشغلى نظم الدفع أو مقدمى خدمات الدفع طبقاً لأحكام هذا القانون .
المفوض : الشخص المعين بمعرفة البنك المركزى لإدارة البنك المتعثر وتسوية أوضاعه طبقاً لأحكام هذا القانون .
المصادقة الإلكترونية : مجموعة من الوسائل التكنولوجية المستخدمة للتحقق من مصدر رسالة ما والتحقق من هوية أحد المشتركين عند اتصاله بالنظام والتأكد من أن رسالة التحقق من الهوية لم يتم تعديلها أو استبدالها أثناء انتقالها ، وتقوم مقام توقيع العميل .
أمر الدفع : تعليمات يصدرها الدافع أو المستفيد بناءً على تفويض من الدافع إلى مقدم خدمات الدفع لتنفيذ عملية إيداع أموال ، أو تحويلها أو سحبها سواء فى صورة ورقية أو إلكترونية .
تفويض الخصم المباشر : اتفاق يقوم بموجبه الدافع بمنح الحق للمستفيد فى إصدار تعليمات إلى مقدم خدمات الدفع لتنفيذ أمر خصم مباشر أو أكثر على حساب الدافع لصالح المستفيد طبقاً للقيم وتواريخ الاستحقاق المبينة به .
أمر الخصم المباشر : أمر دفع يصدر للخصم من حساب الدافع لمصلحة المستفيد بناءً على طلبه طبقاً للتعليمات الواردة بتفويض الخصم المباشر .
أمر التحويل : تعليمات يصدرها المشارك إلى نظام الدفع طبقاً لقواعد هذا النظام بغرض تحويل الأموال من حسابه إلى حساب مشارك آخر من خلال نظام الدفع .
نظام الدفع : مجموعة من الوسائل والإجراءات لسداد أو مقاصة أو تسوية الأموال عن طريق تحويل الأموال بين طرفين أو أكثر من خلال نظام إلكترونى .
المشارك : أى طرف يكون مسموحاً له بسداد الأموال أو تلقيها أو المقاصة بينها أو تسويتها من خلال نظام الدفع سواء كان ذلك بصورة مباشرة أو غير مباشرة .
خدمات الدفع : جميع الخدمات المرتبطة بمعلومات الحساب أو بإصدار أو إرسال أوامر وعمليات الدفع أو استقبالها أو تنفيذها سواء بالعملة المحلية أو بالعملات الأجنبية ، وتشمل إصدار وإدارة أدوات الدفع والنقود الإلكترونية .
أداة دفع : وسيلة يعطى المستخدم من خلالها تعليماته لمقدم خدمات الدفع لتنفيذ أمر الدفع .
التكنولوجيا المالية : نماذج أعمال أو تطبيقات أو منتجات مالية قائمة على استخدام التكنولوجيا .
التكنولوجيا الرقابية : استخدام التطبيقات التكنولوجية للتأكد من الالتزام بالقوانين والقواعد المقررة .
النقود الإلكترونية : قيمة نقدية مقومة بالجنيه المصرى أو بإحدى العملات المصدرة من سلطات إصدار النقد الرسمية مستحقة على المرخص له بإصدارها ، وتكون مخزنة إلكترونياً ومقبولة كوسيلة دفع .
العملات المشفرة : عملات مخزنة إلكترونياً غير مقومة بأى من العملات الصادرة عن سلطات إصدار النقد الرسمية ، ويتم تداولها عبر شبكة الإنترنت .
شركات تحويل الأموال : الشركات المرخص لها طبقاً لأحكام هذا القانون بمزاولة نشاط تحويل الأموال من جمهورية مصر العربية وإليها .
الشمول المالى : إتاحة مختلف الخدمات المالية للاستخدام من قبل جميع فئات المجتمع من خلال القنوات الرسمية بجودة وتكلفة مناسبة مع حماية حقوق المستفيدين من تلك الخدمات بما يمكنهم من إدارة أموالهم بشكل سليم .$m259$,'f218ddb1847966a0799fa3135183978f'),
(2,0,$m259$قانون البنك المركزى والجهاز المصرفى 194/2020 > الباب الثانى: البنك المركزى المصرى > الفصل الأول: أحكام عامة$m259$,$m259$البنك المركزى جهاز رقابى مستقل ، له شخصية اعتبارية عامة ، يتبع رئيس الجمهورية ، ويتمتع بالاستقلال الفنى والمالى والإدارى ، ويؤخذ رأيه فى مشروعات القوانين واللوائح المتعلقة بمجال عمله .$m259$,'7d7f6ab0ab9efc79ff867c53b1a2323d'),
(3,0,$m259$قانون البنك المركزى والجهاز المصرفى 194/2020 > الباب الثانى: البنك المركزى المصرى > الفصل الأول: أحكام عامة$m259$,$m259$المركز الرئيسى للبنك المركزى وموطنه القانونى محافظة القاهرة ، وللبنك المركزى بقرار من مجلس الإدارة أن ينشئ له فروعاً ومكاتب ، وأن يتخذ وكلاء ومراسلين له فى داخل البلاد وخارجها .$m259$,'33b68f078ec36268825d6b21f170c299'),
(4,0,$m259$قانون البنك المركزى والجهاز المصرفى 194/2020 > الباب الثانى: البنك المركزى المصرى > الفصل الأول: أحكام عامة$m259$,$m259$الحد الأدنى لرأس المال المدفوع للبنك المركزى عشرون مليار جنيه .
وتكون زيادة رأسمال البنك المركزى بقرار من مجلس الإدارة وذلك بتجنيب نسبة من الأرباح السنوية الصافية أو من الاحتياطيات أو بتمويل من الخزانة العامة مباشرة بموافقة وزير المالية .
ولا يجوز أن تظهر حقوق الملكية بقيمة سالبة ، وفى حالة حدوث ذلك ، يتعين تغطيتها من الخزانة العامة للدولة خلال فترة لا تجاوز تسعين يوماً من تاريخ إخطار وزير المالية ، وذلك بعد العرض على مجلس الوزراء خلال تلك المدة ، وتكون التغطية إما نقداً أو فى صورة أدوات دين قابلة للتداول بأسعار العائد السائدة بالسوق .$m259$,'e6f692a19101b4ce562eace424dec727'),
(5,0,$m259$قانون البنك المركزى والجهاز المصرفى 194/2020 > الباب الثانى: البنك المركزى المصرى > الفصل الأول: أحكام عامة$m259$,$m259$تعتبر أموال البنك المركزى أموالاً خاصة .$m259$,'0cbddc48ae0b09bc4acc1d830eb5d7ab'),
(6,0,$m259$قانون البنك المركزى والجهاز المصرفى 194/2020 > الباب الثانى: البنك المركزى المصرى > الفصل الثانى: أهداف البنك المركزى واختصاصاته$m259$,$m259$يهدف البنك المركزى إلى سلامة النظام النقدى والمصرفى واستقرار الأسعار فى إطار السياسة الاقتصادية العامة للدولة .$m259$,'f9cd0d8ff556baabe6a9d85a66f5b020'),
(7,0,$m259$قانون البنك المركزى والجهاز المصرفى 194/2020 > الباب الثانى: البنك المركزى المصرى > الفصل الثانى: أهداف البنك المركزى واختصاصاته$m259$,$m259$يباشر البنك المركزى جميع الاختصاصات اللازمة لتحقيق أهدافه ، وله على الأخص ما يأتى :
( أ ) إصدار النقد وإدارته ، وتحديد فئاته ومواصفاته .
( ب ) وضع السياسة النقدية وتنفيذها ، وإصدار الأوراق والأدوات المالية بما يتناسب مع طبيعة أمواله ونشاطه والدخول فى عمليات السوق المفتوحة ، وذلك دون التقيد بحكم المادة ( 465 ) من القانون المدنى .
( جـ ) وضع نظام وسياسة سعر الصرف الأجنبى وتنفيذها ، وتنظيم سوق الصرف الأجنبى ورقابته .
( د ) إصدار اللوائح والتعليمات الرقابية للجهات المرخص لها والمسئولين الرئيسيين ، والإشراف والرقابة عليها .
( هـ ) وضع سياسة إدارة المخاطر الكلية فى النظام المصرفى ، وتنفيذها .
( و ) إدارة الأزمات المصرفية ، وتسوية أوضاع البنوك المتعثرة .
( ز ) الاحتفاظ باحتياطيات الدولة من الذهب والنقد الأجنبى ، وإدارتها .
( ح ) القيام بدور المستشار والوكيل المالى للحكومة .
( ط ) حصر ومتابعة المديونية الخارجية على الحكومة والهيئات العامة الخدمية والاقتصادية وشركات القطاع العام وقطاع الأعمال العام والقطاع الخاص .
( ى ) العمل على حماية حقوق عملاء الجهات المرخص لها ، وتسوية المنازعات ذات الصلة .
( ك ) العمل على حماية المنافسة وتعزيزها ، ومنع الممارسات الاحتكارية بالجهات المرخص لها .
( ل ) العمل على تحقيق سلامة نظم وخدمات الدفع ، ورفع كفاءتها .$m259$,'3ce2c38a50e3d1918d8b59f2108f253a'),
(8,0,$m259$قانون البنك المركزى والجهاز المصرفى 194/2020 > الباب الثانى: البنك المركزى المصرى > الفصل الثانى: أهداف البنك المركزى واختصاصاته$m259$,$m259$يتخذ البنك المركزى الوسائل التى تكفل تحقيق أهدافه والنهوض باختصاصاته ، وله على الأخص ما يأتى :
( أ ) التعاون وتبادل المعلومات مع الجهات الأجنبية المناظرة .
( ب ) المساهمة والاشتراك فى المؤسسات والجهات الدولية ذات الصلة بمجال عمله .
( جـ ) القيام بأنشطة المقاصة والتسوية المالية والإيداع والقيد والحفظ المركزى للأوراق والأدوات المالية الحكومية وتشغيل النظم الخاصة بها ، وذلك طبقاً للأحكام المقررة بقانون الإيداع والقيد المركزى للأوراق والأدوات المالية الصادر بالقانون رقم 93 لسنة 2000
( د ) تعزيز الشمول المالى ، والعمل على توسيع قاعدة المستفيدين من الخدمات المصرفية ، ووضع الأطر التى تهدف إلى خفض الاستخدام المادى للنقود .
( هـ ) تأسيس شركات مساهمة بمفرده أو مع شركاء آخرين أو المساهمة فى شركات قائمة ، وذلك بما يلزم لتحقيق أهدافه والنهوض باختصاصاته .
( و ) إنشاء نظم وخدمات الدفع وإدارتها .
( ز ) القيام بأى مهام أو اتخاذ أى إجراءات يقتضيها تطبيق السياسات النقدية والائتمانية والمصرفية .
( ح ) وضع القواعد المتعلقة بمنع تعارض المصالح بالجهات المرخص لها ، ووضع الأطر الفعالة لإدارتها .$m259$,'1af2a0f52911b389351995d3e3eb8f86'),
(9,0,$m259$قانون البنك المركزى والجهاز المصرفى 194/2020 > الباب الثانى: البنك المركزى المصرى > الفصل الثانى: أهداف البنك المركزى واختصاصاته$m259$,$m259$للبنك المركزى أن يقدم تمويلاً للجهات التى يساهم فيها وللمنشآت وللهيئات الأجنبية والدولية ، وذلك طبقاً للشروط والقواعد والضمانات التى يقرها مجلس الإدارة .
ولا يجوز للبنك المركزى تقديم قروض أو ضمانات أو دعم مالى إلى البنوك باستثناء تلك المتعلقة بعمليات السياسة النقدية والتسهيلات الائتمانية لليوم الواحد ، وعمليات منح السيولة الطارئة ، والتمويل الذى يقدم نيابة عن الحكومة ، وضمان الحصول على التمويل والتسهيلات الائتمانية بالنقد الأجنبى من خارج البلاد مقابل ضمانات كافية يقبلها مجلس الإدارة .$m259$,'718e193c39cc8bf2bbc6d0227db1d3e0'),
(10,0,$m259$قانون البنك المركزى والجهاز المصرفى 194/2020 > الباب الثانى: البنك المركزى المصرى > الفصل الثانى: أهداف البنك المركزى واختصاصاته$m259$,$m259$لمجلس الإدارة الموافقة على منح تمويل طارئ لأى بنك يعانى نقصاً فى السيولة بالشروط الآتية :
( أ ) أن يكون البنك ذا ملاءة مالية .
( ب ) ألا تزيد مدة التمويل على ( 180 ) يوماً ، يجوز مدها لفترة أو فترات أخرى ، على ألا يزيد إجمالى مدة التمويل على سنة .
( جـ ) أن يكون التمويل مقابل ضمانات كافية يقبلها البنك المركزى .
( د ) أن يكون سعر العائد المطبق على التمويل أعلى من متوسط أسعار الإقراض السائدة بالسوق .$m259$,'9e96ec924fa3a5593cf789461244dcba'),
(11,0,$m259$قانون البنك المركزى والجهاز المصرفى 194/2020 > الباب الثانى: البنك المركزى المصرى > الفصل الثانى: أهداف البنك المركزى واختصاصاته$m259$,$m259$مع عدم الإخلال بأحكام المادة ( 10 ) من هذا القانون ، يجوز لمجلس الإدارة فى الظروف الاستثنائية الموافقة على تقديم تمويل للبنوك ذات الملاءة المالية المنخفضة أو المرجح تعثرها بصفته وكيلاً عن الحكومة ، طبقاً للشروط الآتية :
( أ ) أن يكون تقديم الدعم ضرورياً للحفاظ على النظام المصرفى .
( ب ) قابلية البنك للاستمرار من خلال خطة إعادة هيكلة أوضاعه أو تسويتها خلال فترة زمنية يحددها البنك المركزى .
( جـ ) ألا تجاوز مدة التمويل ( 180 ) يوماً ، يجوز مدها لفترة أو فترات أخرى ، على ألا يزيد إجمالى مدة التمويل على سنة .
( د ) أن يكون ذلك مقابل ضمانات كافية من البنك يقبلها البنك المركزى .
( هـ ) أن يكون سعر العائد المطبق على التمويل أعلى من متوسط أسعار الإقراض السائدة بالسوق .
( و ) أن توافق وزارة المالية على تقديم ضمان قانونى للبنك المركزى ، تتعهد فيه بتوفير المخصص المالى لكامل التمويل المقدم .
ويخضع البنك المقدم له التمويل فى هذه الحالة للرقابة المشددة من البنك المركزى .$m259$,'36b768d30f800703ca0312598cc3c4f9'),
(12,0,$m259$قانون البنك المركزى والجهاز المصرفى 194/2020 > الباب الثانى: البنك المركزى المصرى > الفصل الثانى: أهداف البنك المركزى واختصاصاته$m259$,$m259$للبنك المركزى أن يتعهد بتوفير العملات الأجنبية لسداد التمويل والتسهيلات الائتمانية التى تحصل عليها البنوك أو الأشخاص الاعتبارية العامة من البنوك والمؤسسات المالية والهيئات الأجنبية والدولية ، وذلك طبقاً للشروط والقواعد التى يقررها مجلس الإدارة .$m259$,'0462283fbae38ae76a4a06f84c050200'),
(13,0,$m259$قانون البنك المركزى والجهاز المصرفى 194/2020 > الباب الثانى: البنك المركزى المصرى > الفصل الثانى: أهداف البنك المركزى واختصاصاته$m259$,$m259$للبنك المركزى فى سبيل مباشرة اختصاصاته فتح حسابات نقدية أو بالمعادن النفيسة أو الأوراق والأدوات المالية لصالح أى من الجهات الآتية :
( أ ) البنوك .
( ب ) البنوك المركزية والحكومات الأجنبية والمؤسسات المالية الدولية والأجنبية .
( جـ ) البنوك الأجنبية .
( د ) الحكومة والأشخاص الاعتبارية العامة .
( هـ ) الشركات المرخص لها بالعمل فى مجال نظم وخدمات الدفع .
( و ) الجهات التى يساهم فيها البنك المركزى .
ويحظر على البنك المركزى فتح حسابات لأى جهات أو أشخاص آخرين فيما عدا العاملين لديه الحاليين والسابقين .
كما يجوز للبنك المركزى فتح حسابات نقدية أو بالمعادن النفيسة أو الأوراق والأدوات المالية لدى أى من :
( أ ) البنوك .
( ب ) البنوك المركزية والبنوك الأجنبية والمؤسسات المالية الدولية ومؤسسات الإيداع وأمناء الحفظ .
وذلك كله طبقاً للقواعد والشروط التى يُحددها مجلس الإدارة .$m259$,'7647642eed10130017f1a3df7368ad1a'),
(14,0,$m259$قانون البنك المركزى والجهاز المصرفى 194/2020 > الباب الثانى: البنك المركزى المصرى > الفصل الثانى: أهداف البنك المركزى واختصاصاته$m259$,$m259$يختص البنك المركزى بجمع وتحليل البيانات والمعلومات والإحصاءات النقدية والمصرفية والمالية ، كما يختص دون غيره بإعداد ميزان المدفوعات ونشره .
ويحدد البنك المركزى البيانات والمعلومات والإحصاءات المطلوبة ، والجهات المعنية بتقديمها ، وضوابط المحافظة على سريتها ، ومواعيد تقديمها .
وتلتزم الجهات المعنية بتزويد البنك المركزى بالبيانات والمعلومات والإحصاءات المشار إليها .$m259$,'a57aad86f657c9259eec445464d8d697'),
(15,0,$m259$قانون البنك المركزى والجهاز المصرفى 194/2020 > الباب الثانى: البنك المركزى المصرى > الفصل الثانى: أهداف البنك المركزى واختصاصاته$m259$,$m259$للبنك المركزى أن يحتفظ ضمن الاحتياطيات الأجنبية بأى من الأصول الآتية :
( أ ) الذهب والمعادن النفيسة الأخرى .
( ب ) الأرصدة بالعملات الأجنبية المحتفظ بها فى حساباته ، أو لصالحه لدى البنوك أو البنوك المركزية الأجنبية أو البنوك الأجنبية أو المؤسسات المالية الدولية .
( جـ ) سندات الدين المتداولة بعملات أجنبية الصادرة أو المضمونة من الحكومات أو البنوك المركزية الأجنبية أو المؤسسات المالية الدولية .
( د ) المطالبات المستحقة على المؤسسات المالية الدولية .
( هـ ) ما يحدده مجلس الإدارة من أصول مالية متداولة بالعملات الأجنبية .
وذلك كله طبقاً للشروط والقواعد التى يحددها مجلس الإدارة .$m259$,'90dfdff3ac304e19f8c9fb7bbc6ab05e'),
(16,0,$m259$قانون البنك المركزى والجهاز المصرفى 194/2020 > الباب الثانى: البنك المركزى المصرى > الفصل الثانى: أهداف البنك المركزى واختصاصاته$m259$,$m259$ينشأ بالبنك المركزى نظام لتسجيل بيانات العملاء لإعداد الدراسات اللازمة لتعزيز الشمول المالى وتطوير الخدمات المصرفية ، وذلك طبقاً للضوابط والإجراءات التى يحددها مجلس الإدارة مع مراعاة المحافظة على سريتها .$m259$,'87d90aaa89b7fc6aa46f7fd62246b4f9'),
(17,0,$m259$قانون البنك المركزى والجهاز المصرفى 194/2020 > الباب الثانى: البنك المركزى المصرى > الفصل الثالث: إدارة البنك المركزى وحوكمته$m259$,$m259$يكون للبنك المركزى محافظ بدرجة نائب رئيس مجلس الوزراء ، يصدر بتعيينه قرار من رئيس الجمهورية ، بعد موافقة مجلس النواب بأغلبية أعضائه ، لمدة أربع سنوات قابلة للتجديد لمرة واحدة ، ويحدد القرار المعاملة المالية له ، ويحظر على المحافظ ما يحظر على الوزراء .
ويعامل المحافظ من حيث المعاش معاملة نائب رئيس مجلس الوزراء .
ويكون قبول استقالة المحافظ بقرار من رئيس الجمهورية .$m259$,'605800ee760ed658f74115122547fcc2'),
(18,0,$m259$قانون البنك المركزى والجهاز المصرفى 194/2020 > الباب الثانى: البنك المركزى المصرى > الفصل الثالث: إدارة البنك المركزى وحوكمته$m259$,$m259$يكون للمحافظ نائبان ، يعين كل منهما بقرار من رئيس الجمهورية بناءً على ترشيح المحافظ لمدة أربع سنوات قابلة للتجديد ، ويحدد القرار المعاملة المالية لهما .
وفى حالة غياب المحافظ أو وجود مانع لديه يحل محله فى ممارسة اختصاصاته أقدم النائبين ، فإن غاب النائب حل محله النائب الآخر .
ويعامل نائب المحافظ من حيث المعاش معاملة الوزير ، ويكون قبول استقالته بقرار من رئيس الجمهورية .
كما يكون للمحافظ وكلاء يعينون بقرار من مجلس الإدارة بناءً على ترشيح من المحافظ .$m259$,'5013fa0be40a59885889a4047627f546'),
(19,0,$m259$قانون البنك المركزى والجهاز المصرفى 194/2020 > الباب الثانى: البنك المركزى المصرى > الفصل الثالث: إدارة البنك المركزى وحوكمته$m259$,$m259$يمثل المحافظ البنك المركزى أمام القضاء وفى صلاته مع الغير بما فى ذلك الجهات والهيئات الدولية ، ويتولى تصريف جميع شئونه ، وذلك دون الإخلال باختصاصات مجلس الإدارة ولجانه ، ويعاون المحافظ فى ذلك نائباه ووكلاؤه كل فى حدود اختصاصه .
ويجوز للمحافظ أن يفوض بعضاً من اختصاصاته إلى أى من نائبيه أو وكلائه ، ويخطر مجلس الإدارة بذلك .
ويقدم المحافظ لمجلس الإدارة تقريراً عن أعمال الإدارة التنفيذية للبنك المركزى كل ثلاثة أشهر .$m259$,'f3c29c387f0d777fdd40e680994332d7'),
(20,0,$m259$قانون البنك المركزى والجهاز المصرفى 194/2020 > الباب الثانى: البنك المركزى المصرى > الفصل الثالث: إدارة البنك المركزى وحوكمته$m259$,$m259$يشكل مجلس الإدارة برئاسة المحافظ ، وعضوية كل من :
نائبى المحافظ .
رئيس الهيئة العامة للرقابة المالية .
سبعة أعضاء غير تنفيذيين من ذوى الخبرة فى المسائل الاقتصادية أو النقدية أو المصرفية أو المالية أو القانونية أو المحاسبية أو تكنولوجيا المعلومات ، يكون من بينهم اثنان من ذوى الخبرة فى المسائل الاقتصادية ، ويصدر بتعيينهم قرار من رئيس الجمهورية بناءً على ترشيح المحافظ ، وبعد أخذ رأى رئيس مجلس الوزراء لمدة أربع سنوات قابلة للتجديد لمرة واحدة ، ويجوز أن يكون من بينهم أعضاء متفرغون لعضوية المجلس واللجان المنبثقة عنه .
وإذا خلا مكان أى عضو من الأعضاء غير التنفيذيين قبل انتهاء مدته يُعين عضو آخر محله لاستكمال المدة الباقية ، وذلك خلال ستين يوماً من خلو مكان العضو السابق .
ويصدر بتشكيل المجلس وتحديد مكافآت أعضائه غير التنفيذيين وبدلات حضور جلساته قرار من رئيس الجمهورية بناءً على اقتراح المحافظ .$m259$,'35dc7cc95110612f62e7f2115dab28fb'),
(21,0,$m259$قانون البنك المركزى والجهاز المصرفى 194/2020 > الباب الثانى: البنك المركزى المصرى > الفصل الثالث: إدارة البنك المركزى وحوكمته$m259$,$m259$يشترط فى كل من المحافظ ونائبيه وأعضاء مجلس الإدارة ما يأتى :
( أ ) أن يكون مصرياً من أبوين مصريين .
( ب ) أن يكون متمتعاً بحقوقه المدنية والسياسية .
( جـ ) أن يكون حسن السمعة محمود السيرة ، ولم يصدر ضده حكم نهائى فى جناية أو فى جنحة ماسة بالشرف أو الأمانة ، أو أشهر إعساره أو إفلاسه .
( د ) ألا يكون قد سبق فصله من العمل بإحدى الوظائف أو شطبه من إحدى النقابات المهنية بقرار أو بحكم تأديبى نهائى .
( هـ ) ألا تكون له أو للجهة التى يعمل بها مصالح جدية تتعارض مع واجباته ، أو يكون من شأنها أن تؤثر فى حيدته أو استقلاليته فى المداولات واتخاذ القرار .
( و ) ألا يمتلك هو أو زوجه أو أى من أولاده القصر أسهماً فى إحدى الجهات المرخص لها ، وفى حالة امتلاكه هو أو زوجه أو أولاده القصر لأى أسهم يتعين عليهم التصرف فيها خلال شهرين من تاريخ التعيين أو من تاريخ أيلولة تلك الأسهم إلى أى منهم .
( ز ) ألا يجمع بين عضويته فى مجلس الإدارة والعضوية فى أحد مجالس إدارة الجهات المرخص لها ، أو أن يكون من العاملين بها ، أو ممن يقدمون لها خدمات مهنية أو استشارية .
( ح ) ألا يجمع بين عضويته فى مجلس الإدارة والعضوية فى أى حزب سياسى .
( ط ) ألا يكون عضواً فى الحكومة .$m259$,'f55206f58e247cb2b107d91ff8b4ec9a'),
(22,0,$m259$قانون البنك المركزى والجهاز المصرفى 194/2020 > الباب الثانى: البنك المركزى المصرى > الفصل الثالث: إدارة البنك المركزى وحوكمته$m259$,$m259$مجلس الإدارة هو السلطة المختصة بوضع نظم البنك المركزى وسياساته ، والإشراف على تنفيذها ، وله فى سبيل ذلك جميع الصلاحيات اللازمة ، وعلى الأخص ما يأتى :
( أ ) اعتماد السياسات المالية والاستثمارية للبنك المركزى ، ومراقبة تنفيذها ، واعتماد الموازنة التقديرية والقوائم المالية والتقارير التى يعدها عن مركزه المالى ونتائج أعماله .
( ب ) تحديد فئات النقد ومواصفاته وقواعد إصداره وتداوله ، وكيفية تقييم الأصول التى تقابله .
( جـ ) إصدار اللوائح والقرارات والمعايير والضوابط والتعليمات التنظيمية والرقابية للجهات المرخص لها .
( د ) زيادة رأسمال البنك المركزى ، وتكوين الاحتياطيات اللازمة من الأرباح .
( هـ ) اعتماد نظم إعداد التقارير المالية وسياسات إدارة المخاطر والالتزام وتكنولوجيا المعلومات والرقابة الداخلية بالبنك المركزى .
( و ) اعتماد الهيكل التنظيمى للبنك المركزى ، ويجوز أن يشمل هذا الهيكل وحدات ذات طابع خاص ، يكون لها استقلال فنى ومالى وإدارى ، يصدر بإنشائها وتشكيلها ونظام عملها قرار من مجلس الإدارة بناءً على اقتراح المحافظ .
( ز ) العمل على ضمان استقلالية وظائف المراجعة الداخلية والالتزام والمخاطر بالبنك المركزى .
( ح ) إصدار اللوائح والنظم الداخلية المتعلقة بشئون البنك المركزى المالية والإدارية والفنية ، ولائحة تنظيم التعاقدات ، ولائحة العاملين به ، والجزاءات التأديبية الخاصة بهم ، وذلك كله دون التقيد بالقوانين أو اللوائح أو القرارات المعمول بها فى أجهزة الدولة أو فى أى جهة أخرى .
( ط ) قبول المنح وعقد القروض مع الجهات المحلية والأجنبية .$m259$,'15abe6bd308d7aeb11d237905fd2d032'),
(23,0,$m259$قانون البنك المركزى والجهاز المصرفى 194/2020 > الباب الثانى: البنك المركزى المصرى > الفصل الثالث: إدارة البنك المركزى وحوكمته$m259$,$m259$يجتمع مجلس الإدارة بمقر مركزه الرئيسى مرة على الأقل كل شهر ، وذلك بدعوة من المحافظ أو بناءً على دعوة من ثلثى أعضاء المجلس ، ويجوز أن يدعى مجلس الإدارة للانعقاد خارج مقر البنك المركزى بشرط أن يكون داخل جمهورية مصر العربية .
ولا يكون اجتماع مجلس الإدارة صحيحاً إلا بحضور أغلبية أعضائه على أن يكون من بينهم المحافظ أو أحد نائبيه . وتصدر القرارات بأغلبية أعضاء مجلس الإدارة ، وفى حالة التساوى يرجح الجانب الذى منه رئيس الجلسة .
ويجوز المشاركة فى اجتماع مجلس الإدارة باستخدام إحدى وسائل الاتصال البصرية أو السمعية المؤمنة ، وتحسب هذه المشاركة ضمن نصاب الحضور والتصويت ، على ألا يجاوز عدد مستخدمى تلك الوسائل ثلث عدد الأعضاء المشاركين فى الاجتماع .
وتكون مداولات مجلس الإدارة سرية ، ويحدد مجلس الإدارة بقرار منه إجراءات عمله ونظامه .$m259$,'ba3165e7f507477d034d4fb8bbca7029'),
(24,0,$m259$قانون البنك المركزى والجهاز المصرفى 194/2020 > الباب الثانى: البنك المركزى المصرى > الفصل الثالث: إدارة البنك المركزى وحوكمته$m259$,$m259$يعفى المحافظ ونائباه من مناصبهم ، كما تنتهى عضوية أعضاء مجلس الإدارة غير التنفيذيين ، وذلك فى غير حالات الاستقالة أو الوفاة بقرار من رئيس الجمهورية بناءً على توصية من مجلس الإدارة بعد السماح للعضو بإبداء دفاعه ، وذلك فى أى من الحالات الآتية :
( أ ) إذا فقد أحد شروط المنصب أو العضوية .
( ب ) إذا أصبح غير قادر على أداء مهامه لأسباب صحية .
( جـ ) إذا أخل بواجبات المنصب أو العضوية إخلالاً جسيماً .
( د ) إذا تغيب عن الحضور ثلاث جلسات متتالية أو خمس جلسات متفرقة خلال السنة ، دون عذر يقبله مجلس الإدارة .$m259$,'2b5a3ebfa73cb1415974ee566526a161'),
(25,0,$m259$قانون البنك المركزى والجهاز المصرفى 194/2020 > الباب الثانى: البنك المركزى المصرى > الفصل الثالث: إدارة البنك المركزى وحوكمته$m259$,$m259$لمجلس الإدارة أن يقرر تشكيل لجان من بين أعضائه لمباشرة الاختصاصات التى يعهد بها إليها ، على أن يكون من بينها لجنة المراجعة ، ولجنة السياسة النقدية ، ولجنة الإدارة العليا ، ولجنة الاستثمار ، ولجنة المخاطر .
ويعتمد مجلس الإدارة نظام عمل هذه اللجان ، ولها أن تستعين بمن تراه لمباشرة مهامها .
ويجوز أن يضم مجلس الإدارة إلى تشكيل تلك اللجان عضواً من ذوى الخبرة من غير أعضائه ، ويسرى فى شأنه ذات الشروط المنصوص عليها فى المادة ( 21 ) من هذا القانون .
وتكون مداولات هذه اللجان سرية .$m259$,'8155254668e50b5c0384e67ae8a50d1f'),
(26,0,$m259$قانون البنك المركزى والجهاز المصرفى 194/2020 > الباب الثانى: البنك المركزى المصرى > الفصل الثالث: إدارة البنك المركزى وحوكمته$m259$,$m259$لمجلس الإدارة أن يفوض بعضاً من اختصاصاته إلى المحافظ أو اللجان التى يشكلها ، طبقاً للضوابط التى يضعها ، على أن يكون التفويض لمدة محددة ، وذلك عدا الاختصاصات المنصوص عليها فى المادة ( 22 ) ، والفصول : الأول ، والعاشر ، والحادى عشر ، والثانى عشر ، والثالث عشر من الباب الثالث من هذا القانون .$m259$,'e27a3e72debba823628fc6d48189ac90'),
(27,0,$m259$قانون البنك المركزى والجهاز المصرفى 194/2020 > الباب الثانى: البنك المركزى المصرى > الفصل الثالث: إدارة البنك المركزى وحوكمته$m259$,$m259$تشكل لجنة المراجعة من ثلاثة أعضاء من مجلس الإدارة غير التنفيذيين يختارهم مجلس الإدارة ويحدد رئيسها من بينهم ، ويجوز لمجلس الإدارة أن يضم إلى تشكيلها عضواً من ذوى الخبرة من غير أعضاء مجلس الإدارة ، وتهدف إلى ضمان سلامة نظم الرقابة الداخلية والحوكمة .
وللجنة أن تدعو مراقبى الحسابات أو من تراه من الإدارة التنفيذية للبنك المركزى لحضور اجتماعاتها دون أن يكون لهم حق التصويت .$m259$,'c52d416d6dc9d9f0e79a433880a8112b'),
(28,0,$m259$قانون البنك المركزى والجهاز المصرفى 194/2020 > الباب الثانى: البنك المركزى المصرى > الفصل الثالث: إدارة البنك المركزى وحوكمته$m259$,$m259$تشكل لجنة السياسة النقدية برئاسة المحافظ وعضوية نائبى المحافظ ، وثلاثة من أعضاء مجلس الإدارة من غير التنفيذيين يختارهم مجلس الإدارة ، ويجوز لمجلس الإدارة أن يضم إلى تشكيلها عضواً من ذوى الخبرة فى المسائل الاقتصادية أو المصرفية أو المالية من غير أعضاء مجلس الإدارة .
وتختص اللجنة بدراسة التقارير والاقتراحات المقدمة من قطاعى السياسة النقدية والأسواق بالبنك المركزى ، واتخاذ القرارات اللازمة فيما يتعلق بالسياسة النقدية وأدواتها ، وعلى الأخص تحديد أسعار العائد الأساسية لدى البنك المركزى دون التقيد بالحدود والأحكام المنصوص عليها فى أى قانون آخر .$m259$,'38ee0a5a33cec2407535e8b3a81cba27'),
(29,0,$m259$قانون البنك المركزى والجهاز المصرفى 194/2020 > الباب الثانى: البنك المركزى المصرى > الفصل الثالث: إدارة البنك المركزى وحوكمته$m259$,$m259$على المحافظ ونائبيه وأعضاء مجلس الإدارة وأعضاء اللجان التى يشكلها والعاملين بالبنك المركزى الالتزام بأحكام القانون ، وبذل العناية الواجبة ، وتكريس كل جهودهم للبنك المركزى ، والحفاظ على سرية المعلومات التى يتصلون بها بحكم عملهم .
ولا يسألون مدنياً جراء القيام بواجباتهم ، ويتحمل البنك المركزى نفقات الدفاع عنهم فى القضايا التى تقام ضدهم بمناسبة أداء عملهم ، إلا فى حالات الخطأ العمدى أو الإهمال الجسيم .
ويسرى حكم الفقرة الثانية من هذه المادة على المفوض أو المدير المؤقت الذى يعينه البنك المركزى طبقاً لأحكام هذا القانون .$m259$,'e37c7b7f78483cc48aabe645135c8247'),
(30,0,$m259$قانون البنك المركزى والجهاز المصرفى 194/2020 > الباب الثانى: البنك المركزى المصرى > الفصل الثالث: إدارة البنك المركزى وحوكمته$m259$,$m259$يتعين على كل من المحافظ ونائبيه وأعضاء مجلس الإدارة وأعضاء اللجان ، الإفصاح للمجلس أو للجنة بحسب الأحوال عن أى مصلحة مباشرة أو غير مباشرة تتعارض مع واجبات المنصب أو العضوية أو المهام المكلف بها ، وفى هذه الحالة يمتنع عليه الاشتراك فى المناقشة والتصويت .$m259$,'d0fad922de59e5f56ece3a1f9f4d0984'),
(31,0,$m259$قانون البنك المركزى والجهاز المصرفى 194/2020 > الباب الثانى: البنك المركزى المصرى > الفصل الثالث: إدارة البنك المركزى وحوكمته$m259$,$m259$يحظر على العاملين بالبنك المركزى العمل أو المشاركة فى عضوية مجالس إدارة الجهات المرخص لها .
ويجوز بقرار من مجلس الإدارة الاستثناء من حكم الفقرة الأولى من هذه المادة بالنسبة للبنوك والشركات التى يساهم فيها البنك المركزى أو أى من الأشخاص الاعتبارية العامة .$m259$,'e8647e6184ccef34331b4c21f0510b21'),
(32,0,$m259$قانون البنك المركزى والجهاز المصرفى 194/2020 > الباب الثانى: البنك المركزى المصرى > الفصل الثالث: إدارة البنك المركزى وحوكمته$m259$,$m259$استثناءً من أحكام القانون رقم 47 لسنة 1973 بشأن الإدارات القانونية بالمؤسسات العامة والهيئات العامة والوحدات التابعة لها ، تسرى على أعضاء الإدارة القانونية بالبنك المركزى سائر أحكام لائحة العاملين به .
ويصدر بتحديد اختصاصات الإدارة القانونية ونظام عملها قرار من مجلس الإدارة بما يكفل لأعضائها الحيدة والاستقلالية فى مباشرة أعمالهم .$m259$,'88ce06a821eb213b4c4ce81d8b271794'),
(33,0,$m259$قانون البنك المركزى والجهاز المصرفى 194/2020 > الباب الثانى: البنك المركزى المصرى > الفصل الثالث: إدارة البنك المركزى وحوكمته$m259$,$m259$تكون مساءلة العاملين بالبنك المركزى أمام مجلس تأديب يشكل من :
أحد نائبى المحافظ يختاره مجلس الإدارة (رئيساً) .
اثنين من نواب رئيس مجلس الدولة ، يختارهما المجلس الخاص لمجلس الدولة .
وفى حالة غياب رئيس مجلس التأديب أو وجود مانع لديه يحل محله النائب الآخر وتكون الإحالة إلى مجلس التأديب بقرار من المحافظ .
وتسرى بالنسبة إلى المساءلة أمام مجلس التأديب القواعد الخاصة بالمحاكمة أمام المحاكم التأديبية المنصوص عليها فى قانون مجلس الدولة .
وتكون قرارات مجلس التأديب نهائية ، ويجوز لذوى الشأن الطعن فيها أمام المحكمة الإدارية العليا .$m259$,'2a960f56117652c8e0feecf284ab4316'),
(34,0,$m259$قانون البنك المركزى والجهاز المصرفى 194/2020 > الباب الثانى: البنك المركزى المصرى > الفصل الرابع: النظام المالى للبنك المركزى$m259$,$m259$تبدأ السنة المالية للبنك المركزى ببداية السنة المالية للدولة ، وتنتهى بنهايتها .$m259$,'b9bfd8be03ee1cb246aa68dedeb4b572'),
(35,0,$m259$قانون البنك المركزى والجهاز المصرفى 194/2020 > الباب الثانى: البنك المركزى المصرى > الفصل الرابع: النظام المالى للبنك المركزى$m259$,$m259$يعد البنك المركزى بياناً عن مركزه المالى فى نهاية كل شهر مقارنة بمركزه فى نهاية الشهر السابق ، يعتمد من مجلس الإدارة ، وينشر على الموقع الإلكترونى للبنك المركزى .$m259$,'e53512d32cc8a3640aec60038d56a255'),
(36,0,$m259$قانون البنك المركزى والجهاز المصرفى 194/2020 > الباب الثانى: البنك المركزى المصرى > الفصل الرابع: النظام المالى للبنك المركزى$m259$,$m259$يتولى مراجعة حسابات البنك المركزى اثنان من مراقبى الحسابات ، يعين أحدهما الجهاز المركزى للمحاسبات من بين أعضائه ، ويعين الآخر مجلس الإدارة بناءً على ترشيح لجنة المراجعة من بين المسجلين بسجل مراقبى الحسابات بالبنك المركزى ، وذلك طبقاً للقواعد التى يحددها مجلس الإدارة فى هذا الشأن ، وتحدد أتعابهما بالاتفاق بين البنك المركزى والجهاز المركزى للمحاسبات .
وتتم المراجعة طبقاً لمعايير المراجعة المصرية وطبيعة نشاط البنوك المركزية ، وتقوم مقام مراجعة الجهاز المركزى للمحاسبات .
وعلى البنك المركزى أن يضع تحت تصرف مراقبى الحسابات جميع السجلات والأوراق والبيانات التى يراها المراقبان ضرورية للقيام بالمراجعة للاطلاع عليها .
وإذا ثبت تقصير أى من مراقبى الحسابات فى القيام بالمهام الموكلة إليه ، فللبنك المركزى بالاتفاق مع الجهاز المركزى للمحاسبات تنحيته واتخاذ ما يلزم لمحاسبته عن تقصيره .$m259$,'8dc0e89764b405a98065336a8e2a9ab6'),
(37,0,$m259$قانون البنك المركزى والجهاز المصرفى 194/2020 > الباب الثانى: البنك المركزى المصرى > الفصل الرابع: النظام المالى للبنك المركزى$m259$,$m259$تئول حصيلة الرسوم والجزاءات المالية المقررة طبقاً لأحكام هذا القانون إلى البنك المركزى .$m259$,'bf26a6d382337b128448129d0ae899a1'),
(38,0,$m259$قانون البنك المركزى والجهاز المصرفى 194/2020 > الباب الثانى: البنك المركزى المصرى > الفصل الرابع: النظام المالى للبنك المركزى$m259$,$m259$يعد البنك المركزى موازنته التقديرية متضمنة موازنات الوحدات ذات الطابع الخاص .
ويعتمد مجلس الإدارة الموازنة التقديرية للبنك المركزى قبل بداية السنة المالية بأربعة أشهر .
وترسل نسخة منها إلى وزير المالية .
ولا تشمل الموازنة العامة للدولة الموارد والاستخدامات الجارية والرأسمالية للبنك المركزى .$m259$,'fabd1098d3972b51268190bc7085b700'),
(39,0,$m259$قانون البنك المركزى والجهاز المصرفى 194/2020 > الباب الثانى: البنك المركزى المصرى > الفصل الرابع: النظام المالى للبنك المركزى$m259$,$m259$يعد البنك المركزى خلال ثلاثة أشهر من تاريخ انتهاء السنة المالية ما يأتى :
( أ ) القوائم المالية عن السنة المالية المنتهية والمعدة طبقاً لمعايير المحاسبة المصرية وطبيعة نشاط البنوك المركزية ، ويوقع عليها المحافظ ومراقبا الحسابات .
( ب ) تقرير عن المركز المالى للبنك ، ونتائج أعماله خلال السنة المالية المنتهية يتناول بوجه خاص عرض الأحوال والأوضاع الاقتصادية والمالية والنقدية والمصرفية والائتمانية فى مصر .
وترفع القوائم المالية وتقرير مراقبى الحسابات وتقرير المركز المالى إلى رئيس الجمهورية خلال ثلاثين يوماً من تاريخ اعتمادها من مجلس الإدارة ، وترسل نسخ منها إلى رئيس مجلس النواب ورئيس مجلس الوزراء خلال ذات المدة ، وتنشر على الموقع الإلكترونى للبنك المركزى .$m259$,'0dfbd35077eae6c4dcef7c5f11e7f545'),
(40,0,$m259$قانون البنك المركزى والجهاز المصرفى 194/2020 > الباب الثانى: البنك المركزى المصرى > الفصل الخامس: قواعد الإفصاح$m259$,$m259$يفصح البنك المركزى عن الإجراءات المتخذة لتطبيق السياسة النقدية وقراراته ذات الطبيعة الرقابية والتنظيمية من خلال نشراته الرسمية ، وذلك طبقاً للقواعد والمواعيد التى يحددها مجلس الإدارة ، وتنشر هذه الإجراءات والقرارات فى الوقائع المصرية أو على الموقع الإلكترونى للبنك المركزى ، بحسب الأحوال .$m259$,'4bf89830de92836a8067c747dc9e347e'),
(41,0,$m259$قانون البنك المركزى والجهاز المصرفى 194/2020 > الباب الثانى: البنك المركزى المصرى > الفصل الخامس: قواعد الإفصاح$m259$,$m259$يخطر المحافظ مجلس النواب بالإطار العام للسياسة النقدية عند عرض مشروعى قانونى الموازنة العامة للدولة والخطة العامة للتنمية الاقتصادية والاجتماعية . كما يخطر المجلس بأى تعديل يطرأ على هذا الإطار خلال السنة المالية .$m259$,'6ca9d8e03cde16a7ae77cfc8192ac65f'),
(42,0,$m259$قانون البنك المركزى والجهاز المصرفى 194/2020 > الباب الثانى: البنك المركزى المصرى > الفصل الخامس: قواعد الإفصاح$m259$,$m259$يقدم المحافظ إلى رئيس الجمهورية ورئيس مجلس الوزراء تقريراً دورياً كل ثلاثة أشهر يتضمن تحليلاً للتطورات النقدية والائتمانية والمصرفية وأرصدة المديونية الخارجية خلال فترة التقرير ، وذلك بعد اعتماده من مجلس الإدارة .
كما يقدم المحافظ تقريراً سنوياً معتمداً من مجلس الإدارة إلى رئيس الجمهورية ورئيس مجلس النواب ورئيس مجلس الوزراء عن الأوضاع النقدية والائتمانية فى جمهورية مصر العربية ، وذلك خلال ثلاثة أشهر من انتهاء السنة المالية .
وفى حالة وقوع أى حدث من شأنه الإخلال بأهداف البنك المركزى ، يتعين على المحافظ عرض تقرير على رئيس الجمهورية ورئيس مجلس الوزراء متضمناً الأسباب التى أدت إلى ذلك وخطة المعالجة .$m259$,'2f318f8d1221036d3dcd6a5669aaa733'),
(43,0,$m259$قانون البنك المركزى والجهاز المصرفى 194/2020 > الباب الثانى: البنك المركزى المصرى > الفصل السادس: علاقة البنك المركزى بالحكومة$m259$,$m259$يئول صافى أرباح البنك المركزى إلى الخزانة العامة للدولة بعد اقتطاع ما يقرره مجلس الإدارة من زيادة فى رأس المال ، وما يقرر تكوينه من احتياطيات .
وتسدد الأرباح التقديرية كل ثلاثة أشهر ، على أن تتم التسوية بين صافى الأرباح والأرباح التقديرية طبقاً لما تسفر عنه نتيجة النشاط الفعلى فى نهاية السنة المالية .
ويحظر فى جميع الأحوال توزيع أى أرباح غير محققة .$m259$,'5141c0d1911b0ccdd9f1bf1959126f21'),
(44,0,$m259$قانون البنك المركزى والجهاز المصرفى 194/2020 > الباب الثانى: البنك المركزى المصرى > الفصل السادس: علاقة البنك المركزى بالحكومة$m259$,$m259$يعمل البنك المركزى مستشاراً للحكومة ووكيلاً مالياً عنها ، ولها أن تفوضه فى تمثيلها أمام الجهات الدولية والإقليمية .
ويقوم البنك المركزى بمزاولة العمليات المصرفية العائدة للحكومة والأشخاص الاعتبارية العامة ، وكذا التمويل الداخلى والخارجى مع البنوك ومشغلى نظم الدفع والجهات التى يساهم فيها ، وذلك كله طبقاً للشروط والضوابط التى يضعها مجلس الإدارة ، ويمتنع عليه مزاولة هذه العمليات لغيرها .$m259$,'2f093c6dbdb51e7822c30c64c2c10b14'),
(45,0,$m259$قانون البنك المركزى والجهاز المصرفى 194/2020 > الباب الثانى: البنك المركزى المصرى > الفصل السادس: علاقة البنك المركزى بالحكومة$m259$,$m259$يقوم البنك المركزى بأعمال مصرف الحكومة ، ويتقاضى مقابلاً عن الخدمات التى يؤديها لها وللأشخاص الاعتبارية العامة طبقاً للائحة أسعار الخدمات المصرفية الخاصة به التى يحددها مجلس الإدارة ، وذلك بمراعاة الأسعار السائدة فى السوق وبالتنسيق مع وزير المالية .$m259$,'3281617d5cd839f001e50d11107827d3'),
(46,0,$m259$قانون البنك المركزى والجهاز المصرفى 194/2020 > الباب الثانى: البنك المركزى المصرى > الفصل السادس: علاقة البنك المركزى بالحكومة$m259$,$m259$للحكومة أن تعهد إلى البنك المركزى بأن ينوب عنها فى إصدار الأوراق والأدوات المالية بجميع أنواعها وإدارتها وتحديد آجالها ، ويقدم البنك المركزى للحكومة المشورة فى شأنها .
ويحظر عليه التعامل على أدوات الدين الحكومية الصادرة بالعملة المحلية فى السوق الأولية .$m259$,'cb74aea3dc1c8c9ed0bc9e4540a667fa'),
(47,0,$m259$قانون البنك المركزى والجهاز المصرفى 194/2020 > الباب الثانى: البنك المركزى المصرى > الفصل السادس: علاقة البنك المركزى بالحكومة$m259$,$m259$يقدم البنك المركزى تمويلاً للحكومة بناءً على طلبها لتغطية العجز الموسمى فى الموازنة العامة ، على ألا تجاوز قيمة هذا التمويل ( 10% ) من متوسط إيرادات الموازنة العامة فى السنوات الثلاثة السابقة ، وتكون مدة هذا التمويل ثلاثة أشهر قابلة للتجديد لمدد أخرى مماثلة ، ويجب أن يسدد بالكامل خلال اثنى عشر شهراً على الأكثر من تاريخ تقديمه .
وتحدد الشروط الخاصة بهذا التمويل بالاتفاق بين البنك المركزى ووزارة المالية على أساس أسعار العائد السائدة بالسوق .$m259$,'653f25ee558bf5c28fcb2f24804f37f9'),
(48,0,$m259$قانون البنك المركزى والجهاز المصرفى 194/2020 > الباب الثانى: البنك المركزى المصرى > الفصل السادس: علاقة البنك المركزى بالحكومة$m259$,$m259$مع عدم الإخلال بالاختصاصات المقررة للبنك المركزى ، يشكل بقرار من رئيس الجمهورية مجلس تنسيقى يضع آلية للتنسيق بين السياسة النقدية للبنك المركزى والسياسة المالية للحكومة .
ويضم المجلس فى عضويته ممثلين عن الحكومة والبنك المركزى وغيرهم من ذوى الخبرة ، ويتضمن القرار الصادر بتشكيل المجلس نظام عمله .
وينعقد المجلس مرة على الأقل كل ثلاثة أشهر وكلما دعت الحاجة إلى ذلك ، ويرفع تقريراً سنوياً عن أعماله إلى رئيس الجمهورية .$m259$,'7410859ad776b655dad5aac70a73e847'),
(49,0,$m259$قانون البنك المركزى والجهاز المصرفى 194/2020 > الباب الثانى: البنك المركزى المصرى > الفصل السادس: علاقة البنك المركزى بالحكومة$m259$,$m259$تشكل لجنة للاستقرار المالى ، برئاسة رئيس مجلس الوزراء ، وعضوية كل من :
المحافظ نائباً للرئيس .
وزير المالية .
رئيس الهيئة العامة للرقابة المالية .
وتهدف اللجنة إلى الحفاظ على استقرار النظام المالى فى الدولة من خلال تنسيق الجهود لتجنب حدوث أى أزمة مالية وإدارتها فى حالة حدوثها ، وذلك كله دون الإخلال بالاختصاصات المخولة قانوناً لكل جهة .
وللجنة أن تستعين بمن تراه فى مباشرة أعمالها .
وتنعقد اللجنة مرة على الأقل كل ثلاثة أشهر وكلما دعت الحاجة إلى ذلك ، وترفع تقريراً سنوياً عن أعمالها لرئيس الجمهورية ورئيس مجلس النواب ومجلس الوزراء .$m259$,'4f6e2ebcd8fe378d80855538e3af3545'),
(50,0,$m259$قانون البنك المركزى والجهاز المصرفى 194/2020 > الباب الثانى: البنك المركزى المصرى > الفصل السادس: علاقة البنك المركزى بالحكومة$m259$,$m259$مع عدم الإخلال بالاختصاصات المخولة قانوناً للبنك المركزى ، يشكل المجلس القومى للمدفوعات بقرار من رئيس الجمهورية ، ويهدف إلى خفض استخدام أوراق النقد ، ودعم وتحفيز استخدام الوسائل والقنوات الإلكترونية فى الدفع بديلاً عنه تعزيزاً للشمول المالى ولدمج أكبر عدد من المواطنين فى النظام المالى .
ويرأس هذا المجلس رئيس الجمهورية ، ويضم فى عضويته رئيس مجلس الوزراء والمحافظ وممثلين عن الحكومة والبنك المركزى وعدداً من الأعضاء من ذوى الخبرة والجهات ذات الصلة ، ويصدر بنظام العمل به قرار من رئيس الجمهورية .
وينعقد المجلس مرة على الأقل كل ثلاثة أشهر وكلما دعت الحاجة إلى ذلك .
ويكون للمجلس أمانة فنية برئاسة المحافظ ، تتولى على الأخص إعداد جدول أعماله ومحاضر جلساته وتعميم ما يصدر عنه من قرارات وتوصيات ، ومتابعة تنفيذها ، ويصدر بتشكيل الأمانة الفنية ونظام عملها قرار من المحافظ .$m259$,'4761132dbef5bcdd887501608ee447be'),
(51,0,$m259$قانون البنك المركزى والجهاز المصرفى 194/2020 > الباب الثانى: البنك المركزى المصرى > الفصل السادس: علاقة البنك المركزى بالحكومة$m259$,$m259$مع عدم الإخلال بالاختصاصات المخولة قانوناً للبنك المركزى ، تشكل لجنة برئاسة رئيس مجلس الوزراء وعضوية المحافظ ووزير المالية وممثلين عن كل من البنك المركزى ووزارة المالية بهدف التشاور ودراسة العلاقات البينية بين البنك المركزى ووزارة المالية ، ووضع خطط لفض التشابكات المالية بين الجهتين .
وتنعقد اللجنة مرة على الأقل كل ثلاثة أشهر وكلما دعت الحاجة إلى ذلك .
ويصدر بنظام عمل اللجنة وتشكيل أمانتها الفنية قرار من رئيس مجلس الوزراء .$m259$,'87fe3e13b87794edc29e0d64922975c2'),
(52,0,$m259$قانون البنك المركزى والجهاز المصرفى 194/2020 > الباب الثانى: البنك المركزى المصرى > الفصل السابع: تعاون البنك المركزى مع الجهات الأجنبية المناظرة$m259$,$m259$للبنك المركزى ، فى إطار ممارسته لاختصاصاته ، إبرام بروتوكولات تعاون أو مذكرات تفاهم أو اتفاقات مع الجهات الأجنبية المناظرة بهدف التنسيق والتعاون وتبادل المعلومات فى شأن أى من المسائل الآتية :
( أ ) تبادل المعلومات فى الموضوعات التى يتفق عليها مع هذه الجهات ، ويشمل ذلك المعلومات المتعلقة بالتراخيص وتغييرات الملكية والرقابة المشتركة والجزاءات وإجراءات التدخل المبكر وتسوية أوضاع البنوك المتعثرة ونظم وخدمات الدفع .
( ب ) السماح للجهات الأجنبية المناظرة بالتفتيش على أى من فروع البنوك الأجنبية أو البنوك التابعة لها المسجلة لدى البنك المركزى ، أو السماح للبنك المركزى بالتفتيش على أحد الفروع أو البنوك التابعة لأحد البنوك المصرية فى الخارج .
( جـ ) التنسيق المشترك أو الإخطار المسبق قبل اتخاذ أى إجراء قد يؤثر على أى بنك تحت رقابة وإشراف السلطة الرقابية الأخرى .
( د ) تنسيق الإجراءات الرقابية وإجراءات تسوية الأوضاع بالنسبة للبنوك الأجنبية أو فروعها المسجلة لدى البنك المركزى أو البنوك المصرية أو فروعها العاملة فى الخارج ، وآلية الاعتداد ودعم الإجراءات المتخذة قبل أى منها .
وذلك كله بشرط التأكد من أن آلية معاملة المعلومات السرية فى الجهة المطلوب تبادل المعلومات معها تتفق مع ضوابط السرية المنصوص عليها فى هذا القانون .$m259$,'8362bc9775f61d4a999f7ae55406dadc'),
(53,0,$m259$قانون البنك المركزى والجهاز المصرفى 194/2020 > الباب الثانى: البنك المركزى المصرى > الفصل السابع: تعاون البنك المركزى مع الجهات الأجنبية المناظرة$m259$,$m259$للبنك المركزى المشاركة فى المجموعات الرقابية أو مجموعات تسوية أوضاع البنوك المتعثرة التى تشكلها الجهات الأجنبية المناظرة . كما يحق له تشكيل تلك المجموعات للبنوك المصرية التى لديها فروع أو بنوك تابعة فى الخارج .$m259$,'834b3d515738f71b7c99091ebdca83f0'),
(54,0,$m259$قانون البنك المركزى والجهاز المصرفى 194/2020 > الباب الثانى: البنك المركزى المصرى > الفصل السابع: تعاون البنك المركزى مع الجهات الأجنبية المناظرة$m259$,$m259$يلتزم البنك المركزى باستخدام المعلومات التى يحصل عليها من الجهات الأجنبية المناظرة فى الغرض المتفق عليه ، مع ضمان عدم إفشائها لأى طرف إلا بموافقة مسبقة من هذه الجهات ، أو للدفاع عن البنك المركزى فى أى دعوى قضائية يكون طرفاً فيها طبقاً للبند ( ح ) من المادة ( 143 ) من هذا القانون .
ويتعين على البنك المركزى التحقق من أن المعلومات المتبادلة ستستخدم فى الأغراض المتفق عليها ، وأنه لن يتم استخدامها فى أى غرض آخر إلا بعد موافقة كتابية منه .$m259$,'338b59b29a0ede0fe1feccb7435fac2c'),
(55,0,$m259$قانون البنك المركزى والجهاز المصرفى 194/2020 > الباب الثانى: البنك المركزى المصرى > الفصل السابع: تعاون البنك المركزى مع الجهات الأجنبية المناظرة$m259$,$m259$للبنك المركزى التنسيق مع الجهات الأجنبية المناظرة قبل إصدار قرار تسوية أوضاع أى من الفروع أو البنوك الأجنبية العاملة فى مصر فى ضوء التأثير المحتمل لذلك على الجهاز المصرفى بالدولة الأجنبية .$m259$,'153af266ccb5cf182853e872f5965cf8'),
(56,0,$m259$قانون البنك المركزى والجهاز المصرفى 194/2020 > الباب الثانى: البنك المركزى المصرى > الفصل السابع: تعاون البنك المركزى مع الجهات الأجنبية المناظرة$m259$,$m259$للبنك المركزى الاعتداد بقرارات التسوية الصادرة عن جهات أجنبية مناظرة فى شأن فرع أو بنك تابع لبنك أجنبى يعمل فى جمهورية مصر العربية ، أو إصدار قرارات مكملة لها ، بشرط ألا يترتب على ذلك تأثير سلبى على الاستقرار المصرفى أو مصالح المودعين وغيرهم من دائنى الفرع أو البنك فى مصر .$m259$,'5652f6790914a767949e5150030dfe07'),
(57,0,$m259$قانون البنك المركزى والجهاز المصرفى 194/2020 > الباب الثانى: البنك المركزى المصرى > الفصل الثامن: تنظيم إصدار النقد$m259$,$m259$وحدة النقد فى جمهورية مصر العربية هى الجنيه المصرى ، وينقسم إلى مائة قرش .$m259$,'7648ac10bf62b409d4cefd66d90f0bf6'),
(58,0,$m259$قانون البنك المركزى والجهاز المصرفى 194/2020 > الباب الثانى: البنك المركزى المصرى > الفصل الثامن: تنظيم إصدار النقد$m259$,$m259$يكون للبنك المركزى دون غيره حق إصدار النقد وإلغائه ، ويحدد مجلس الإدارة فئات النقد ومواصفاته ، وضوابط وإجراءات إصداره وإلغائه ، ويجب أن تحمل أوراق النقد توقيع المحافظ .$m259$,'654eb89295d1fba504c989e159c0fa1b'),
(59,0,$m259$قانون البنك المركزى والجهاز المصرفى 194/2020 > الباب الثانى: البنك المركزى المصرى > الفصل الثامن: تنظيم إصدار النقد$m259$,$m259$يحظر على أى شخص بخلاف البنك المركزى إصدار أى أوراق أو مسكوكات من أى نوع يكون لها مظهر النقد أو تشبه النقد . كما تحظر إهانة النقد أو تشويهه أو إتلافه أو الكتابة عليه بأى صورة من الصور$m259$,'ca77fe51109ce365a215bb40d91b533c'),
(60,0,$m259$قانون البنك المركزى والجهاز المصرفى 194/2020 > الباب الثانى: البنك المركزى المصرى > الفصل الثامن: تنظيم إصدار النقد$m259$,$m259$يكون للنقد الذى يصدره البنك المركزى قوة إبراء غير محدودة .$m259$,'aff6ce6661b6aad76a39f44e74025f7c'),
(61,0,$m259$قانون البنك المركزى والجهاز المصرفى 194/2020 > الباب الثانى: البنك المركزى المصرى > الفصل الثامن: تنظيم إصدار النقد$m259$,$m259$يجب أن يقابل النقد المصدر بصفة دائمة وبقدر قيمته رصيد مكون من الذهب والنقد الأجنبى والأوراق المالية الأجنبية والسندات والأذون الحكومية المصرية والأجنبية وأى سندات مصرية أخرى تضمنها الحكومة .$m259$,'bf382e2dfdde7863a1e23517d27f0862'),
(62,0,$m259$قانون البنك المركزى والجهاز المصرفى 194/2020 > الباب الثانى: البنك المركزى المصرى > الفصل الثامن: تنظيم إصدار النقد$m259$,$m259$يودع الذهب والنقد الأجنبى والأصول المكونة لغطاء الإصدار فى البنك المركزى بالقاهرة ، أو فى أى من البنوك المسجلة لدى البنك المركزى أو البنوك الأجنبية خارج جمهورية مصر العربية التى يوافق عليها مجلس الإدارة ، ويكون الإيداع باسم البنك المركزى ولحسابه .$m259$,'7dc19faa0a3719f642452ef78ccd7f24'),
(63,0,$m259$قانون البنك المركزى والجهاز المصرفى 194/2020 > الباب الثالث: تنظيم الجهاز المصرفى > الفصل الأول: تراخيص البنوك$m259$,$m259$يحظر على أى شخص ، طبيعى أو اعتبارى ، غير مسجل طبقاً لأحكام هذا الفصل أن يباشر أى عمل من أعمال البنوك ، ويستثنى من ذلك الأشخاص الاعتبارية العامة التى تباشر عملاً من هذه الأعمال فى حدود سند إنشائها .
ويحظر على أى منشأة غير مسجلة طبقاً لأحكام هذا الفصل أن تستعمل كلمة "بنك" أو أى تعبير يماثلها فى أى لغة سواء فى تسميتها الخاصة أو فى عنوانها التجارى أو فى دعايتها إذا كان ذلك من شأنه أن يثير اللبس لدى الجمهور .$m259$,'976860a38d94cd731fbf9b73d3f703ab'),
(64,0,$m259$قانون البنك المركزى والجهاز المصرفى 194/2020 > الباب الثالث: تنظيم الجهاز المصرفى > الفصل الأول: تراخيص البنوك$m259$,$m259$لمجلس الإدارة منح موافقة مبدئية لأى منشأة ترغب فى الترخيص بمزاولة أعمال البنوك عند توافر الشروط الآتية :
( أ ) أن تتخذ شكل شركة مساهمة مصرية ، أو فرع لبنك أجنبى .
( ب ) ألا يقل رأس المال المصدر والمدفوع بالكامل للبنك عن خمسة مليارات جنيه مصرى ، وألا يقل رأس المال المخصص لنشاط فروع البنوك الأجنبية فى جمهورية مصر العربية عن مائة وخمسين مليون دولار أمريكى أو ما يعادلها بالعملات الحرة .
( جـ ) وضوح هيكل الملكية بما يكفل التعرف على المستفيد النهائى والتأكد من مشروعية مصدر الأموال
( د ) ألا يكون الترخيص متعارضاً مع المصلحة الاقتصادية العامة للدولة
( هـ ) ألا يؤدى الترخيص إلى الإخلال بقواعد المنافسة ومنع الممارسات الاحتكارية .
( و ) ألا يكون الاسم التجارى الذى يتخذه البنك مماثلاً أو مشابهاً على نحو يثير اللبس مع اسم بنك آخر أو منشأة أخرى .
( ز ) كفاءة دراسة الجدوى المالية والاقتصادية والمتضمنة بيان الهدف من تأسيسه ، وطبيعة الأنشطة والخدمات التى سيؤديها ، ودراسة للسوق توضح قدرته على تعبئة المدخرات وتوظيفها .
( ح ) أن يتوافر فى ذوى الشأن النزاهة ، وحسن السمعة ، والملاءة المالية .
( ط ) كفاءة ووضوح خطط الرقابة الداخلية والمخاطر والإدارة ونظم العمل والحوكمة والاستراتيجية والسياسة التى ينوى اتباعها فى تصريف شئونه .
وفضلاً عن الشروط المتقدمة ، يشترط فى فرع البنك الأجنبى أو الشركة المساهمة المصرية التابعة لبنك أجنبى ، أن يتمتع المركز الرئيسى للبنك الأجنبى بجنسية محددة ويخضع لرقابة الجهة الأجنبية المناظرة المختصة فى الدولة التى يقع فيها ، وأن توافق تلك السلطة على العمل فى جمهورية مصر العربية ، وأن تطبق مبدأ الرقابة المجمعة ، وأن تبدى عدم ممانعة فى تطبيق مبدأ الرقابة المشتركة مع البنك المركزى .
ويجوز لمجلس الإدارة الاستثناء من الحد الأدنى لرأس المال المشار إليه بالبند ( ب ) من الفقرة الأولى من هذه المادة ، وذلك بالنسبة للبنوك المتخصصة أو البنوك الرقمية .$m259$,'c26c817f87502edf1528f23102bda260'),
(65,0,$m259$قانون البنك المركزى والجهاز المصرفى 194/2020 > الباب الثالث: تنظيم الجهاز المصرفى > الفصل الأول: تراخيص البنوك$m259$,$m259$يقدم ذوو الشأن إلى البنك المركزى طلباً للحصول على موافقة مبدئية للترخيص بمزاولة أعمال البنوك مرفقاً به المستندات التى يصدر بتحديدها قرار من مجلس الإدارة ، وما يفيد سداد مبلغ مليون جنيه رسم فحص الطلب .
ويعرض الطلب على مجلس الإدارة لإصدار قرار فى شأنه خلال تسعين يوماً من تاريخ تقديمه مستوفياً المستندات المطلوبة .
ويتعين اتخاذ الإجراءات اللازمة لتأسيس البنك خلال سنة من تاريخ إخطار ذوى الشأن بقرار مجلس الإدارة بالموافقة المبدئية على التأسيس ، وإلا اعتبرت الموافقة كأن لم تكن ، ويجوز لمجلس الإدارة مد هذه المهلة لمدة أخرى مماثلة .
وفى حالة رفض الطلب ، يخطر الطالب به خلال ثلاثين يوماً من تاريخ صدوره .$m259$,'467f6ff55fc17a4811ac4ee2858bd367'),
(66,0,$m259$قانون البنك المركزى والجهاز المصرفى 194/2020 > الباب الثالث: تنظيم الجهاز المصرفى > الفصل الأول: تراخيص البنوك$m259$,$m259$يقدم طلب ترخيص البنك الصادر له الموافقة المبدئية إلى المحافظ مرفقاً به المستندات التى يصدر بتحديدها قرار من مجلس الإدارة .
ويتعين أخذ موافقة المحافظ قبل تعيين رئيس وأعضاء أول مجلس إدارة للبنك طبقاً لحكم المادة ( 120 ) من هذا القانون .
ويعرض طلب الترخيص على مجلس الإدارة لإصدار قرار فى شأنه خلال ستين يوماً من تاريخ تقديم الطلب مستوفياً المستندات المطلوبة . ويجوز لمجلس الإدارة مد هذه المدة لمدة أخرى مماثلة .
ويلتزم طالب الترخيص بإخطار البنك المركزى فى حالة حدوث أى تغيير فى البيانات المقدمة فى طلب الترخيص .$m259$,'111d00cd465d097ad99be20ab583356d'),
(67,0,$m259$قانون البنك المركزى والجهاز المصرفى 194/2020 > الباب الثالث: تنظيم الجهاز المصرفى > الفصل الأول: تراخيص البنوك$m259$,$m259$يقدم ذوو الشأن إلى البنك المركزى طلباً للحصول على موافقة مبدئية للترخيص بإنشاء فرع لبنك أجنبى فى مصر مرفقاً به المستندات التى يصدر بتحديدها قرار من مجلس الإدارة ، وما يفيد سداد خمسين ألف دولار أمريكى رسم فحص الطلب .
ويعرض طلب الحصول على الموافقة المبدئية لإنشاء الفرع على مجلس الإدارة لإصدار قرار فى شأنه طبقاً لسياسة التعاون التى يتم الاتفاق عليها بين البنك المركزى والجهة الأجنبية المناظرة المختصة فى الدولة التى يقع فيها المركز الرئيسى للبنك الأجنبى التابع له الفرع للتنسيق بينهما فى مجال الرقابة والإشراف ، على أن يتم البت فى الطلب خلال تسعين يوماً من تاريخ تقديمه مستوفياً المستندات المطلوبة ، ويجوز لمجلس الإدارة مد هذه المدة لمدة أخرى مماثلة .
ويتعين اتخاذ الإجراءات اللازمة لإنشاء الفرع خلال ستة أشهر من تاريخ إخطار ذوى الشأن بقرار مجلس الإدارة بالموافقة المبدئية على الإنشاء ، وإلا اعتبرت الموافقة كأن لم تكن .$m259$,'916fedbaf36d6dd0f99c0fed3f17c73e'),
(68,0,$m259$قانون البنك المركزى والجهاز المصرفى 194/2020 > الباب الثالث: تنظيم الجهاز المصرفى > الفصل الأول: تراخيص البنوك$m259$,$m259$يقدم طلب الترخيص بإنشاء فرع لبنك أجنبى فى مصر الصادر له الموافقة المبدئية إلى المحافظ مرفقاً به المستندات التى يصدر بتحديدها قرار من مجلس الإدارة ، على أن تتضمن على الأخص ما يأتى :
( أ ) ضمان غير مشروط من المركز الرئيسى للبنك الأجنبى لجميع الودائع لدى الفرع وحقوق الدائنين وجميع التزامات الفرع الأخرى .
( ب ) تفويض صادر من المركز الرئيسى للبنك الأجنبى باسم المدير المسئول عن الفرع ونائبه ، وما يفيد موافقة المحافظ قبل تعيينهما طبقاً لحكم المادة ( 120 ) من هذا القانون .
ويعرض طلب الترخيص على مجلس الإدارة لإصدار قرار فى شأنه خلال ستين يوماً من تاريخ تقديم الطلب مستوفياً المستندات المطلوبة .
ويلتزم طالب الترخيص بإخطار البنك المركزى فى حالة حدوث أى تغيير فى البيانات المقدمة فى طلب الترخيص .$m259$,'a3ee382c466bd7ebc617d4d1039414dc'),
(69,0,$m259$قانون البنك المركزى والجهاز المصرفى 194/2020 > الباب الثالث: تنظيم الجهاز المصرفى > الفصل الأول: تراخيص البنوك$m259$,$m259$يخطر طالب الترخيص بقرار القبول أو بما يلزم عليه استيفاؤه من مستندات أو بيانات خلال تسعين يوماً من تاريخ تقديم الطلب .
وإذا لم يقم الطالب باستيفاء المطلوب خلال تسعين يوماً من تاريخ الإخطار المشار إليه سقط حقه فى هذا الطلب .
وتنشر القرارات الصادرة من مجلس الإدارة بالترخيص فى الوقائع المصرية على نفقة المرخص له وعلى الموقع الإلكترونى للبنك المركزى .
ويكون رفض طلب الترخيص بقرار من مجلس الإدارة ، ويخطر الطالب به خلال ثلاثين يوماً من تاريخ صدوره .$m259$,'96cf3af104b67908d1e921127b0da332'),
(70,0,$m259$قانون البنك المركزى والجهاز المصرفى 194/2020 > الباب الثالث: تنظيم الجهاز المصرفى > الفصل الأول: تراخيص البنوك$m259$,$m259$يتم تسجيل البنوك وفروع البنوك الأجنبية المرخص لها وفروعها ووكالاتها فى سجل خاص يعد لهذا الغرض بالبنك المركزى وذلك بعد أداء رسم معاينة مقداره خمسمائة ألف جنيه عن المركز الرئيسى ، ومائتان وخمسون ألف جنيه عن كل فرع ، ومائة ألف جنيه عن كل وكالة أو فرع صغير .
وبالنسبة للمقر الرئيسى لفرع البنك الأجنبى يسدد رسم معاينة مقداره خمسة وعشرون ألف دولار أمريكى ، وعشرة آلاف دولار أمريكى عن كل فرع إضافى له ، وخمسة آلاف دولار أمريكى عن كل وكالة أو فرع صغير .
ويتعين الحصول على موافقة المحافظ قبل بدء إنشاء كل فرع أو وكالة وقبل الافتتاح للتعامل .$m259$,'35f6e9ff9b8c0f78804a3ba2ef8f61fd'),
(71,0,$m259$قانون البنك المركزى والجهاز المصرفى 194/2020 > الباب الثالث: تنظيم الجهاز المصرفى > الفصل الأول: تراخيص البنوك$m259$,$m259$للمحافظ بعد موافقة مجلس الإدارة الترخيص للبنوك الأجنبية بفتح مكاتب تمثيل لها فى جمهورية مصر العربية بالشروط الآتية :
( أ ) ألا يكون لها فروع فى جمهورية مصر العربية .
( ب ) أن تكون مراكزها الرئيسية خاضعة للجهة الأجنبية المناظرة المختصة فى الدول التى تقع فيها هذه المراكز ، وأن توافق تلك السلطة على فتح مكتب تمثيل فى جمهورية مصر العربية .
( جـ ) أن يقتصر نشاط مكاتب التمثيل على دراسة الأسواق وفرص الاستثمار ، وتكون حلقة اتصال ما بين المراكز الرئيسية لها فى الخارج والبنوك المسجلة لدى البنك المركزى أو غيرها من الجهات التى تتعامل معها ، وتساهم فى تذليل المشاكل والصعوبات التى قد تواجه البنوك المراسلة لها فى جمهورية مصر العربية .
ولا يجوز لهذه المكاتب أن تمارس أياً من أعمال البنوك أو الأنشطة التجارية بما فى ذلك نشاط الوكلاء التجاريين وأعمال الوساطة المالية .
وتسجل هذه المكاتب بعد قيدها طبقاً لأحكام قانون شركات المساهمة وشركات التوصية بالأسهم والشركات ذات المسئولية المحدودة وشركات الشخص الواحد فى سجل خاص لدى البنك المركزى وذلك طبقاً للإجراءات التى يصدر بتحديدها قرار من مجلس الإدارة بعد أداء رسم تسجيل مقداره ( عشرون ألف دولار أمريكى ) .
ويتعين الحصول على موافقة المحافظ قبل تعيين المدير المسئول عن إدارة مكتب التمثيل ، والتأكد من استيفائه الشروط التى يقررها مجلس الإدارة .
ويحدد مجلس الإدارة رسم رقابة سنوى على هذه المكاتب يسدد خلال شهر يناير من كل عام بما لا يجاوز خمسة آلاف دولار أمريكى .
وتخضع مكاتب التمثيل المشار إليها لرقابة البنك المركزى ، ويكون له حق الاطلاع فى أى وقت على السجلات الخاصة بها ، وطلب البيانات التى تحقق أغراض الرقابة والإشراف عليها .
وعلى مكاتب التمثيل أن تخطر البنك المركزى بأى تعديلات تطرأ على بياناتها المسجلة لديه .
وللمحافظ فى حالة مخالفة أى من هذه المكاتب لشروط الترخيص المنصوص عليها فى هذه المادة توجيه تنبيه ، أو إيقاف النشاط لمدة لا تجاوز سنة ، أو إلغاء الترخيص وشطب القيد من السجل .
وتلتزم مكاتب التمثيل بإخطار البنك المركزى قبل إغلاق المكتب سواء بصورة مؤقتة أو نهائية بثلاثين يوماً على الأقل .
وذلك كله طبقاً للضوابط والإجراءات التى يحددها مجلس الإدارة .$m259$,'0aaa11cd839ede240a4f26dd62f29bf3'),
(72,0,$m259$قانون البنك المركزى والجهاز المصرفى 194/2020 > الباب الثالث: تنظيم الجهاز المصرفى > الفصل الثانى: قواعد التملك فى رءوس أموال البنوك$m259$,$m259$للمصريين ولغيرهم تملك رءوس أموال البنوك دون التقيد بحد أقصى ينص عليه فى أى قانون آخر ، وذلك مع عدم الإخلال بأحكام هذا الفصل .$m259$,'0dbb3cdeb3125abe66d5dbd9626fd09f'),
(73,0,$m259$قانون البنك المركزى والجهاز المصرفى 194/2020 > الباب الثالث: تنظيم الجهاز المصرفى > الفصل الثانى: قواعد التملك فى رءوس أموال البنوك$m259$,$m259$على كل شخص طبيعى أو اعتبارى يملك ما يزيد على ( 5% ) من رأس المال المصدر أو من حقوق التصويت لأى بنك وبما لا يجاوز ( 10% ) منه أن يخطر البنك المركزى بذلك خلال خمسة عشر يوماً على الأكثر من تاريخ إتمام التملك ، طبقاً للنموذج الذى يعتمده المحافظ لهذا الغرض .$m259$,'e71714440dfff150a270c3495747f178'),
(74,0,$m259$قانون البنك المركزى والجهاز المصرفى 194/2020 > الباب الثالث: تنظيم الجهاز المصرفى > الفصل الثانى: قواعد التملك فى رءوس أموال البنوك$m259$,$m259$لا يجوز لأى شخص طبيعى أو اعتبارى وأطرافه المرتبطة أن يتملك ما يزيد على ( 10% ) من رأس المال المصدر أو من حقوق التصويت لأى بنك أو أى نسبة تؤدى إلى السيطرة الفعلية عليه إلا بعد الحصول على موافقة مسبقة من مجلس الإدارة ، وكذلك عند كل زيادة على النسبة المصرح بها .
وفى حالة مخالفة ذلك ، توقف حقوق التصويت وتوزيعات الأرباح الخاصة بالأسهم الزائدة على النسبة المصرح بها ، ويتعين على المخالف التصرف فى النسبة الزائدة خلال ستة أشهر من تاريخ أيلولتها إليه ، وإلا كان للبنك المركزى أن يطلب من الهيئة العامة للرقابة المالية الأمر بتعيين إحدى شركات السمسرة لتولى إجراءات بيع الأسهم المخالفة ، على أن تئول حصيلة البيع للمساهم بعد خصم المصروفات .
ويصدر مجلس الإدارة قواعد الإفصاح فى شأن تملك أسهم البنوك بما يضمن التعرف على المالك الفعلى أو المستفيد النهائى من الأسهم ، وفى حالة مخالفة هذه القواعد يسرى فى شأن الأسهم المخالفة حكم الفقرة الثانية من هذه المادة .$m259$,'b8271a58845ca614ca522355fa8704da'),
(75,0,$m259$قانون البنك المركزى والجهاز المصرفى 194/2020 > الباب الثالث: تنظيم الجهاز المصرفى > الفصل الثانى: قواعد التملك فى رءوس أموال البنوك$m259$,$m259$يجب أن يقدم طلب الموافقة على تملك ما يزيد على ( 10% ) من رأس المال المصدر للبنك أو من حقوق التصويت أو على تملك أى نسبة تؤدى إلى السيطرة الفعلية عليه إلى البنك المركزى قبل موعد إتمام التملك بستين يوماً على الأقل وذلك على النموذج الذى يعتمده المحافظ وطبقاً للشروط والإجراءات التى يحددها مجلس الإدارة ، ويرفق بالطلب تقرير يبين الملاءة المالية لمقدم الطلب ، وسبب تملك الأسهم ، والأهداف التى يرمى إلى تحقيقها منه ، وخططه فى إدارة البنك ، والسياسة التى ينوى اتباعها فى تصريف شئونه ، ونسبة مساهماته وأطرافه المرتبطة فى أى شركة أو منشأة أخرى .
فإذا كان التملك لسبب غير إرادى كالميراث أو الوصية ، أو نتيجة لتخصيص أسهم مطروحة فى اكتتاب عام ، أو نتيجة للاندماج أو الاستحواذ أو التقسيم ، تعين تقديم طلب استمرار التملك خلال ثلاثين يوماً من تاريخ علم الطالب بما آل إليه وأدى لزيادة النسبة .$m259$,'15ca1182efb1ca91d9ea4339f658b488'),
(76,0,$m259$قانون البنك المركزى والجهاز المصرفى 194/2020 > الباب الثالث: تنظيم الجهاز المصرفى > الفصل الثانى: قواعد التملك فى رءوس أموال البنوك$m259$,$m259$إذا تملك شخص وأطرافه المرتبطة بالميراث أو الوصية أكثر من ( 10% ) من رأس المال المصدر لأى بنك أو من حقوق التصويت أو ما يؤدى إلى سيطرته الفعلية على البنك ولم يطلب استمرار تملكه طبقاً لحكم المادة ( 75 ) من هذا القانون ، تعين عليه أن يوفق أوضاعه طبقاً للقواعد التى يحددها مجلس الإدارة خلال مدة لا تجاوز سنة من تاريخ أيلولة هذه الزيادة إليه ، ويجوز لمجلس الإدارة مدها لمدة مماثلة حال تعثر بيع الأسهم خلالها .
ويسرى عليه فى حالة عدم توفيق أوضاعه خلال هذه المدة حكم الفقرة الثانية من المادة ( 74 ) من هذا القانون .$m259$,'b69541c118b39011269d9608d4b2dcae'),
(77,0,$m259$قانون البنك المركزى والجهاز المصرفى 194/2020 > الباب الثالث: تنظيم الجهاز المصرفى > الفصل الثانى: قواعد التملك فى رءوس أموال البنوك$m259$,$m259$يشترط للموافقة على الطلب المنصوص عليه فى المادة ( 75 ) من هذا القانون ما يأتى :
( أ ) وضوح هيكل الملكية لطالب التملك وأطرافه المرتبطة .
( ب ) توافر الملاءة المالية اللازمة لدى طالب التملك لدعم عمليات البنك أو لزيادة رأسماله إذا دعت الحاجة إلى ذلك .
( جـ ) التثبت من مصادر أموال طالب التملك .
( د ) ألا يترتب على قبول الطلب الإخلال بالمنافسة فى السوق المصرفية أو اضطراب العمل بها .
( هـ ) التأكد من أن الأهداف التى يرمى مقدم الطلب إلى تحقيقها منه أو خططه فى إدارة البنك والسياسة التى ينوى اتباعها فى تصريف شئونه لن تؤثر سلباً على إدارة البنك أو تضر بمصالح المودعين .
( و ) أن يتوافر فى طالب التملك الخبرة بالعمل المصرفى ، وألا يكون قد صدر ضده حكم نهائى فى جريمة ماسة بالشرف أو الأمانة أو فى إحدى الجرائم المنصوص عليها فى هذا القانون أو فى قانون مكافحة غسل الأموال الصادر بالقانون رقم 80 لسنة 2002
وإذا كان الطالب بنكاً أجنبياً أو مؤسسة مالية أجنبية فيشترط بالإضافة إلى ما سبق أن يكون خاضعاً لإشراف السلطة الرقابية المختصة فى الدولة التى يقع بها مقره الرئيسى ، وأن تطبق هذه السلطة قواعد الرقابة المجمعة ، وأن تبدى موافقتها على طلب التملك وعدم ممانعتها فى تطبيق مبدأ الرقابة المشتركة مع البنك المركزى .
ويسرى ذلك على المالك المستفيد للأسهم أو شهادات الإيداع الأجنبية ويكون المالك المسجل ملتزماً بتنفيذ هذه الأحكام نيابة عن المالك المستفيد ، وذلك كله طبقاً للشروط والإجراءات التى يحددها مجلس الإدارة .$m259$,'cea9390bbaaa757dcfd94f22fa68ce26'),
(78,0,$m259$قانون البنك المركزى والجهاز المصرفى 194/2020 > الباب الثالث: تنظيم الجهاز المصرفى > الفصل الثانى: قواعد التملك فى رءوس أموال البنوك$m259$,$m259$يخطر صاحب الشأن بقرار قبول أو رفض الطلب المشار إليه فى المادة ( 75 ) من هذا القانون خلال ستين يوماً من تاريخ تقديمه .
وتكون الموافقة سارية لمدة ستة أشهر من تاريخ إبلاغ طالب التملك بها ، وإلا اعتبرت كأن لم تكن ، ويجوز لمجلس الإدارة مد هذه المدة لمدة مماثلة .
وفى حالة صدور قرار برفض استمرار تملك الطالب للنسبة التى آلت إليه بطريق الميراث أو الوصية أو نتيجة لتخصيص أسهم مطروحة فى اكتتاب عام أو نتيجة الإندماج أو الاستحواذ أو التقسيم أو غيرها من الأسباب غير الإرادية يصدر البنك المركزى قراراً يطالبه بالتصرف فيها خلال سنة من تاريخ إخطاره بقرار الرفض إذا كان التملك بالميراث أو الوصية ، وخلال ثلاثة أشهر إذا كان التملك نتيجة اكتتاب عام أو نتيجة الإندماج أو الاستحواذ أو التقسيم أو غيرها من الأسباب غير الإرادية ، ويجوز للبنك المركزى مد هذه المدة لمدة أخرى مماثلة ، ويسرى فى شأنه ، حال عدم تصرفه فيها خلال هذه المدد ، حكم الفقرة الثانية من المادة ( 74 ) من هذا القانون .$m259$,'2b2ddaeace8fa50a08183d6648b75bce'),
(79,0,$m259$قانون البنك المركزى والجهاز المصرفى 194/2020 > الباب الثالث: تنظيم الجهاز المصرفى > الفصل الثانى: قواعد التملك فى رءوس أموال البنوك$m259$,$m259$يلتزم كل شخص طبيعى أو اعتبارى يمتلك وأطرافه المرتبطة نسبة تزيد على ( 10% ) من رأس المال المصدر للبنك أو من حقوق التصويت أو أى نسبة تؤدى إلى السيطرة الفعلية عليه بإخطار البنك المركزى حال انخفاض هذه النسبة عن الحد المرخص له به ، وذلك على النموذج الذى يعتمده المحافظ لهذا الغرض .$m259$,'206b84d2b44eecdbb5ed1cad4b4ab173'),
(80,0,$m259$قانون البنك المركزى والجهاز المصرفى 194/2020 > الباب الثالث: تنظيم الجهاز المصرفى > الفصل الثانى: قواعد التملك فى رءوس أموال البنوك$m259$,$m259$على كل بنك إخطار البنك المركزى فى أى من الحالتين الآتيتين :
( أ ) إذا تملك أى شخص طبيعى أو اعتبارى وأطرافه المرتبطة ما يزيد على ( 5% ) من رأس المال المصدر للبنك أو من حقوق التصويت أو تملك أى نسبة تؤدى إلى السيطرة الفعلية عليه ، وكذلك عند كل زيادة أو نقص بعد ذلك الحد بنسبة ( 1% ) .
( ب ) إذا انخفضت ملكية أى من المساهمين الرئيسيين عن الحد المصرح له بتملكه .$m259$,'3b6e7e6f2ec8c70be1548ae78cd7f148'),
(81,0,$m259$قانون البنك المركزى والجهاز المصرفى 194/2020 > الباب الثالث: تنظيم الجهاز المصرفى > الفصل الثانى: قواعد التملك فى رءوس أموال البنوك$m259$,$m259$تلتزم بورصة الأوراق المالية أو شركة الإيداع والقيد المركزى للأوراق والأدوات المالية ، بحسب الأحوال ، بإخطار البنك المركزى إذا جاوزت ملكية أحد المساهمين وأطرافه المرتبطة نسبة ( 5% ) من رأس المال المصدر للبنك ، وكذلك عند كل زيادة أو نقص بعد ذلك الحد بنسبة ( 1% ) .$m259$,'5d01a1d7f8a5314f6efd6cf7d99ef304'),
(82,0,$m259$قانون البنك المركزى والجهاز المصرفى 194/2020 > الباب الثالث: تنظيم الجهاز المصرفى > الفصل الثانى: قواعد التملك فى رءوس أموال البنوك$m259$,$m259$تلتزم البنوك بإمساك سجل لحملة الأسهم لما يزيد على ( 5% ) من رأس المال المصدر للبنك أو من حقوق التصويت أو أى نسبة تؤدى إلى السيطرة الفعلية عليه وتحديثه بصفة دورية .
ويتعين إخطار البنك المركزى بكل تعديل يطرأ عليه .
وذلك كله طبقاً للقواعد والشروط الصادرة عن مجلس الإدارة .$m259$,'a2330781465ddbbcdc6d211d43dfaae3'),
(83,0,$m259$قانون البنك المركزى والجهاز المصرفى 194/2020 > الباب الثالث: تنظيم الجهاز المصرفى > الفصل الثالث: قواعد الرقابة والإشراف على البنوك$m259$,$m259$تلتزم جميع البنوك بممارسة أعمالها طبقاً للمبادئ الآتية :
( أ ) الالتزام بأحكام القوانين واللوائح والقرارات والتعليمات السارية وسياساتها الداخلية ، وإبلاغ البنك المركزى عن أى مخالفات جسيمة تتعلق بأى منها .
( ب ) وضع الاستراتيجيات والنظم الفعالة لإدارة المخاطر ، والحفاظ على أصولها ، وكفاية مواردها المالية وغير المالية ، ووضع الخطط اللازمة للحفاظ على كيانها واستمراره .
( جـ ) مباشرة أعمالها بشفافية وبنزاهة تامة .
( د ) بذل العناية الواجبة طبقاً للأصول والأعراف المصرفية ، وحماية حقوق العملاء .
( هـ ) تطبيق قواعد الحوكمة والرقابة الداخلية ، وخطط التعاقب الوظيفى ، وتعزيز المنافسة ، وتطوير نظم العمل وبيئته .
( و ) التعامل مع البنك المركزى بمصداقية وشفافية .
( ز ) العمل على منع تعارض المصالح ، ووضع الأطر الفعالة لإدارتها .$m259$,'ac7351bcdd31753519a5c1891ee1de52'),
(84,0,$m259$قانون البنك المركزى والجهاز المصرفى 194/2020 > الباب الثالث: تنظيم الجهاز المصرفى > الفصل الثالث: قواعد الرقابة والإشراف على البنوك$m259$,$m259$يضع مجلس الإدارة قواعد للرقابة والإشراف على البنوك والضوابط المرتبطة بأنشطتها ، وله فرض معايير أو ضوابط أو قواعد محددة على أى بنك حال توافر ظروف تستدعى ذلك ، وذلك طبقاً لأحكام هذا القانون ، على أن تتضمن بوجه خاص :
( أ ) تحديد الحد الأدنى لمعيار كفاية رأس المال ومكوناته وطرق حسابه ، وكذا نسبة الحد الأدنى للرافعة المالية ومكوناتها .
( ب ) الحدود القصوى لتركز توظيفات البنوك .
( جـ ) الحدود القصوى لمديونية البنك للخارج والضمانات المقدمة عن تمويل يؤدى فى الخارج .
( د ) الحدود القصوى للنسبة التسليفية للضمانات المقدمة مقابل التمويل والتسهيلات الائتمانية ، وتحديد آجال الاستحقاق .
( هـ ) تحديد نسبة الاحتياطى ومكوناتها .
( و ) الحدود القصوى لاستثمارات البنك فى الأوراق والأدوات المالية وفى التمويل العقارى والائتمان لأغراض استهلاكية ، وذلك مع مراعاة حكم البند ( جـ ) من المادة ( 87 ) من هذا القانون .
( ز ) الحدود القصوى لتركز العملات .
( ح ) ضوابط فتح الحسابات ، ومزاولة العمليات المصرفية ، وتقديم المنتجات المصرفية .
( ط ) المعايير التى تتبع فى تحديد قيمة كل نوع من أنواع أصول البنك .
( ى ) قواعد حوكمة البنوك ، وعلى الأخص القواعد المتعلقة بتحديد مسئوليات والتزامات مجلس إدارة البنك ولجانه ، وتعزيز استقلالية أعضائه ، وتحديد آلية تقييم الأداء ، ونظام المكافآت ، وخطط التعاقب الوظيفى .
( ك ) ميثاق سلوك العمل المصرفى ، وقواعد الأصول المهنية .
( ل ) نظم الرقابة الداخلية وإدارة المخاطر .
( م ) معايير تطبيق الرقابة المجمعة .
( ن ) قواعد الإفصاح ، وإعداد القوائم المالية المستقلة والمجمعة ، والبيانات الواجب نشرها وكيفية النشر ووسائله .
( س ) شروط الجدارة والصلاحية الفنية الواجب توافرها فى المسئولين الرئيسيين .
( ع ) القواعد الخاصة بالحد الأقصى للسندات التى يجوز لكل بنك إصدارها أو ضمانها ، وشروط الإصدار أو الضمان .
( ف ) الحدود القصوى للتوظيف لدى العميل الواحد والأطراف المرتبطة به وذلك مع مراعاة حكم المادة ( 98 ) من هذا القانون .
( ص ) ضوابط تعامل البنوك مع أطرافها المرتبطة .
( ق ) قواعد تقييم طلبات تملك أسهم البنوك .
( ر ) نظام الإبلاغ عن المخالفات وحماية المبلغين .
( ش ) شروط وقواعد إصدار البنوك لشهادات الإيداع الأجنبية .
( ت ) شروط وقواعد إصدار البنوك للأوراق والأدوات المالية وإبرام العقود المالية والتعامل عليهما وذلك دون التقيد بحكم المادة ( 465 ) من القانون المدنى .$m259$,'d899872865da0fbab4ea81ea13d6dfb8'),
(85,0,$m259$قانون البنك المركزى والجهاز المصرفى 194/2020 > الباب الثالث: تنظيم الجهاز المصرفى > الفصل الثالث: قواعد الرقابة والإشراف على البنوك$m259$,$m259$يضع مجلس الإدارة القواعد التى تنظم معدلات السيولة فى البنوك ومجالات الاستثمار ، وله على الأخص ما يأتى :
( أ ) تحديد المجالات التى يمتنع على البنوك الاستثمار فيها .
( ب ) تحديد المخصصات الواجب توافرها لمقابلة الأصول المعرضة لتقلبات مؤثرة فى قيمتها .
( جـ ) تحديد نسب السيولة التى يجب أن تحتفظ بها البنوك وأنواعها ومكوناتها .
وإذا خالف أى بنك قرارات مجلس الإدارة فى شأن قواعد حساب نسب السيولة ، جاز لمجلس الإدارة أن يقرر خصم مبلغ من رصيد البنك المخالف لديه لا يجاوز مثلى قيمة العائد من العجز فى نسب السيولة وذلك طبقاً لأسعار العائد الأساسية لدى البنك المركزى عن الفترة التى حدث خلالها العجز .
وإذا استمر العجز مدة تجاوز شهراً ، جاز لمجلس الإدارة أن يتخذ أياً من الإجراءات أو الجزاءات المنصوص عليها فى المادة ( 144 ) من هذا القانون .$m259$,'b3dea8c470c5349d50adfa43eac9d1d0'),
(86,0,$m259$قانون البنك المركزى والجهاز المصرفى 194/2020 > الباب الثالث: تنظيم الجهاز المصرفى > الفصل الثالث: قواعد الرقابة والإشراف على البنوك$m259$,$m259$يضع مجلس الإدارة المعايير الواجب التزام البنوك بها فى تصنيف ما تقدمه من تمويل وتسهيلات ائتمانية ، وفى تصنيف غير المنتظم منها ، والأرصدة الناتجة عن هذا التصنيف .
كما يُحدد كل بنك الإجراءات التى يجب اتخاذها لمعالجة التمويل والتسهيلات الائتمانية غير المنتظمة .
وعلى إدارة كل بنك الالتزام بهذه المعايير وتنفيذ هذه الإجراءات ، كما يلتزم مراقبو الحسابات بالتأكد من اتباع إدارة البنك المعايير المشار إليها ، وعليهم تسجيل ذلك فى تقريرهم السنوى الذى يُعرض مع القوائم المالية للبنك على جمعيته العامة ، وكذا فى التقارير ربع السنوية .
فإذا ثبت للبنك المركزى من التقارير الرقابية مخالفة إدارة البنك لأى من تلك المعايير ، وجب إنذارها لإزالة المخالفة خلال ثلاثين يوماً من تاريخ الإنذار ، وإلا كان لمجلس الإدارة أن يتخذ ما يراه قبل البنك من الإجراءات أو الجزاءات المنصوص عليها فى المادتين ( 144 ، 147 ) من هذا القانون .
ويجب أن يُعرض على مجلس الإدارة تقرير كل ستة أشهر عما يرد إلى البنك المركزى من البنوك عن التمويل والتسهيلات الائتمانية غير المنتظمة .$m259$,'7bc1213a1d0498ea27326bc311eb9aa4'),
(87,0,$m259$قانون البنك المركزى والجهاز المصرفى 194/2020 > الباب الثالث: تنظيم الجهاز المصرفى > الفصل الثالث: قواعد الرقابة والإشراف على البنوك$m259$,$m259$يُحظر على البنك ما يأتى :
( أ ) إصدار أذون قابلة للدفع لحاملها وقت الطلب .
( ب ) قبول الأسهم التى يتكون منها رأسمال البنك بصفة ضمان للتمويل أو التعامل فى أسهمه مع مراعاة أحكام قانون شركات المساهمة وشركات التوصية بالأسهم والشركات ذات المسئولية المحدودة وشركات الشخص الواحد الصادر بالقانون رقم 159 لسنة 1981 فى هذا الشأن ما لم تكن قد آلت إلى البنك وفاء لدين له قبل الغير ، على أن يقوم البنك ببيعها خلال ستة أشهر من تاريخ أيلولة الملكية .
( جـ ) تجاوز القيمة الاسمية للحصص أو للأسهم التى يملكها البنك لغير أغراض المتاجرة مقدار القاعدة الرأسمالية للبنك .
( د ) الدخول كشريك متضامن فى شركات الأشخاص والتوصية بالأسهم .
( هـ ) التعامل فى المنقول أو العقار بالشراء أو البيع أو المقايضة عدا :
1 - العقار المخصص لإدارة أعمال البنك أو للخدمات الاجتماعية أو الصحية للعاملين به .
2 - المنقول أو العقار الذى يئول إلى البنك وفاء لدين له قبل الغير ، على أن يقوم البنك بالتصرف فيه خلال سنة من تاريخ الأيلولة بالنسبة للمنقول وخمس سنوات بالنسبة للعقار ، ولمجلس الإدارة مد المدة إذا اقتضت الظروف ذلك بالشروط التى يحددها ، وله استثناء بعض البنوك من هذا الحظر طبقاً لطبيعة نشاطها .
( و ) منح تسهيلات ائتمانية لشراء أسهم رأسماله .$m259$,'31445859666a515fb1c958faa62ab7bf'),
(88,0,$m259$قانون البنك المركزى والجهاز المصرفى 194/2020 > الباب الثالث: تنظيم الجهاز المصرفى > الفصل الثالث: قواعد الرقابة والإشراف على البنوك$m259$,$m259$لكل بنك سلطة تحديد معدلات العائد عن العمليات المصرفية التى يقوم بها حسب طبيعة هذه العمليات ، كما يكون له أن يُحدد أسعار الخدمات التى يتعامل بها ، وذلك دون التقيد بالحدود والأحكام المنصوص عليها فى أى قانون آخر ، وذلك بما لا يخل بسلامة المركز المالى للبنك ، أو بقواعد المنافسة ، أو يؤدى إلى ممارسات احتكارية .
ويجب على البنك فى جميع الأحوال الإفصاح للعميل عن معدلات العائد الفعلية وأسعار الخدمات المصرفية طبقاً لقواعد الإفصاح التى يحددها مجلس الإدارة .$m259$,'bef8ea2aa523fb82db111b9c6458c816'),
(89,0,$m259$قانون البنك المركزى والجهاز المصرفى 194/2020 > الباب الثالث: تنظيم الجهاز المصرفى > الفصل الثالث: قواعد الرقابة والإشراف على البنوك$m259$,$m259$على كل بنك أن يحتفظ لدى البنك المركزى برصيد دائن كاحتياطى ، وذلك بنسبة مما لدى البنك من الودائع يحددها مجلس الإدارة .
ولمجلس الإدارة أن يقرر تقديم عائد على هذا الرصيد فى الأحوال التى يراها وبالضوابط التى يضعها .
وإذا خالف أى بنك قرارات مجلس الإدارة فى شأن قواعد حساب نسبة الاحتياطى ، جاز لمجلس الإدارة أن يخصم مبلغاً من رصيد البنك الدائن لدى البنك المركزى يعادل قيمة سعر العائد الأساسى لديه على قيمة العجز فى الرصيد الدائن عن الفترة التى حدث خلالها هذا العجز .
وإذا جاوز العجز ( 5% ) مما يجب أن يكون عليه الرصيد ، جاز لمجلس الإدارة أن يتخذ أياً من الإجراءات أو الجزاءات المنصوص عليها فى المادة ( 144 ) من هذا القانون بالإضافة إلى خصم المبلغ المشار إليه فى الفقرة الثالثة من هذه المادة .$m259$,'123a275d809d90245935e249a2b674e1'),
(90,0,$m259$قانون البنك المركزى والجهاز المصرفى 194/2020 > الباب الثالث: تنظيم الجهاز المصرفى > الفصل الثالث: قواعد الرقابة والإشراف على البنوك$m259$,$m259$على كل بنك القيام بتقييم ربع سنوى على الأقل لجميع المخاطر لديه ، وعلى الأخص مخاطر استثماراته ومحفظة الائتمان وما تم من إجراءات فى شأنها ، وعليه اتخاذ ما يلزم من الإجراءات لمواجهة ما يستجد من مخاطر ، ويعرض التقييم على لجنة المخاطر ، ويعتمد من مجلس إدارته فى أول اجتماع تال لهذا التقييم .$m259$,'b6617c79b48ff4a2eda231453e7e0c13'),
(91,0,$m259$قانون البنك المركزى والجهاز المصرفى 194/2020 > الباب الثالث: تنظيم الجهاز المصرفى > الفصل الثالث: قواعد الرقابة والإشراف على البنوك$m259$,$m259$يجب أن يكون للبنك أصول فى جمهورية مصر العربية تعادل مقدار التزاماته مستحقة الأداء فيها ، علاوة على مبلغ لا يقل عن الحد الأدنى لرأس المال المصدر والمدفوع المنصوص عليه فى المادة ( 64 ) من هذا القانون .
وفى تطبيق أحكام هذه المادة ، يدخل فى حساب أصول البنك فى جمهورية مصر العربية ما يسمح له بالاحتفاظ به من أموال فى الخارج بموافقة مجلس الإدارة .$m259$,'7d7b2bf22a3c5912dc36bd18facabb9c'),
(92,0,$m259$قانون البنك المركزى والجهاز المصرفى 194/2020 > الباب الثالث: تنظيم الجهاز المصرفى > الفصل الثالث: قواعد الرقابة والإشراف على البنوك$m259$,$m259$يجب إخطار البنك المركزى بكل تعديل يراد إجراؤه فى عقد التأسيس أو فى النظام الأساسى لأى بنك قبل عرضه على الجمعية العامة ، كما يجب الإخطار بكل تعديل فى البيانات التى قدمت عند طلب الترخيص .
ويقدم الإخطار طبقاً للنموذج الذى يعتمده المحافظ لهذا الغرض ، ولا يجوز أن يعرض طلب التعديل على الجمعية العامة إلا بعد الحصول على موافقة مبدئية من البنك المركزى ، ولا يعمل بهذا التعديل إلا بعد موافقة الجمعية العامة عليه واعتماده من مجلس الإدارة والتأشير به فى السجل المعد لهذا الغرض .$m259$,'2ed26102fc2faf7afe402c7dcfc741b9'),
(93,0,$m259$قانون البنك المركزى والجهاز المصرفى 194/2020 > الباب الثالث: تنظيم الجهاز المصرفى > الفصل الثالث: قواعد الرقابة والإشراف على البنوك$m259$,$m259$يُحدد مجلس الإدارة رسم رقابة سنوى على البنوك ، تسدده خلال شهر يناير من كل عام ، على ألا يجاوز جنيهين عن كل عشرة آلاف جنيه من متوسط إجمالى المراكز الشهرية للبنك خلال العام .
وفى حالة التأخر فى السداد ، يستحق عائد يحسب طبقاً لأسعار العائد الأساسية لدى البنك المركزى .$m259$,'ba3ae51732eeacdfc36de87663850547'),
(94,0,$m259$قانون البنك المركزى والجهاز المصرفى 194/2020 > الباب الثالث: تنظيم الجهاز المصرفى > الفصل الثالث: قواعد الرقابة والإشراف على البنوك$m259$,$m259$يقدم كل بنك إلى البنك المركزى خطة تتضمن مجموعة من الافتراضات لإدارة أحداث جسيمة قد تقع فى النظام المصرفى أو على البنك ، واحتمالات تعرضه لمشاكل مالية تؤثر على ملاءته المالية أو سيولته أو ربحيته ، والإجراءات التصحيحية اللازمة لاستعادة سلامته المالية حال تحقق أى من تلك الافتراضات ، ويلتزم البنك بتعديل تلك الخطة طبقاً لما يراه البنك المركزى .
ويتعين على كل بنك مراجعة تلك الخطة وتحديثها كل سنتين ، وكلما حدث تغير جوهرى فى أنشطته أو فى هيكله أو فى توظيفاته أو فى الافتراضات المستخدمة فى إعدادها ، وعرضها على البنك المركزى ، وكذا إعداد نظام للتسجيل الفورى والمستمر للعقود المالية التى يكون البنك طرفاً فيها ، وغيرها من العقود التى يحددها البنك المركزى .
ويلتزم مجلس إدارة كل بنك باعتماد تلك الخطة ، وبمراقبة التزام الإدارة التنفيذية بها ومتابعة ذلك .
ولا تخل الخطة المعدة طبقاً لهذه المادة بسلطة البنك المركزى فى اتخاذ أى إجراءات أخرى وفق أحكام هذا القانون .
وذلك كله طبقاً للقواعد والشروط والإجراءات التى يحددها مجلس الإدارة بما يتناسب مع طبيعة نشاط كل بنك وحجمه .$m259$,'70547b03acbb54a869f464bc59c16f87'),
(95,0,$m259$قانون البنك المركزى والجهاز المصرفى 194/2020 > الباب الثالث: تنظيم الجهاز المصرفى > الفصل الثالث: قواعد الرقابة والإشراف على البنوك$m259$,$m259$يضع البنك المركزى خطة لتسوية أوضاع كل بنك فى حالة تعثره وذلك بعد دراسة أوضاعه وتقييم قابليته للتسوية ، دون أن تتضمن تلك الخطة اللجوء إلى الدعم الحكومى أو التمويل الاستثنائى .
وتلتزم البنوك بإزالة أى عوائق تحول دون تنفيذ تلك الخطط ، وتزويد البنك المركزى بأى معلومات يطلبها من البنك أو من الشركة الأم أو الشركات الشقيقة والتابعة للبنك أو من المساهمين الرئيسيين .
وذلك كله على النحو الذى يحدده مجلس الإدارة .$m259$,'49d2ee4b1a44d41f2be1df81966c4f9a'),
(96,0,$m259$قانون البنك المركزى والجهاز المصرفى 194/2020 > الباب الثالث: تنظيم الجهاز المصرفى > الفصل الثالث: قواعد الرقابة والإشراف على البنوك$m259$,$m259$لمجلس الإدارة تحديد الخدمات ذات الأهمية التى تقدم للبنوك من خدمات تعهيد وخدمات تقنية ، وله وضع شروط وإجراءات تسجيل مقدميها بالبنك المركزى ، على أن تتضمن على الأخص تحديد الحد الأدنى الواجب توافره فى شأن متطلبات الحوكمة ، وإدارة المخاطر ، ومعايير أداء الخدمة ، وضوابط الحفاظ على سرية المعلومات التى يطلعون عليها .
ويحظر على البنوك الاستعانة بمقدمى تلك الخدمات من غير المسجلين لدى البنك المركزى ، ويكون البنك مسئولاً مسئولية كاملة على تلك الأعمال .$m259$,'b212b078f4001cd1e5adf7c20c67b9db'),
(97,0,$m259$قانون البنك المركزى والجهاز المصرفى 194/2020 > الباب الثالث: تنظيم الجهاز المصرفى > الفصل الثالث: قواعد الرقابة والإشراف على البنوك$m259$,$m259$يجوز لأى بنك ، بموافقة مسبقة من مجلس الإدارة ، الاندماج فى بنك آخر أو الاندماج معه لتكوين بنك جديد ، أو الانقسام لتكوين بنكين أو أكثر ، وذلك بعد استيفاء الشروط والإجراءات التى يصدر بتحديدها قرار من مجلس الإدارة ، مع مراعاة ضمان حقوق العاملين بالبنوك المندمجة أو المنقسمة ، وتأثير الاندماج أو الانقسام على المنافسة بالجهاز المصرفى .
ويضع مجلس الإدارة القواعد التى يلزم اتباعها لإعداد تقارير الفحص النافى للجهالة لأى من البنوك ، وكذا القواعد المنظمة لإجراءات الدمج والاستحواذ والانقسام الخاصة بالبنوك وأسهمها .
ويترتب على الاندماج أو الانقسام إلغاء الترخيص وشطب تسجيل البنوك المندمجة أو المنقسمة بحسب الأحوال ، وتنشر قرارات الإلغاء والشطب فى الوقائع المصرية وكذلك على الموقع الإلكترونى لكل من البنك المركزى والبنوك المعنية خلال عشرة أيام من تاريخ صدور قرار الاندماج أو الانقسام .$m259$,'9390e1785c2eabada070dfdb3d572a78'),
(98,0,$m259$قانون البنك المركزى والجهاز المصرفى 194/2020 > الباب الثالث: تنظيم الجهاز المصرفى > الفصل الرابع: قواعد تقديم ومنح الائتمان لعملاء البنوك$m259$,$m259$لمجلس الإدارة فى الحالات التى يرى فيها ضرورة لذلك تحديد نسبة التوظيف التى يقدمها أى بنك للعميل الواحد والأطراف المرتبطة به ، على ألا تجاوز هذه النسبة ( 30% ) من القاعدة الرأسمالية للبنك .$m259$,'a19449c7a81e55791868aae5eea83a49'),
(99,0,$m259$قانون البنك المركزى والجهاز المصرفى 194/2020 > الباب الثالث: تنظيم الجهاز المصرفى > الفصل الرابع: قواعد تقديم ومنح الائتمان لعملاء البنوك$m259$,$m259$يضع مجلس إدارة البنك قواعد الائتمان لعملائه ، والإجراءات التى تتبع للتأكد من الجدارة الائتمانية وصحة المعلومات المقدمة ، وإجراءات إتاحة هذا الائتمان ، ونظام الرقابة على استخدامه .
وتحدد السياسة الائتمانية لكل بنك سلطات منح الائتمان والموافقة عليه .
وفى جميع الأحوال ، لا يجوز منح صلاحيات ائتمانية لمجالس إدارات البنوك .
ويعرض على مجلس إدارة البنك بصفة دورية تقارير وافية عن موقف المحفظة الائتمانية للبنك .
وذلك كله طبقاً لضوابط منح الائتمان الصادرة عن مجلس الإدارة .$m259$,'80fd37aa790c4d6b5bb68510616a3c94'),
(100,0,$m259$قانون البنك المركزى والجهاز المصرفى 194/2020 > الباب الثالث: تنظيم الجهاز المصرفى > الفصل الرابع: قواعد تقديم ومنح الائتمان لعملاء البنوك$m259$,$m259$على من يطلب الحصول على تمويل أو تسهيلات ائتمانية من البنوك من بين الأشخاص الطبيعيين والأشخاص الاعتبارية أن يفصح فى الطلب عن أصحاب المنشأة أو أصحاب الحصص أو نسبة المساهمة فى شركات المساهمة ودرجة القرابة بينهم إن وجدت ، وأرصدة المديونية لدى البنوك الأخرى عند تقديم الطلب ، ولا يجوز النظر فى الطلب إلا بعد تقديم هذه البيانات ، والإقرار بصحتها .
وعلى البنك بذل العناية الواجبة للتحقق من صحة هذه البيانات .$m259$,'c3e8090cf20d6cfcddd92326fa7aa53f'),
(101,0,$m259$قانون البنك المركزى والجهاز المصرفى 194/2020 > الباب الثالث: تنظيم الجهاز المصرفى > الفصل الرابع: قواعد تقديم ومنح الائتمان لعملاء البنوك$m259$,$m259$يشترط لتقديم الائتمان للعميل أن يكون حسن السمعة ، ولديه موارد ذاتية كافية ، وأن تثبت الدراسات كفاية التدفقات النقدية المتوقعة لأنشطته للوفاء بالتزاماته الحالية والمستقبلية ، وغيرها من متطلبات الجدارة الائتمانية التى يصدر بتحديدها قرار من مجلس الإدارة .
وللبنك فى الأحوال التى يقدرها أن يطلب من العميل تقديم ضمانات إضافية سواء عينية أو من أى طبيعة أخرى يقبلها البنك .
ويحدد مجلس الإدارة معايير تقييم الضمانات التى تقدم للبنك عما يمنحه للعميل من التمويل والتسهيلات الائتمانية ، والضوابط اللازمة لتطبيق أحكام هذه المادة .
ولا يجوز تجديد ائتمان أو تعديله قبل إقرار العميل بصحة أرصدة التمويل والتسهيلات الائتمانية المقدمة له من البنك .$m259$,'6b156ac05604f199391186f7a92bec0c'),
(102,0,$m259$قانون البنك المركزى والجهاز المصرفى 194/2020 > الباب الثالث: تنظيم الجهاز المصرفى > الفصل الرابع: قواعد تقديم ومنح الائتمان لعملاء البنوك$m259$,$m259$مع عدم الإخلال بأحكام قانون تنظيم الضمانات المنقولة الصادر بالقانون رقم 115 لسنة 2015 ، يحتفظ كل بنك بسجل للضمانات العينية المقدمة من العملاء عن التمويل والتسهيلات الائتمانية المقدمة لهم ، وعليه أن يتأكد عند تقديم الائتمان من جدية هذه الضمانات ، وسند ملكيتها ، وقيمتها .
وعلى لجنة المخاطر بكل بنك أن تتأكد من قيام الإدارة التنفيذية بالبنك بمراجعة قيم تلك الضمانات دورياً ، وتحديد الإجراءات الواجب اتخاذها لمواجهة أى انخفاض فى هذه القيم .
وتخضع هذه السجلات لرقابة البنك المركزى ، وله أن يطلب تعزيز هذه الضمانات عند الاقتضاء .$m259$,'f436bc318e27f84c3f9adc9682ed3efc'),
(103,0,$m259$قانون البنك المركزى والجهاز المصرفى 194/2020 > الباب الثالث: تنظيم الجهاز المصرفى > الفصل الرابع: قواعد تقديم ومنح الائتمان لعملاء البنوك$m259$,$m259$يعد البنك المركزى سجلاً لقيد بيوت الخبرة المؤهلة للمشاركة فى تقييم الضمانات التى تقدم للبنوك ، ويضع مجلس الإدارة قواعد القيد فى هذا السجل وشروطه وإجراءاته ، ويحدد التزامات بيوت الخبرة .
وتكون هذه البيوت مسئولة عما يرد فى تقارير التقييم .
وإذا ثبت تقصير أى من تلك البيوت فى القيام بالمهام الموكلة له ، جاز لمجلس الإدارة وقف قيده للمدة التى يحددها أو شطبه من السجل وذلك بعد دراسة المبررات المقدمة منه ، وإتخاذ ما يلزم لمحاسبته عن تقصيره .$m259$,'8dbac03fd81e19b81d6c57e18d3a0949'),
(104,0,$m259$قانون البنك المركزى والجهاز المصرفى 194/2020 > الباب الثالث: تنظيم الجهاز المصرفى > الفصل الرابع: قواعد تقديم ومنح الائتمان لعملاء البنوك$m259$,$m259$على كل بنك التأكد من أن التمويل والتسهيلات الائتمانية تستخدم فى الأغراض والمجالات التى حددت فى الموافقة الائتمانية ، وعليه أن يتابع ذلك .
ويحظر على العميل استخدام التمويل أو التسهيلات الائتمانية فى غير الأغراض أو المجالات التى حددت فى الموافقة الائتمانية .$m259$,'01650525531bf39db12b26e13903a788'),
(105,0,$m259$قانون البنك المركزى والجهاز المصرفى 194/2020 > الباب الثالث: تنظيم الجهاز المصرفى > الفصل الرابع: قواعد تقديم ومنح الائتمان لعملاء البنوك$m259$,$m259$يبلغ البنك كل عميل من عملائه بكشف برصيد حسابه كل ثلاثة شهور على الأكثر .
وعلى العميل أن يرد بالموافقة أو الاعتراض على ما جاء بكشف الحساب خلال ثلاثين يوماً من تاريخ إبلاغه بالرصيد ، فإذا لم يرد العميل خلال هذه المدة بما يفيد اعتراضه ، اعتبر موافقاً على صحة ما ورد بكشف الحساب ما لم يثبت العكس .
ويكون الإبلاغ والرد بكتاب موصى عليه مصحوب بعلم الوصول ، ما لم يتفق الطرفان على أن يكون ذلك بأى من الوسائل المستحدثة طبقاً للضوابط والإجراءات التى يضعها مجلس الإدارة .
ولا يترتب على رفع الدعوى التى يقيمها العميل ضد البنك لتحديد مقدار المبالغ المدين بها وقف أى إجراءات قضائية أو غير قضائية يتخذها البنك لاقتضاء مستحقاته لدى العميل تطبيقاً للاتفاقات المبرمة بينهما وفى حدود المبالغ التى سبقت موافقة العميل عليها ، وذلك ما لم تأمر المحكمة المختصة بوقف هذه الإجراءات .$m259$,'dbe0fe3960a4dff8ab39d051281a9d33'),
(106,0,$m259$قانون البنك المركزى والجهاز المصرفى 194/2020 > الباب الثالث: تنظيم الجهاز المصرفى > الفصل الرابع: قواعد تقديم ومنح الائتمان لعملاء البنوك$m259$,$m259$مع مراعاة أحكام قانون الضمانات المنقولة الصادر بالقانون رقم 115 لسنة 2015 ، يعد عقد الرهن التجارى للمحال التجارية التى تقدم ضماناً للتمويل والتسهيلات الائتمانية المقدمة من أحد البنوك بعد توثيقه سنداً تنفيذياً فى تطبيق أحكام المادة ( 280 ) من قانون المرافعات المدنية والتجارية الصادر بالقانون رقم 13 لسنة 1968 ويجوز رهن المحل التجارى لدى البنوك الأجنبية ومؤسسات التمويل الدولية ضماناً للتمويل والتسهيلات الائتمانية التى يجرى استخدامها فى جمهورية مصر العربية .
وللبنك المركزى أن يرخص للبنوك والبنوك الأجنبية ومؤسسات التمويل الدولية برهن المحال التجارية .$m259$,'92c5e9efffc537cc8c33ed57583f4747'),
(107,0,$m259$قانون البنك المركزى والجهاز المصرفى 194/2020 > الباب الثالث: تنظيم الجهاز المصرفى > الفصل الرابع: قواعد تقديم ومنح الائتمان لعملاء البنوك$m259$,$m259$فى حالة وجود اتفاق يعطى البنك بصفته دائناً مرتهناً الحق فى بيع الأوراق والأدوات المالية المرهونة إذا لم يقم المدين بالوفاء بمستحقات البنك المضمونة بالرهن عند حلول أجلها .
ويجوز للبنك بيع تلك الأوراق والأدوات طبقاً للأحكام المنظمة للتداول أو التعامل على الأوراق أو الأدوات المالية فى البورصة وذلك بعد مضى عشرة أيام عمل من تكليف المدين بالوفاء بموجب ورقة من أوراق المحضرين ودون التقيد بالأحكام المنصوص عليها فى المادتين ( 126 ، 129 ) من قانون التجارة الصادر بالقانون رقم 17 لسنة 1999 والمادة ( 8 ) من قانون سوق رأس المال الصادر بالقانون رقم 95 لسنة 1992$m259$,'1d061ee3ca467aef5f265c5134f84560'),
(108,0,$m259$قانون البنك المركزى والجهاز المصرفى 194/2020 > الباب الثالث: تنظيم الجهاز المصرفى > الفصل الرابع: قواعد تقديم ومنح الائتمان لعملاء البنوك$m259$,$m259$مع عدم الإخلال بأحكام قيد الرهن الرسمى للعقارات والطائرات والسفن والرهن التجارى للمحال التجارية المنصوص عليها فى القوانين المنظمة لها وبأحكام قانون التمويل العقارى الصادر بالقانون رقم 148 لسنة 2001 ، يقدم البنك أو الراهن طلب قيد رهن الأصول العقارية التى تقدم للبنوك والبنوك الأجنبية ومؤسسات التمويل الدولية ضماناً للتمويل والتسهيلات الائتمانية ، سواء كانت مقدمة من المقترض مباشرة أو من كفيله إلى مكتب الشهر العقارى الكائن فى دائرته العقار ، مرفقاً به سند الملكية وشهادة تصرفات عقارية ، ومتضمناً أسماء وبيانات أطراف عقد الرهن ، وبيان التسهيل الائتمانى أو قيمة التمويل وشروطه ، ويقيد الطلب فى سجل خاص يعد لذلك بمكتب الشهر العقارى المختص .
وعلى مكتب الشهر العقارى المختص أن يتحقق من صحة حدود العقار محل الرهن ومواصفاته بعد استيفاء ما يلزم من مستندات من واقع الطلب وسند الملكية .
ويجب البت فى طلب الرهن خلال خمسة عشر يوماً من تاريخ تقديمه مستوفياً المستندات اللازمة .
ولا يجوز رفض طلب القيد إلا بسبب عدم استيفاء المستندات اللازمة لإجراء .
وفى جميع الأحوال ، يجب إخطار الطالب بقبول الطلب أو بقرار رفضه مسبباً خلال سبعة أيام من تاريخ البت فيه ، وذلك بخطاب موصى عليه مصحوب بعلم الوصول .
وتسرى فى شأن التنفيذ على العقار المرهون للبنوك أحكام المواد من ( 12 ) إلى ( 27 ) من قانون التمويل العقارى الصادر بالقانون رقم 148 لسنة 2001 ، وفى حالة عدم بلوغ أكبر عرض قيمة المديونية لا يترتب على إيقاع البيع إبراء ذمة الراهن من التزاماته تجاه البنك ، إلا فى حدود المبلغ المتحصل للبنك من البيع .
وفى جميع الأحوال ، تستوفى رسوم التنفيذ على الأموال المرهونة للبنوك من حصيلة التنفيذ بعد إتمام البيع ، وتحسب نسبتها من حصيلة البيع .$m259$,'4a10b5d25af9cf2754f12c88d50996b5'),
(109,0,$m259$قانون البنك المركزى والجهاز المصرفى 194/2020 > الباب الثالث: تنظيم الجهاز المصرفى > الفصل الرابع: قواعد تقديم ومنح الائتمان لعملاء البنوك$m259$,$m259$مع عدم الإخلال بأحكام الخفض والإعفاء المقررة قانوناً بالنسبة إلى الرسوم على الرهن الرسمى ، تخفض إلى النصف جميع الرسوم المستحقة على الرهون الرسمية والرهون التجارية لما يقدم للبنوك والبنوك الأجنبية ومؤسسات التمويل الدولية ضماناً للتمويل والتسهيلات الائتمانية سواء كانت مقدمة من المقترض مباشرة أو من كفيله وعلى تجديد وتعديل قيمة هذه الرهون أو أى شرط من شروطها وبحيث يكون الحد الأقصى لهذه الرسوم على النحو الآتى :
خمسة وعشرون ألف جنيه فيما لا تجاوز قيمته عشرة ملايين جنيه .
خمسون ألف جنيه فيما لا تجاوز قيمته عشرين مليون جنيه .
خمسة وسبعون ألف جنيه فيما لا تجاوز قيمته ثلاثين مليون جنيه .
مائة ألف جنيه فيما تجاوز قيمته ثلاثين مليون جنيه .
ويعفى شطب تلك الرهون من جميع الرسوم المستحقة .$m259$,'558206aa4c285b4fb4dfe960c75da6c2'),
(110,0,$m259$قانون البنك المركزى والجهاز المصرفى 194/2020 > الباب الثالث: تنظيم الجهاز المصرفى > الفصل الرابع: قواعد تقديم ومنح الائتمان لعملاء البنوك$m259$,$m259$لمجلس الإدارة أن يرخص للشركات بتقديم خدمات ضمان الائتمان ، ويجب أن تتخذ شركة ضمان الائتمان شكل شركة مساهمة مصرية ، وألا يقل رأسمالها المصدر والمدفوع عن خمسين مليون جنيه .
ويحدد مجلس الإدارة بقرار منه قواعد الترخيص وشروطه وإجراءاته ونظام العمل فى شركات ضمان الائتمان ، ونظام رقابة البنك المركزى عليها .
ويعد فى البنك المركزى سجل لقيد تلك الشركات وذلك بعد أداء رسم معاينة مقداره مائة ألف جنيه عن المركز الرئيسى وخمسون ألف جنيه عن كل فرع .
ويحدد مجلس الإدارة رسم رقابة سنوى على هذه الشركات لا يجاوز مائة ألف جنيه تقوم بسداده خلال شهر يناير من كل عام .
ويسرى فى شأن تلك الشركات أحكام المادتين ( 144 ، 145 ) من هذا القانون بما يتناسب مع طبيعتها .$m259$,'086684306f7c50c86ff62e494bea14ab'),
(111,0,$m259$قانون البنك المركزى والجهاز المصرفى 194/2020 > الباب الثالث: تنظيم الجهاز المصرفى > الفصل الخامس: نظام تسجيل الائتمان$m259$,$m259$يدير البنك المركزى نظاماً لتسجيل أرصدة التمويل والتسهيلات الائتمانية المقدمة لعملاء البنوك وجهات منح الائتمان ، وكذلك نظاماً لتسجيل أرصدة مديونية البنوك للخارج والضمانات الصادرة منها لجهات فى الخارج ، ويحفظ فى هذين النظامين المعلومات الضرورية للرقابة على الائتمان المقدم لعملاء البنوك والأطراف المرتبطة بهم والمديونية الخارجية .
وتلتزم البنوك وجهات منح الائتمان بأن تقدم البيانات اللازمة فى هذا الشأن للبنك المركزى .
وذلك كله طبقاً للضوابط والإجراءات التى يحددها مجلس الإدارة ، مع مراعاة التنسيق مع الهيئة العامة للرقابة المالية بالنسبة لجهات منح الائتمان الخاضعة لرقابتها .$m259$,'6d7153182f6ad170e2830819d0fc656f'),
(112,0,$m259$قانون البنك المركزى والجهاز المصرفى 194/2020 > الباب الثالث: تنظيم الجهاز المصرفى > الفصل الخامس: نظام تسجيل الائتمان$m259$,$m259$لمجلس الإدارة أن يرخص للشركات بتقديم خدمات الاستعلام والتصنيف الائتمانى المتعلقة بمديونية عملاء البنوك وشركات التمويل العقارى وشركات التأجير التمويلى وشركات وجمعيات التمويل متناهى الصغر وشركات التمويل الاستهلاكى ومديونية المتقدمين للحصول على تمويل أو تسهيلات ائتمانية من موردى السلع والخدمات ، وغيرها من جهات منح الائتمان التى يصدر بتحديدها قرار من مجلس الإدارة .
ويجب أن تتخذ شركات الاستعلام والتصنيف الائتمانى شكل شركة مساهمة مصرية ، وألا يقل رأسمالها المصدر والمدفوع عن مائتى مليون جنيه .
ويحدد مجلس الإدارة بقرار منه قواعد وشروط وإجراءات الترخيص ونظام العمل فى تلك الشركات ، ونظام رقابة البنك المركزى عليها .
ويحدد مجلس الإدارة رسم رقابة سنوى على شركات الاستعلام والتصنيف الائتمانى لا يجاوز مائة ألف جنيه ، تقوم بسداده خلال شهر يناير من كل عام .
وتسرى على هذه الشركات الأحكام الواردة فى المادتين ( 144 ، 145 ) من هذا القانون ، بما يتناسب مع طبيعتها .
ويعد فى البنك المركزى سجل لقيد تلك الشركات .$m259$,'a063eb300e0c3323c57474bc029977b7'),
(113,0,$m259$قانون البنك المركزى والجهاز المصرفى 194/2020 > الباب الثالث: تنظيم الجهاز المصرفى > الفصل الخامس: نظام تسجيل الائتمان$m259$,$m259$تلتزم البنوك وجهات منح الائتمان بالتسجيل المستمر لمراكز العملاء فور صدور الموافقة على منحهم تمويل أو تسهيلات ائتمانية .
وللبنك المركزى أن يطلب إجراء أى تعديلات تكون لازمة لتحديث هذا النظام ، وضمان شمول بياناته على مراكز العملاء المدينين .
ويجب ربط ذلك النظام بقاعدة المعلومات المجمعة بالبنك المركزى وشركات الاستعلام والتصنيف الائتمانى .
وعلى البنوك وجهات منح الائتمان إبلاغ البنك المركزى وشركات الاستعلام والتصنيف الائتمانى ببيان عن مركز كل عميل يحصل على موافقة لمنحه تسهيلات ائتمانية .
وذلك كله على النحو الذى تحدده القواعد والإجراءات الصادرة عن مجلس الإدارة .$m259$,'0a30135d4a67f607b790d53687a96d1d'),
(114,0,$m259$قانون البنك المركزى والجهاز المصرفى 194/2020 > الباب الثالث: تنظيم الجهاز المصرفى > الفصل الخامس: نظام تسجيل الائتمان$m259$,$m259$تلتزم الجهات والشركات القائمة على إدارة المرافق العامة فى المجالات التى يحددها البنك المركزى بإمداد شركات الاستعلام والتصنيف الائتمانى بالبيانات الخاصة بطالبى الائتمان ، وذلك بغرض تقييم الجدارة الائتمانية لهم وبشرط موافقة طالب الائتمان على ذلك .
ويحدد مجلس الإدارة البيانات المطلوب استيفاؤها من تلك الجهات وطريقة ومواعيد تقديمها .$m259$,'b07a956baf69eb8006460fd7f4f5c3ee'),
(115,0,$m259$قانون البنك المركزى والجهاز المصرفى 194/2020 > الباب الثالث: تنظيم الجهاز المصرفى > الفصل الخامس: نظام تسجيل الائتمان$m259$,$m259$يعد البنك المركزى وشركات التصنيف والاستعلام الائتمانى فور استقبال المعلومات المشار إليها فى المادتين ( 113 ، 114 ) من هذا القانون ، بياناً مجمعاً عن كل عميل وأطرافه المرتبطة .
وعلى البنوك وجهات منح الائتمان الاطلاع على البيان المجمع الخاص بالعميل وأطرافه المرتبطة قبل منحه تمويلاً أو تسهيلاً ائتمانياً أو زيادته أو تجديده ، ولها المطالبة بمستخرج من هذا البيان .
وذلك كله طبقاً للقواعد والإجراءات الصادرة عن مجلس الإدارة .$m259$,'d0e29bd7c9ecdf99aa33abdac253c878'),
(116,0,$m259$قانون البنك المركزى والجهاز المصرفى 194/2020 > الباب الثالث: تنظيم الجهاز المصرفى > الفصل الخامس: نظام تسجيل الائتمان$m259$,$m259$يتبادل البنك المركزى مع البنوك وجهات منح الائتمان وشركات الاستعلام والتصنيف الائتمانى المعلومات المتعلقة بمديونية العملاء والتمويلات أو التسهيلات الائتمانية المقررة لهم ، وذلك طبقاً للقواعد الصادرة عن مجلس الإدارة فى هذا الشأن ، مع كفالة سرية المعلومات والبيانات وضمان توافر ما يلزم منها لسلامة تقديم الائتمان .$m259$,'f7cc37a282511a6163f7f52dfd340ace'),
(117,0,$m259$قانون البنك المركزى والجهاز المصرفى 194/2020 > الباب الثالث: تنظيم الجهاز المصرفى > الفصل السادس: حوكمة البنوك$m259$,$m259$يلتزم كل بنك بوضع سياسة داخلية يلتزم فيها بقواعد الحوكمة والرقابة الداخلية طبقاً للقواعد الصادرة عن مجلس الإدارة .$m259$,'83f51c530985b61c16d1bbd19876c471'),
(118,0,$m259$قانون البنك المركزى والجهاز المصرفى 194/2020 > الباب الثالث: تنظيم الجهاز المصرفى > الفصل السادس: حوكمة البنوك$m259$,$m259$يتولى إدارة البنك مجلس إدارة ، يتكون من عدد من الأعضاء من ذوى الخبرات المتنوعة ، تختارهم الجمعية العامة لمدة ثلاث سنوات .
ويجتمع مجلس إدارة البنك بصورة دورية بناءً على دعوة من رئيسه أو من أغلبية أعضائه ، ويجوز المشاركة فى اجتماع مجلس إدارة البنك باستخدام إحدى وسائل الاتصال البصرية أو السمعية المؤمنة ، وتحسب هذه المشاركة ضمن نصاب الحضور والتصويت .
وتحدد الجمعية العامة البدلات والمكافآت والمزايا الأخرى المقررة لأعضاء المجلس غير التنفيذيين ، ويحدد مجلس إدارة البنك مكافآت ومرتب وبدلات والمزايا الأخرى للعضو المنتدب .
وذلك كله طبقاً للقواعد والإجراءات التى يحددها مجلس الإدارة .$m259$,'751ec62f8cc9f68c8166aa073cf1aa30'),
(119,0,$m259$قانون البنك المركزى والجهاز المصرفى 194/2020 > الباب الثالث: تنظيم الجهاز المصرفى > الفصل السادس: حوكمة البنوك$m259$,$m259$مع عد الإخلال بحق مجلس إدارة كل بنك فى تشكيل ما يراه من لجان تشكل فى كل بنك لجنة للمراجعة الداخلية من ثلاثة من أعضاء مجلس إدارة البنك غير التنفيذيين يختارهم مجلس إدارة البنك ، ويجوز للمجلس أن يضم إلى تشكيلها عضواً خارجياً من ذوى الخبرة بعد الحصول على موافقة المحافظ على انضمامه .
ويجب أن تعقد لجنة المراجعة اجتماعاً كل ثلاثة أشهر على الأكثر يحضره مراقبا حسابات البنك ، وللجنة أن تستعين فى القيام بعملها بمن تراه ، وتعرض توصياتها على مجلس إدارة البنك ، ولأى من مراقبى الحسابات طلب عقد اجتماع اللجنة إذا ما وجد ذلك ضرورياً .
كما تشكل لجان أخرى للمخاطر والمرتبات والمكافآت والحوكمة والترشيحات ، وغيرها من اللجان التى يحددها مجلس الإدارة .
ويحدد مجلس الإدارة اختصاصات اللجان المشار إليها ، ونظم عملها .$m259$,'4c8353b740e0e729482861fed6a597b2'),
(120,0,$m259$قانون البنك المركزى والجهاز المصرفى 194/2020 > الباب الثالث: تنظيم الجهاز المصرفى > الفصل السادس: حوكمة البنوك$m259$,$m259$مع عدم الإخلال بسلطة الجمعية العامة للبنك ، يتعين قبل تعيين أى من المسئولين الرئيسيين الحصول على موافقة المحافظ بما يفيد استيفاء لشروط الجدارة والصلاحية الفنية المشار إليها فى البند ( س ) من المادة ( 84 ) من هذا القانون ، وذلك طبقاً للإجراءات التى يحددها مجلس الإدارة ، وفى حالة عدم الموافقة ، يجب أن يكون القرار مسبباً .$m259$,'1ef50b7c614fee42086cdb36c184512e'),
(121,0,$m259$قانون البنك المركزى والجهاز المصرفى 194/2020 > الباب الثالث: تنظيم الجهاز المصرفى > الفصل السادس: حوكمة البنوك$m259$,$m259$يلتزم المسئولون الرئيسيون ، بممارسة أعمالهم طبقاً للمبادئ الآتية :
( أ ) الالتزام بأحكام هذا القانون واللوائح والتعليمات الصادرة بناءً عليه .
( ب ) بذل العناية الواجبة طبقاً للأصول الفنية والمهنية .
( جـ ) التعاون مع البنك المركزى بمصداقية وشفافية .
( د ) إبلاغ البنك المركزى عن أى مخالفات جسيمة بالبنك .
( هـ ) التحقق من أن الأعمال الواقعة فى نطاق مسئولياتهم تتم بكفاءة وفاعلية طبقاً للقوانين واللوائح والتعليمات المعمول بها .
( و ) مراعاة أن يكون تفويض مسئولياتهم لأشخاص يتوافر لديهم الكفاءة والصلاحية للأعمال المفوضة إليهم ، دون إخلاء مسئوليتهم عن تلك الأعمال .
( ز ) بذل العناية الواجبة لحماية مصالح العملاء ومعاملتهم بطريقة عادلة .
( ح ) مراعاة الإفصاح والشفافية فى إتاحة المعلومات اللازمة للعملاء .
( ط ) العمل على منع تعارض المصالح .$m259$,'564a56f8287f0fbb77b694bc34eafd4c'),
(122,0,$m259$قانون البنك المركزى والجهاز المصرفى 194/2020 > الباب الثالث: تنظيم الجهاز المصرفى > الفصل السادس: حوكمة البنوك$m259$,$m259$لا يجوز لعضو مجلس إدارة أى بنك بصفته الشخصية أو بصفته ممثلاً لغيره أن يجمع إلى عضويته عضوية مجلس إدارة بنك آخر أو شركة منح ائتمان ، أو أن يقوم بأى عمل من أعمال الإدارة أو الاستشارة فى أى منهما .$m259$,'88092aedce19a574e07680072181c3e5'),
(123,0,$m259$قانون البنك المركزى والجهاز المصرفى 194/2020 > الباب الثالث: تنظيم الجهاز المصرفى > الفصل السادس: حوكمة البنوك$m259$,$m259$يحظر على البنك تقديم تمويل أو مبالغ تحت الحساب أو تسهيلات ائتمانية أو ضمان من أى نوع لرئيس وأعضاء مجلس إدارته ومراقبى حساباته أو أزواجهم أو أقاربهم حتى الدرجة الثانية ، أو لأى جهة يكون هؤلاء أو أقاربهم حتى الدرجة الثانية شركاء أو مساهمين فيها ولهم سيطرة فعلية عليها أو أعضاء فى مجالس إدارتها بصفتهم الشخصية .
ويستثنى من ذلك ما كان منها بضمانات نقدية وما فى حكمها ، أو تلك الممنوحة للعضو المنتدب أو المدير الإقليمى لفروع البنوك الأجنبية بحسب الأحوال فى حدود المزايا المقررة للعاملين به وبذات الشروط المقررة لهم مع الإفصاح عن ذلك طبقاً للقواعد السارية بالبنك ، وذلك كله على النحو المحدد بالقواعد والإجراءات المحددة من مجلس الإدارة .$m259$,'5c60c98771512b4c408d11dfb65f8f28'),
(124,0,$m259$قانون البنك المركزى والجهاز المصرفى 194/2020 > الباب الثالث: تنظيم الجهاز المصرفى > الفصل السادس: حوكمة البنوك$m259$,$m259$مع عدم الإخلال بأحكام قانون الجهاز المركزى للمحاسبات ، يتولى مراجعة حسابات البنك مراقبان للحسابات يختارهما البنك من بين المقيدين فى السجل المعد لهذا الغرض طبقاً للقواعد التى يضعها مجلس الإدارة .
ولا يجوز للمراقب الواحد أن يراجع حسابات أكثر من بنكين فى ذات الوقت .
ولا يجوز لمراقب الحسابات أن يكون مساهماً فى البنك الذى يراجع حساباته أو يقدم خدمات له .
وعلى البنك أن يخطر البنك المركزى بتعيين مراقبى الحسابات خلال ثلاثين يوماً من تاريخ تعيينهما .
وللمحافظ ، للأسباب التى يراها ، أن يعهد إلى مراقب حسابات ثالث للقيام بمهمة محددة ، ويتحمل البنك المركزى أتعابه .$m259$,'d977f300301b33cce920507a37a4d71a'),
(125,0,$m259$قانون البنك المركزى والجهاز المصرفى 194/2020 > الباب الثالث: تنظيم الجهاز المصرفى > الفصل السادس: حوكمة البنوك$m259$,$m259$على مراقبى الحسابات أن يعدا تقريرهما عن مراجعة القوائم المالية للبنك طبقاً للقانون ، ولمعايير المراجعة المصرية ، والضوابط التى يصدر بتحديدها قرار من مجلس الإدارة ، على أن يتضمن تقريرهما توضيح ما إذا كانت العمليات التى قاما بمراجعتها تخالف أى حكم من أحكام هذا القانون أو القرارات أو التعليمات الصادرة تنفيذاً له ، وعليهما أن يرسلا إلى البنك المركزى قبل انعقاد الجمعية العامة بثلاثين يوماً على الأقل صورة من تقريرهما مصحوبة بنسخة من القوائم المالية ، وبتقرير تفصيلى متضمناً ما يأتى :
( أ ) أسلوب تقييم أصول البنك ، وكيفية تقدير تعهداته والتزاماته .
( ب ) مدى كفاية نظام الرقابة الداخلية فى البنك بجميع مستوياته .
( جـ ) مدى كفاية المخصصات لمقابلة أى نقص فى قيم الأصول وكذلك أى التزامات قد تقع على عاتق البنك ، مع تحديد مقدار العجز فى المخصصات إن وجد .
( د ) أى معايير أو ضوابط رقابية يرى البنك المركزى أن يتحقق مراقبا الحسابات منها .
ولا يجوز عقد الجمعية العامة للبنك قبل تلقى ملاحظات البنك المركزى على التقرير المقدم إليها عن القوائم المالية .
وللمحافظ أن يصدر خلال خمسة عشر يوماً من تاريخ تسلم التقرير والمرفقات المشار إليها فى الفقرة الأولى من هذه المادة قراراً بعدم اعتماد الأرباح المقترح توزيعها على المساهمين وغيرهم من أصحاب النصيب فى الأرباح وذلك إذا تبين وجود نقص فى المخصصات ، أو انخفاض فى معيار كفاية رأس المال عن الحد الأدنى المقرر ، أو أى تحفظ يكون قد ورد فى تقرير مراقب الحسابات له تأثير مهم على الأرباح القابلة للتوزيع .
وللمحافظ ، طبقاً للضوابط والشروط التى يصدرها مجلس الإدارة ، إلزام البنك بزيادة رأس المال أو بتكوين الاحتياطيات والمخصصات اللازمة قبل توزيع الأرباح بما يتماشى مع متطلبات كفاية رأس المال والملاءة المالية .$m259$,'39646de9cd5d248ef6985d62ec5ece1c'),
(126,0,$m259$قانون البنك المركزى والجهاز المصرفى 194/2020 > الباب الثالث: تنظيم الجهاز المصرفى > الفصل السادس: حوكمة البنوك$m259$,$m259$على مراقب الحسابات الالتزام بإبلاغ البنك المركزى مباشرة فى الحالات الآتية :
( أ ) الوقوف على أى معلومات تؤثر على سلامة الأداء المالى للبنك .
( ب ) قيام الإدارة بأى أنشطة تؤثر على سلامة البنك أو سمعته .
( جـ ) وجود تعارض فى المصالح أو أى خلل فى نظام الرقابة الداخلية .$m259$,'af822c6b4672a20892e2064723e395da'),
(127,0,$m259$قانون البنك المركزى والجهاز المصرفى 194/2020 > الباب الثالث: تنظيم الجهاز المصرفى > الفصل السادس: حوكمة البنوك$m259$,$m259$يكون مراقبا الحسابات مسئولين عما يرد فى تقريرهما من نتائج ، وعلى الأخص ما يتعلق بمحفظة الائتمان والمخاطر الناتجة عن الائتمان والاستثمارات والأصول الخطرة .
وللجمعية العامة للبنك أن تطلب من البنك المركزى فحص أى قصور فى التقارير المقدمة من مراقبى الحسابات .
وإذا ثبت تقصير أى من مراقبى الحسابات فى القيام بالمهام الموكلة له ، جاز لمجلس الإدارة وقف مراقب الحسابات للمدة التى يحددها أو رفع اسمه من السجل المشار إليه فى المادة ( 124 ) من هذا القانون وذلك بعد دراسة المبررات المقدمة منه ، واتخاذ ما يلزم لمحاسبته عن تقصيره .$m259$,'2d49724cc1d615de4808e8e3546f8ad4'),
(128,0,$m259$قانون البنك المركزى والجهاز المصرفى 194/2020 > الباب الثالث: تنظيم الجهاز المصرفى > الفصل السابع: التقارير وقواعد الإفصاح$m259$,$m259$تبدأ السنة المالية لجميع البنوك ببداية السنة الميلادية ، وتنتهى بنهايتها .
ويتم إعداد القوائم المالية للبنك كل ثلاثة أشهر طبقاً لمعايير المحاسبة المصرية ، ويرفق بهذه القوائم موجز لتقرير مراقب الحسابات طبقاً لمعايير المراجعة المصرية وتقرير مجلس إدارة البنك .
وتنشر تلك القوائم فى صحيفة يومية واحدة ، وعلى الموقع الإلكترونى لكل بنك .$m259$,'d8405830d9f0b9ca4a2ba7ec6235b87e'),
(129,0,$m259$قانون البنك المركزى والجهاز المصرفى 194/2020 > الباب الثالث: تنظيم الجهاز المصرفى > الفصل السابع: التقارير وقواعد الإفصاح$m259$,$m259$يقدم كل بنك للبنك المركزى بيانات شهرية وأسبوعية ويومية عن مركزه المالى وغيرها من بيانات مالية ورقابية وذلك فى المواعيد وطبقاً للنماذج التى يصدر بتحديدها قرار من المحافظ .
كما يجوز للبنك المركزى طلب أى بيانات أخرى فى الأحوال التى يقدرها من البنك ذاته أو من الشركة الأم أو الشركات الشقيقة أو التابعة له .$m259$,'468f138c0a813cc37e58098f31607f41'),
(130,0,$m259$قانون البنك المركزى والجهاز المصرفى 194/2020 > الباب الثالث: تنظيم الجهاز المصرفى > الفصل السابع: التقارير وقواعد الإفصاح$m259$,$m259$يقدم كل بنك للبنك المركزى ما يطلبه من بيانات وإيضاحات عن العمليات التى يباشرها ، وللبنك المركزى الحق فى التفتيش والاطلاع على السجلات والحسابات ومحاضر مجلس إدارة كل بنك وجميع اللجان والنظم الآلية والوسائط الإلكترونية للبنك والشركات والجهات التابعة له داخل جمهورية مصر العربية وخارجها بما يكفل تحقيق أغراضه ، كما يحق له مطالبة المساهمين الرئيسيين بأى بيانات لازمة للتحقق من استمرار توافر شروط الموافقة على طلب التملك .
ويتم الاطلاع فى مقار البنك وفروعه وشركاته والجهات التابعة له ، ويقوم بذلك مفتشو البنك المركزى ومعاونوهم الذين يندبهم المحافظ لهذا الغرض ، كما يكون لمفتشى البنك المركزى الحصول على صورة أى مستندات لازمة لتحقيق أغراض التفتيش .$m259$,'d5ba1da82ae31ba562fe9b65d61e9d61'),
(131,0,$m259$قانون البنك المركزى والجهاز المصرفى 194/2020 > الباب الثالث: تنظيم الجهاز المصرفى > الفصل السابع: التقارير وقواعد الإفصاح$m259$,$m259$يتعين على البنوك الالتزام بتصويب الملاحظات التى أسفرت عنها الرقابة المكتبية أو التفتيش الميدانى ، وذلك طبقاً للجدول الزمنى الوارد بخطة الإجراءات التصحيحية .
وللبنك المركزى تكليف خبير مستقل للقيام بأى مهام فحص يحددها له وعلى نفقته .$m259$,'414c2722aac39b10b8bfb12362a9dc18'),
(132,0,$m259$قانون البنك المركزى والجهاز المصرفى 194/2020 > الباب الثالث: تنظيم الجهاز المصرفى > الفصل السابع: التقارير وقواعد الإفصاح$m259$,$m259$يقدم كل بنك للبنك المركزى نسخة من الدعوة إلى الجمعية العامة للبنك وجدول أعمالها وكذا نسخة من كل تقرير يقدم عن أعماله إلى المساهمين ، وذلك قبل ثلاثين يوماً على الأقل من تاريخ انعقاد تلك الجمعية ، وعليه أن يقدم إلى البنك المركزى صورة من محضر اجتماع كل جمعية عامة خلال ثلاثين يوماً من تاريخ انعقادها .
وللبنك المركزى أن يؤجل انعقاد الجمعية العامة فى الأحوال التى يراها لمدة لا تجاوز ثلاثين يوماً .$m259$,'98cbe179b657627926b2fa9b7c84722d'),
(133,0,$m259$قانون البنك المركزى والجهاز المصرفى 194/2020 > الباب الثالث: تنظيم الجهاز المصرفى > الفصل الثامن: البنوك المملوكة أسهمها بالكامل للدولة$m259$,$m259$تخضع البنوك المملوكة أسهمها بالكامل للدولة لذات الأحكام التى تخضع لها البنوك الأخرى ، فيما عدا ما يرد به نص خاص فى هذا الفصل .
وفى جميع الأحوال ، لا تخضع البنوك المملوكة أسهمها بالكامل للدولة والعاملون فيها لأحكام القوانين واللوائح والقرارات المعمول بها فى شركات القطاع العام وقطاع الأعمال العام ، بما فى ذلك القانون رقم 47 لسنة 1973 بشأن الإدارات القانونية بالمؤسسات العامة والهيئات العامة والوحدات التابعة لها والقانون رقم 117 لسنة 1958 بإعادة تنظيم النيابة الإدارية والمحاكمات التأديبية فى الإقليم المصرى .$m259$,'cfedfa6c6db31d45f384a7fe01c5eadd'),
(134,0,$m259$قانون البنك المركزى والجهاز المصرفى 194/2020 > الباب الثالث: تنظيم الجهاز المصرفى > الفصل الثامن: البنوك المملوكة أسهمها بالكامل للدولة$m259$,$m259$مع عدم الإخلال بأحكام المادة ( 120 ) من هذا القانون ، يكون تعيين رئيس وأعضاء مجلس إدارة البنك المملوكة أسهمه بالكامل للدولة بقرار من رئيس مجلس الوزراء .$m259$,'c3c51f54f3b34e78bc7ff13057adb603'),
(135,0,$m259$قانون البنك المركزى والجهاز المصرفى 194/2020 > الباب الثالث: تنظيم الجهاز المصرفى > الفصل الثامن: البنوك المملوكة أسهمها بالكامل للدولة$m259$,$m259$يعتمد مجلس إدارة البنك المملوكة أسهمه بالكامل للدولة جميع لوائح العمل الداخلية طبقاً لما ورد فى قانون العمل الصادر بالقانون رقم 12 لسنة 2003 فى هذا الشأن ، ويقر جدول الأجور والحوافز والبدلات للعاملين ، وله أن يضع نظاماً أو أكثر لإثابتهم فى ضوء معدلات أدائهم وحجم ومستوى إنجازهم فى العمل والتحقيق معهم وتأديبهم ، وذلك كله دون التقيد بأحكام القوانين واللوائح المعمول بها فى شركات القطاع العام وقطاع الأعمال العام .$m259$,'fdf59e593c76dc4e283e2887527fb123'),
(136,0,$m259$قانون البنك المركزى والجهاز المصرفى 194/2020 > الباب الثالث: تنظيم الجهاز المصرفى > الفصل الثامن: البنوك المملوكة أسهمها بالكامل للدولة$m259$,$m259$يكون تعيين ممثلى البنوك المملوكة أسهمها بالكامل للدولة فى البنوك والشركات التى تساهم فيها بقرار من مجلس إدارة البنك المعنى ، ويكون قرار التعيين لدورة واحدة قابلة للتجديد لمرة واحدة ، ويجوز لمجلس إدارة البنك المملوكة أسهمه بالكامل للدولة تغيير ممثليه قبل انتهاء دورة المجلس وذلك دون الإخلال بحكم المادة ( 120 ) من هذا القانون .$m259$,'1538ad7d06341ea6fd612046a4b4d2bd'),
(137,0,$m259$قانون البنك المركزى والجهاز المصرفى 194/2020 > الباب الثالث: تنظيم الجهاز المصرفى > الفصل الثامن: البنوك المملوكة أسهمها بالكامل للدولة$m259$,$m259$يكون لكل بنك من البنوك المملوكة أسهمها بالكامل للدولة جمعية عامة يصدر بتشكيلها قرار من رئيس مجلس الوزراء من بين ذوى الخبرة المصرفية والمالية والاقتصادية والقانونية والمحاسبية .
وتتولى الجمعية العامة للبنك المملوكة أسهمه بالكامل للدولة على الأخص ما يأتى :
( أ ) إقرار القوائم المالية وتوزيع الأرباح وتقرير مراقب الحسابات .
( ب ) تعديل النظام الأساسى .
( جـ ) تقرير اندماج البنك أو تقسيمه ، ولا يكون القرار الصادر فى هذا الشأن نافذاً إلا بعد موافقة مجلس الوزراء .
( د ) اعتماد الموازنة التقديرية .
( هـ ) تحديد مرتبات وبدلات ومكافآت رئيس وأعضاء مجلس إدارة البنك .
ويحضر الجمعية العامة رئيس وأعضاء مجلس إدارة البنك ومراقبا الحسابات وممثل أو أكثر عن البنك المركزى دون أن يكون لهم صوت معدود .$m259$,'12e6d3ba8bc6e9440e2438a60aba0010'),
(138,0,$m259$قانون البنك المركزى والجهاز المصرفى 194/2020 > الباب الثالث: تنظيم الجهاز المصرفى > الفصل الثامن: البنوك المملوكة أسهمها بالكامل للدولة$m259$,$m259$يجوز للقطاع الخاص أن يتملك أسهماً فى رءوس أموال البنوك المملوكة أسهمها بالكامل للدولة ، وفى هذه الحالة لا تسرى عليه أحكام هذا الفصل .
ويعين بقرار من رئيس مجلس الوزراء ممثلو المال العام فى اجتماعات الجمعية العامة للبنك وذلك بالنسبة إلى ما تملكه الدولة فى رأسماله .$m259$,'f3f130cc60eaefd2998ca4de60f1d2ce'),
(139,0,$m259$قانون البنك المركزى والجهاز المصرفى 194/2020 > الباب الثالث: تنظيم الجهاز المصرفى > الفصل الثامن: البنوك المملوكة أسهمها بالكامل للدولة$m259$,$m259$لا تشمل الموازنة العامة للدولة الموارد والاستخدامات الجارية والرأسمالية للبنوك المملوكة أسهمها بالكامل للدولة ، ويئول صافى أرباح هذه البنوك للخزانة العامة للدولة ، وذلك بعد اقتطاع ما يتقرر تكوينه من احتياطيات أو حصة العاملين فى الأرباح أو احتجازه من أرباح أو زيادة فى رأس المال أو غيرها من المتطلبات الرقابية الأخرى التى يفرضها البنك المركزى .$m259$,'21fcec2ce4111bdf3f1af22dce6f10da'),
(140,0,$m259$قانون البنك المركزى والجهاز المصرفى 194/2020 > الباب الثالث: تنظيم الجهاز المصرفى > الفصل التاسع: سرية الحسابات$m259$,$m259$تكون جميع بيانات العملاء وحساباتهم وودائعهم وأماناتهم وخزائنهم فى البنوك وكذلك المعاملات المتعلقة بها سرية ، ولا يجوز الاطلاع عليها أو إعطاء بيانات عنها بطريق مباشر أو غير مباشر إلا بإذن كتابى من صاحب الحساب أو الوديعة أو الأمانة أو الخزينة أو من أحد ورثته أو من أحد الموصى لهم بكل هذه الأموال أو بعضها ، أو من نائبه القانونى أو وكيله أو بناء على حكم قضائى أو حكم تحكيم .
ومع عدم الإخلال بالاستثناءات الواردة بهذا القانون ، يسرى الحظر المنصوص عليه فى الفقرة الأولى من هذه المادة على جميع الأشخاص والجهات بما فى ذلك الجهات التى يخولها القانون سلطة الاطلاع أو الحصول على الأوراق أو البيانات المحظور إفشاء سريتها طبقاً لأحكام هذا القانون ، ويظل هذا الحظر قائماً حتى ولو انتهت العلاقة بين العميل والبنك لأى سبب من الأسباب .$m259$,'ce94d52662177db616b691c59cc3c844'),
(141,0,$m259$قانون البنك المركزى والجهاز المصرفى 194/2020 > الباب الثالث: تنظيم الجهاز المصرفى > الفصل التاسع: سرية الحسابات$m259$,$m259$إذا اقتضى كشف الحقيقة فى جناية أو جنحة قامت الدلائل الجدية على وقوعها ، يجوز للنائب العام أو لمن يفوضه من المحامين العامين الأول على الأقل ، من تلقاء نفسه أو بناء على طلب جهة رسمية أو أحد من ذوى الشأن ، أن يطلب من محكمة استئناف القاهرة الأمر بالاطلاع أو الحصول على أى بيانات أو معلومات تتعلق بالحسابات أو الودائع أو الأمانات أو الخزائن المنصوص عليها فى المادة ( 140 ) من هذا القانون أو المعاملات المتعلقة بها .
ولأى من ذوى الشأن فى حالة التقرير بما فى الذمة بمناسبة حجز موقع لدى أحد البنوك الخاضعة لأحكام هذا القانون أن يتقدم بالطلب المشار إليه فى الفقرة الأولى من هذه المادة إلى محكمة الاستئناف المختصة .
وتفصل المحكمة منعقدة فى غرفة المشورة فى الطلب خلال الأيام الثلاثة التالية لتقديمه بعد سماع أقوال النيابة العامة أو ذى الشأن .
وعلى النائب العام أو من يفوضه فى ذلك من المحامين العامين الأول على الأقل وعلى ذى الشأن بحسب الأحوال إخطار البنك وذوى الشأن بالأمر الذى تصدره المحكمة خلال الأيام الثلاثة التالية لصدوره .
ويبدأ سريان الميعاد المحدد للتقرير بما فى الذمة من تاريخ إخطار البنك بالأمر المذكور .
ويكون للنائب العام أو من يفوضه من المحامين العامين الأول على الأقل أن يأمر مباشرة بالاطلاع أو الحصول على أى بيانات أو معلومات تتعلق بالحسابات أو الودائع أو الأمانات أو الخزائن المنصوص عليها فى المادة ( 140 ) من هذا القانون أو المعاملات المتعلقة بها إذا اقتضى ذلك كشف الحقيقة فى جريمة من الجرائم المنصوص عليها فى القسم الأول من الباب الثانى من الكتاب الثانى من قانون العقوبات ، وفى الجرائم المنصوص عليها فى القوانين المتعلقة بمكافحة غسل الأموال ومكافحة وتمويل الإرهاب .
وللمدعى العام العسكرى أو من يفوضه ممن يعادل درجة محام عام أول على الأقل من أعضاء النيابة العسكرية مباشرة الاختصاصات المقررة للنائب العام والمنصوص عليها فى هذه المادة ، كما تختص المحكمة العسكرية للجنايات بالقاهرة بذات الاختصاصات والإجراءات المقررة لمحكمة استئناف القاهرة المنصوص عليها فى هذه المادة ، وذلك كله فيما يدخل فى اختصاص القضاء العسكرى .$m259$,'9686b3f976af89c62b251681e1d25f1c'),
(142,0,$m259$قانون البنك المركزى والجهاز المصرفى 194/2020 > الباب الثالث: تنظيم الجهاز المصرفى > الفصل التاسع: سرية الحسابات$m259$,$m259$يُحظر على كل من يتلقى أو يطلع بحكم مهنته أو وظيفته أو عمله بطريق مباشر أو غير مباشر على معلومات أو بيانات عن العملاء أو حساباتهم أو ودائعهم ، أو الأمانات أو الخزائن الخاصة بهم أو معاملاتهم إفشاؤها أو تمكين الغير من الاطلاع عليها وذلك فى غير الحالات المرخص بها بمقتضى أحكام هذا القانون ، ويستمر هذا الحظر بعد تركهم للعمل .$m259$,'85a35f71156ae9afb3cfd595a438553b'),
(143,0,$m259$قانون البنك المركزى والجهاز المصرفى 194/2020 > الباب الثالث: تنظيم الجهاز المصرفى > الفصل التاسع: سرية الحسابات$m259$,$m259$لا تخل أحكام المادتين ( 140 ، 142 ) من هذا القانون بما يأتى :
( أ ) الواجبات المنوط أداؤها قانوناً بمراقبى حسابات البنوك ، وبالاختصاصات المخولة قانوناً للبنك المركزى .
( ب ) التزام البنك بإصدار بيان بأسباب رفض صرف الشيك أو أمر الخصم المباشر بناءً على طلب صاحب الحق أو ما يفيد الوفاء الجزئى لأى منهما حالة عدم كفاية الرصيد .
( جـ ) حق البنك أو جهة منح الائتمان أو التمويل فى الكشف عن كل أو بعض البيانات الخاصة بمعاملات العميل اللازمة لمباشرة الإجراءات القانونية ، أو لإثبات حق البنك أو الجهة فى أى نزاع ينشأ مع العميل فى شأن هذه المعاملات .
( د ) القوانين والأحكام الخاصة بتنظيم مكافحة غسل الأموال وتمويل الإرهاب .
( هـ ) ما تقدمه شركات الاستعلام والتصنيف الائتمانى من معلومات وبيانات طبقاً للقواعد التى يحددها مجلس الإدارة .
( و ) اختصاص البنك المركزى فى تبادل البيانات والمعلومات مع الجهات الأجنبية المناظرة فى الدول الأخرى ولجنة الاستقرار المالى والهيئة العامة للرقابة المالية .
( ز ) الاطلاع على البيانات والمعلومات اللازمة لإعداد تقارير الفحص النافى للجهالة عند طلب الدمج أو الاستحواذ أو التقسيم على نسبة حاكمة من أسهم أى من البنوك .
( ح ) حق البنك المركزى فى الدفاع عن نفسه فى أى نزاع قضائى أو دعوى تحكيمية أو إبلاغ النيابة العامة بمناسبة مباشرته لاختصاصاته المخولة له قانوناً .
( ط ) اطلاع مقدمى خدمات التعهيد على بيانات العملاء اللازمة لمباشرة الخدمات الموكلة إليهم .
( ى ) قيام العاملين بالبنوك ومُشغلى نظم الدفع ومقدمى خدمات الدفع بإبلاغ البنك المركزى عن المخالفات التى تتكشف لهم من جراء أعمالهم طبقاً لقواعد الإبلاغ عن المخالفات التى يحددها مجلس الإدارة .$m259$,'ac4018ba7ecbe07bdca3b7bc4005b529'),
(144,0,$m259$قانون البنك المركزى والجهاز المصرفى 194/2020 > الباب الثالث: تنظيم الجهاز المصرفى > الفصل العاشر: الإجراءات التصحيحية والجزاءات$m259$,$m259$لمجلس الإدارة حال ثبوت مخالفة أى من البنوك أو المسئولين الرئيسيين لأحكام هذا القانون أو اللوائح أو القرارات الصادرة تنفيذاً له اتخاذ واحد أو أكثر من الإجراءات أو الجزاءات التالية بما يتناسب مع طبيعة المخالفة وجسامتها وظروف ارتكابها :
( أ ) توجيه تنبيه .
( ب ) إلزام البنك بإزالة المخالفة واتخاذ إجراءات تصحيحية خلال مدة محددة .
( جـ ) أن يوفد ممثلاً عنه لحضور اجتماعات مجلس إدارة البنك أو جمعيته العامة دون أن يكون له حق التصويت .
( د ) إلزام رئيس مجلس إدارة البنك المخالف بدعوة المجلس إلى الانعقاد للنظر فى أمر المخالفات المنسوبة إلى البنك واتخاذ اللازم نحو إزالتها ، ويجوز أن يحضر اجتماع المجلس فى هذه الحالة ممثل أو أكثر عن البنك المركزى دون أن يكون لهم حق التصويت .
( هـ ) إلزام البنك بدعوة الجمعية العامة للانعقاد لاتخاذ الإجراءات اللازمة ، وإدراج الموضوعات التى يرى البنك المركزى ضرورة مناقشتها خلالها ، وفى حالة عدم امتثال البنك لذلك ، يحق للبنك المركزى دعوتها مباشرة .
( و ) منع أو تعليق أو تقييد البنك وفروعه والشركات التابعة له من ممارسة أى من الأنشطة أو العمليات مع أى من الأطراف أو المساهمين الرئيسيين أو الأطراف المرتبطة بالبنك .
( ز ) إلزام البنك المخالف بإيداع أرصدة لدى البنك المركزى دون عائد طبقاً للقواعد التى يقررها مجلس الإدارة وذلك بالإضافة إلى الرصيد الدائن المنصوص عليه فى المادة ( 89 ) من هذا القانون .
( ح ) توقيع جزاءات مالية على البنك .
( ط ) تنحية واحد أو أكثر من المسئولين الرئيسيين .
ويجوز للبنك المركزى نشر أى من الإجراءات والجزاءات المشار إليها .$m259$,'c7b5d7b93cd1de475562c12fd0639dfe'),
(145,0,$m259$قانون البنك المركزى والجهاز المصرفى 194/2020 > الباب الثالث: تنظيم الجهاز المصرفى > الفصل العاشر: الإجراءات التصحيحية والجزاءات$m259$,$m259$لمجلس الإدارة فى حالة اتخاذه قراراً بتوقيع جزاءات مالية طبقاً لحكم المادة ( 144 ) من هذا القانون مراعاة ألا تقل قيمة الجزاء المالى عن المبالغ المتحصلة من المخالفة وبما يتناسب مع درجة جسامتها وحجم الضرر الناتج عنها .
ولمجلس الإدارة الإعفاء من جزء من قيمة الجزاء المالى طبقاً لدرجة استجابة المخالف فى تصويب الوضع ، على أن يخرج من نطاق ذلك الإعفاء قيمة المبلغ المتحصل نتيجة للمخالفة محل الجزاء .
وذلك كله طبقاً للقواعد والإجراءات التى يصدرها مجلس الإدارة .$m259$,'c14c6e6048acd8ca75affd90c53c0727'),
(146,0,$m259$قانون البنك المركزى والجهاز المصرفى 194/2020 > الباب الثالث: تنظيم الجهاز المصرفى > الفصل الحادى عشر: التدخل المبكر$m259$,$m259$للبنك المركزى اتخاذ أى من الإجراءات أو الجزاءات المنصوص عليها بالمادة ( 147 ) من هذا القانون حال تحقق أى من الحالات الآتية :
( أ ) قيام البنك بممارسات مصرفية غير سليمة .
( ب ) عدم التزام البنك بأى من الإجراءات المُتخذة فى شأنه عملاً بنص المادة ( 144 ) من هذا القانون .
( جـ ) التباين الكبير بين آجال استحقاق أصول البنك والتزاماته .
( د ) ارتفاع تكلفة السيولة لدى البنك نتيجة الاعتماد على التمويل الاستثنائى أو غيره من الموارد المكلفة .
( هـ ) انخفاض جودة أصول البنك بما من شأنه المساس بالسلامة المالية للبنك أو بمصالح المودعين .
( و ) انخفاض مستوى الأرباح المحققة بما من شأنه تهديد استمرارية البنك على المدى المتوسط أو البعيد .
( ز ) تراجع مؤشرات السلامة المالية للبنك .
( ح ) وجود قصور فى نظم الحوكمة أو إدارة المخاطر أو الرقابة الداخلية أو السياسات المحاسبية .$m259$,'20e70305075de46f6381464ff637aa2b'),
(147,0,$m259$قانون البنك المركزى والجهاز المصرفى 194/2020 > الباب الثالث: تنظيم الجهاز المصرفى > الفصل الحادى عشر: التدخل المبكر$m259$,$m259$فى حالة حدوث أى من الحالات المبينة فى المادة ( 146 ) من هذا القانون ، يجوز لمجلس الإدارة ، دون الإخلال بسلطته فى اتخاذ أى إجراء آخر منصوص عليه فى هذا القانون أو فى أى قانون آخر ، إلزام البنك باتخاذ واحد أو أكثر من الإجراءات والجزاءات التالية بما يتناسب مع كل حالة :
( أ ) تعزيز سياسات الحوكمة وإدارة المخاطر والرقابة الداخلية والسياسات المحاسبية .
( ب ) التقيد بالمتطلبات الرقابية الإضافية التى يفرضها البنك المركزى .
( جـ ) توفير تمويل إضافى ، وإعادة نسب السيولة إلى مستوى يقبله البنك المركزى .
( د ) تكوين مخصصات واحتياطيات إضافية ، أو زيادة رأسماله المصدر والمدفوع أو رأس المال المخصص لفروع البنوك الأجنبية .
( هـ ) تخفيض المكافآت والمزايا المالية للمسئولين الرئيسيين وكبار العاملين بالبنك .
( و ) حظر توزيع أى أرباح أو مزايا مالية على مساهمى البنك وغيرهم من أصحاب النصيب .
( ز ) تنفيذ إجراء أو أكثر من الإجراءات الواردة بالخطة المنصوص عليها فى المادة ( 94 ) من هذا القانون .
( ح ) تقديم خطة تصحيحية محددة المدة يعتمدها البنك المركزى .
( ط ) الحصول على موافقة مسبقة من البنك المركزى قبل تنفيذ معاملات أو ممارسة أنشطة محددة .
( ى ) ألا يتجاوز مجموع أصوله الحد الذى يقرره البنك المركزى لمدة محددة .
( ك ) إغلاق بعض فروعه أو بيع بعض أنشطته أو مساهماته أو حصصه فى شركاته التابعة .
( ل ) تقديم خطة لإعادة الهيكلة ، بما فى ذلك إعادة جدولة الالتزامات ، أو استبدال أصول ذات مخاطر منخفضة بالأصول عالية المخاطر ، أو تقديم تعهدات مالية من جانب المساهمين الرئيسيين ، يوافق عليها البنك المركزى .
( م ) تغيير نموذج أعمال البنك أو فروعه أو الشركات التابعة له أو تعديل نظمها الأساسية أو هياكلها التنظيمية .
( ن ) تنحية واحد أو أكثر من المسئولين الرئيسيين .
( س ) حل مجلس إدارة البنك وتعيين مدير مؤقت لإدارة البنك لمدة لا تجاوز ستة أشهر يجوز مدها لمدة مماثلة ، ويعرض المدير المؤقت قبل انتهاء مدة تعيينه الأمر على الجمعية العامة للبنك لاختيار مجلس إدارة جديد ، أو اتخاذ ما تراه لازماً .
( ع ) الاندماج فى بنك آخر .
وفى حالة عدم قدرة أى من المساهمين الرئيسيين على تحمل التزاماته تجاه البنك أو ثبوت إخلاله بأى إجراء تصحيحى أو فقدانه أحد شروط التملك المنصوص عليها فى المادة ( 77 ) من هذا القانون ، يجوز لمجلس الإدارة تعليق حقه فى التصويت ومطالبته ببيع حصته خلال مدة محددة ، وإلا يتم اتخاذ إجراءات البيع المنصوص عليها فى الفقرة الثانية من المادة ( 74 ) من هذا القانون .
ويجوز للبنك المركزى نشر أى من الإجراءات والجزاءات المشار إليها .$m259$,'b8b0f77906365d9c7ac5a898fa99fb6e'),
(148,0,$m259$قانون البنك المركزى والجهاز المصرفى 194/2020 > الباب الثالث: تنظيم الجهاز المصرفى > الفصل الحادى عشر: التدخل المبكر$m259$,$m259$يلتزم البنك المعنى بتقديم تقارير إلى البنك المركزى فى شأن الموقف التنفيذى للإجراءات المتخذة بموجب المادة ( 147 ) من هذا القانون فى المواعيد والحالات التى يحددها مجلس الإدارة .
ولمجلس الإدارة أن يوقف أو يعدل أو يلغى أياً من الإجراءات المفروضة على البنك .$m259$,'f67658e82a5ec0b0c31e6b24cc31de1d'),
(149,0,$m259$قانون البنك المركزى والجهاز المصرفى 194/2020 > الباب الثالث: تنظيم الجهاز المصرفى > الفصل الثانى عشر: تسوية أوضاع البنوك المتعثرة$m259$,$m259$تخضع البنوك المسجلة لدى البنك المركزى لأحكام هذا الفصل فى حالات التعثر ، ولا يسرى عليها قانون تنظيم إعادة الهيكلة والصلح الواقى والإفلاس الصادر بالقانون رقم 11 لسنة 2018$m259$,'f4352bd7eddcc56e00c15e805cddca62'),
(150,0,$m259$قانون البنك المركزى والجهاز المصرفى 194/2020 > الباب الثالث: تنظيم الجهاز المصرفى > الفصل الثانى عشر: تسوية أوضاع البنوك المتعثرة$m259$,$m259$البنك المركزى هو السلطة المختصة بتسوية أوضاع البنوك المتعثرة ، ويجوز له ممارسة سلطاته واتخاذ أى من الإجراءات المنصوص عليها فى هذا الفصل مباشرةً أو من خلال المفوض .
ويختص مجلس الإدارة بإصدار القرارات والتعليمات اللازمة لتنفيذ أحكام هذا الفصل .$m259$,'a0712b589f0cfeac76727a1c0ccf320f'),
(151,0,$m259$قانون البنك المركزى والجهاز المصرفى 194/2020 > الباب الثالث: تنظيم الجهاز المصرفى > الفصل الثانى عشر: تسوية أوضاع البنوك المتعثرة$m259$,$m259$تهدف إجراءات التسوية التى يتخذها البنك المركزى طبقاً لأحكام هذا الفصل إلى الآتى :
( أ ) الحفاظ على استقرار النظام المصرفى .
( ب ) حماية مصالح المودعين وأموالهم .
( جـ ) الحد من استخدام المال العام فى تسوية أوضاع البنوك المتعثرة .
( د ) تخفيض خسائر الدائنين كلما أمكن .$m259$,'346800b84630b6a73776049780afbf5b'),
(152,0,$m259$قانون البنك المركزى والجهاز المصرفى 194/2020 > الباب الثالث: تنظيم الجهاز المصرفى > الفصل الثانى عشر: تسوية أوضاع البنوك المتعثرة$m259$,$m259$تتم تسوية أوضاع البنوك المتعثرة ، طبقاً للضوابط الآتية :
( أ ) تناسب الإجراء المتخذ مع درجة تعثر البنك .
( ب ) أن يتم استهلاك الخسائر أولاً من حقوق المساهمين .
( جـ ) يتم استهلاك باقى الخسائر إن وجدت من مستحقات دائنى البنك المتعثر بعكس الترتيب المنصوص عليه فى المادة ( 175 ) من هذا القانون مع مراعاة الاستثناءات الواردة فى هذا القانون .
( د ) أن تتم معاملة الدائنين من ذات المرتبة معاملة متساوية ما لم ينص هذا القانون على خلاف ذلك .
( هـ ) ألا يتحمل أى من دائنى البنك خسارة تجاوز تلك التى كان سيتحملها لو تمت تصفية البنك طبقاً لقانون تنظيم إعادة الهيكلة والصلح الواقى والإفلاس الصادر بالقانون رقم 11 لسنة 2018 بأولوية ترتيب الدائنين المنصوص عليها فى المادة ( 175 ) من هذا القانون .$m259$,'f736ff7dbe0a7d8d0167fc73f3424583'),
(153,0,$m259$قانون البنك المركزى والجهاز المصرفى 194/2020 > الباب الثالث: تنظيم الجهاز المصرفى > الفصل الثانى عشر: تسوية أوضاع البنوك المتعثرة$m259$,$m259$للبنك المركزى أن يصدر قراراً باعتبار أحد البنوك متعثراً وبدء تسوية أوضاعه فى أى من الحالات الآتية :
( أ ) ضعف المركز المالى للبنك إلى حد كبير ، أو تعرض مصالح المودعين للخطر .
( ب ) إذا كان البنك غير قادر على الوفاء بالتزاماته تجاه المودعين أو غيرهم من الدائنين .
( جـ ) إذا جاوزت التزامات البنك قيمة أصوله .
( د ) نقص قيمة حقوق المساهمين فى البنك عن المخصصات الواجب تكوينها .
( هـ ) إذا فقد البنك قدرته على الوصول إلى مصادر الأموال أو الدخول إلى الأسواق المالية .
( و ) إذا أخل بمعيار كفاية رأس المال أو نسب السيولة أو بغيرها من النسب الرقابية عن الحد الذى يقرره مجلس الإدارة .
( ز ) إذا انخفضت قيمة أصول البنك أو أرباحه بشكل ملحوظ ومستمر بما يهدد قدرته على الاستمرار .
( ح ) اعتماد البنك على مصادر تمويل استثنائية مكلفة لمواصلة أنشطته الاعتيادية .
( ط ) تحقق أى من الحالات المقررة لإلغاء الترخيص المنصوص عليها فى المادة ( 173 ) من هذا القانون .
( ى ) إذا لم يلتزم البنك بإجراءات التدخل المبكر المنصوص عليها فى المادة ( 147 ) من هذا القانون وخلال المدة المحددة لتنفيذها .
( ك ) عدم قدرة فرع البنك الأجنبى على الوفاء بالتزاماته وتقاعس مركزه الرئيسى عن الوفاء بها بموجب الضمان غير المشروط المقدم منه طبقاً لنص المادة ( 68 ) من هذا القانون ، ولم تصدر السلطة المختصة بدولة المقر قراراً بتسوية أوضاعه خلال المدة التى يحددها مجلس الإدارة ، أو صدر قرار بتسوية أوضاع البنك بدولة المقر وكانت الإجراءات التصحيحية أو إجراءات التسوية المتخذة فى شأنه أو تلك المتوقع اتخاذها غير كافية للحفاظ على الاستقرار المصرفى فى جمهورية مصر العربية أو على حقوق المودعين والدائنين بالفرع .
وفى جميع الأحوال ، لا يعد التدخل المبكر أو أى إجراءات أخرى شرطاً مسبقاً لبدء إجراءات تسوية أوضاع البنك المتعثر .$m259$,'e85086ce0194d35b8cc6941c9ab2cf84'),
(154,0,$m259$قانون البنك المركزى والجهاز المصرفى 194/2020 > الباب الثالث: تنظيم الجهاز المصرفى > الفصل الثانى عشر: تسوية أوضاع البنوك المتعثرة$m259$,$m259$دون التقيد بأحكام أى قوانين أو التزامات تعاقدية أخرى ، يصدر مجلس الإدارة قراراً مسبباً باعتبار البنك متعثراً وببدء تسوية أوضاعه ، ويكون قراره سارياً لمدة عام من تاريخ نشره أو إخطار ذوى الشأن به ، بحسب الأحوال ، ويكون النشر فى الوقائع المصرية وعلى الموقع الإلكترونى لكل من البنك المركزى والبنك المعنى ، ويكون قراره ملزماً ونافذاً من تاريخ نشره بالوقائع المصرية ، ويجوز لمجلس الإدارة مد تلك الفترة لفترات مماثلة بما لا يجاوز ثلاث سنوات من تاريخ صدوره .
ولمجلس الإدارة إلغاء قرار تسوية أوضاع البنك المتعثر فى أى وقت حال انتفاء أسباب صدوره ، وينشر هذا القرار فى الوقائع المصرية أو يخطر ذوو الشأن به ، بحسب الأحوال .$m259$,'88263d17ccac3e04b6298898bedff27e'),
(155,0,$m259$قانون البنك المركزى والجهاز المصرفى 194/2020 > الباب الثالث: تنظيم الجهاز المصرفى > الفصل الثانى عشر: تسوية أوضاع البنوك المتعثرة$m259$,$m259$يترتب على صدور قرار البنك المركزى باعتبار البنك متعثراً ما يأتى :
( أ ) انتقال جميع اختصاصات جمعيته العامة العادية وغير العادية ومجلس إدارته والإدارة التنفيذية إلى البنك المركزى ، ما لم يقرر البنك المركزى استمرار أى منهم فى ممارسة كل أو بعض اختصاصاته .
( ب ) وقف توزيع أى أرباح أو غيرها من صور توزيعات رأس المال للمساهمين ولغيرهم من أصحاب النصيب .
( جـ ) وقف صرف مستحقات المسئولين الرئيسيين باستثناء تلك المتعلقة بالأعمال أو الخدمات التى يقررها البنك المركزى .
( د ) وقف جميع الدعاوى القضائية المقامة من الدائنين ضد البنك الخاضع للتسوية لمدة تسعين يوماً من تاريخ نشر قرار اعتبار البنك متعثراً .
ويجوز للبنك المركزى ، مباشرة أو بناءً على طلب من المفوض ، اتخاذ أى من الإجراءات الآتية :
( أ ) جدولة كل أو بعض المدفوعات المستحقة على البنك لمدة لا تزيد عن ستين يوماً ، فيما عدا ودائع العملاء ، والمستحقات الخاصة بنظم الدفع والتسوية أو بمشغلى تلك النظم أو المشاركين فيها .
( ب ) وقف تطبيق حق الإنهاء المبكر للعقود المالية التى يكون البنك الخاضع للتسوية طرفاً فيها ، وذلك طبقاً للضوابط الآتية :
1 - أن تكون المطالبة بالإنهاء المبكر ناشئة عن اتخاذ أى من الإجراءات المنصوص عليها فى هذا الفصل .
2 - ألا تزيد فترة الإيقاف على يومى عمل .
3 - عقب نقل العقود المالية للطرف المستحوذ ، تظل حقوق الإنهاء المبكر للطرف الآخر نافذة فى مواجهة الجهة المستحوذة ، وذلك فى حال وقوع خطأ لاحق مستقل من طرف الجهة المستحوذة .
4 - يحق للطرف الآخر استخدام حق الإنهاء المبكر فى مواجهة البنك الخاضع للتسوية عند انتهاء مدة الإيقاف المشار إليها فى البند ( 2 ) أو قبل انتهائها حالة إخطار البنك المركزى للطرف الآخر بأن تلك العقود المالية لن يتم نقلها .
ولا يترتب على صدور قرار تسوية أوضاع البنك المتعثر أو اتخاذ أى من الإجراءات المنصوص عليها فى المادة ( 157 ) من هذا القانون إنهاء أى حق أو التزام تعاقدى أو تعجيله أو تعديله طالما استمر البنك المعنى فى تنفيذ التزاماته الجوهرية المنصوص عليها فى العقد .$m259$,'8ad1c750aaeff168b253d7f3fcf73b10'),
(156,0,$m259$قانون البنك المركزى والجهاز المصرفى 194/2020 > الباب الثالث: تنظيم الجهاز المصرفى > الفصل الثانى عشر: تسوية أوضاع البنوك المتعثرة$m259$,$m259$يلتزم البنك المركزى بإعداد تقرير يتضمن حصر أصول وإلتزامات البنك الخاضع للتسوية وتقييمها طبقاً للمنهجية والفرضيات التى يحددها بالنظر لحالة البنك وذلك مراعاة ألا تقع المقاصة بين ما للبنك من حقوق وما عليه من التزامات إلا إذا وجد ارتباط بينهما ، ويوجد الارتباط على وجه الخصوص إذا نشأت الحقوق والالتزامات عن سبب واحد أو شملها حساب جار .
ويهدف هذا التقرير إلى تحديد صافى أصوله فى تاريخ اعتباره متعثراً ، وحساب تكلفة تسوية أوضاعه ، وتحديد أنسب الطرق لتنفيذها ، وحساب الخسائر المتوقعة .
ويشمل هذا التقرير على الأخص ما يأتى :
( أ ) تصنيف الأصول بحسب درجة جودة كل منها ومخاطره والمخصصات القابلة لها .
( ب ) الوضع المالى والاحتمالات المستقبلية للبنك .
( جـ ) قائمة المركز المالى المعدلة استناداً إلى تقييم الأصول والالتزامات .
وللبنك المركزى فى حالات الضرورة القصوى اتخاذ قرار ببدء إجراءات تسوية أوضاع البنك المتعثر بناءً على تقييمات مبدئية لقيمة الأصول والالتزامات ، على أن يتم الانتهاء من التقرير المشار إليه فى الفقرة الأولى من هذه المادة خلال مدة لا تجاوز 180 يوماً من تاريخ اعتبار البنك متعثراً .
ويجوز للبنك المركزى إعداد التقرير المشار إليه فى الفقرة الأولى من هذه المادة إذا ارتأى ضرورة لذلك دون اشتراط صدور قراره باعتبار البنك متعثراً . كما يجوز له تعيين خبير مستقل لإجراء هذا التقرير .
وذلك كله طبقاً للقواعد التى يضعها مجلس الإدارة .$m259$,'7f72de7e89f36e10f69f16ef86d92aff'),
(157,0,$m259$قانون البنك المركزى والجهاز المصرفى 194/2020 > الباب الثالث: تنظيم الجهاز المصرفى > الفصل الثانى عشر: تسوية أوضاع البنوك المتعثرة$m259$,$m259$للبنك المركزى بمجرد نشر قرار اعتبار البنك مُتعثراً اتخاذ واحد أو أكثر من الإجراءات التالية دون الحصول على موافقة أى من مساهمى البنك أو دائنيه أو مدينيه ، ودون التقيد بأحكام أى قوانين أخرى أو أى التزامات تعاقدية :
( أ ) حل مجلس إدارة البنك المتعثر وتعيين مفوض لإدارته .
( ب ) إيقاف عمليات البنك أو بعض أنشطته كلياً أو جزئياً .
( جـ ) تخفيض القيمة الاسمية لأسهم البنك أو تخفيض عدد الأسهم المصدرة .
( د ) إعادة رسملة البنك عن طريق طرح أسهم جديدة أو أى أوراق مالية أخرى قابلة للتداول .
( هـ ) تخفيض قيمة بعض التزامات البنك أو تحويلها إلى أسهم فى رأسماله أو فى البنك المعبرى .
( و ) إنهاء أو تعديل شروط أى عقد أو سند من سندات المديونية التى يكون البنك تحت التسوية طرفاً فيها .
( ز ) حوالة كل أو بعض الحقوق والالتزامات والأصول المملوكة للبنك المتعثر لبنك آخر أو للبنك المعبرى .
( ح ) دمج البنك المتعثر فى بنك آخر ، أو نقل ملكية أسهمه .
( ط ) رفع الدعاوى المدنية للمطالبة بالتعويضات واسترداد أى أموال وذلك ضد أى من المساهمين أو المسئولين الرئيسيين أو الموظفين المسئولين عن تعثر البنك .
ويسرى ذلك على فروع البنوك الأجنبية بما يتناسب مع طبيعتها .$m259$,'c2ddf6027de358f62deb077140fa3124'),
(158,0,$m259$قانون البنك المركزى والجهاز المصرفى 194/2020 > الباب الثالث: تنظيم الجهاز المصرفى > الفصل الثانى عشر: تسوية أوضاع البنوك المتعثرة$m259$,$m259$يجوز للبنك المركزى ممارسة جميع اختصاصاته المنصوص عليها فى هذا الفصل مباشرةً أو من خلال تعيين مفوض .
ويحدد البنك المركزى اختصاصات المفوض لإدارة البنك الخاضع للتسوية ، والتى قد تتضمن اختصاصات الإدارة التنفيذية ومجلس إدارة البنك وجمعيته العامة العادية وغير العادية .
ويباشر المفوض أعماله طبقاً للقواعد والتعليمات الصادرة من البنك المركزى وتحت إشرافه .
ويحدد البنك المركزى قيمة المكافأة المستحقة له ، على أن يتحملها البنك الخاضع للتسوية بالإضافة إلى أى مصروفات أو نفقات يتكبدها المفوض أثناء تنفيذ خطة التسوية .
وللبنك المركزى الحق فى تنحية المفوض أو استبداله .
ويحدد مجلس الإدارة الشروط الواجب توافرها فى المفوض ، وقواعد الحد من تعارض المصالح .$m259$,'e173f3cb1957430864d8ac45a4d0fdbc'),
(159,0,$m259$قانون البنك المركزى والجهاز المصرفى 194/2020 > الباب الثالث: تنظيم الجهاز المصرفى > الفصل الثانى عشر: تسوية أوضاع البنوك المتعثرة$m259$,$m259$إذا تطلبت إجراءات تسوية أوضاع البنك المتعثر الحصول على موافقة الهيئة العامة للرقابة المالية أو غيرها من الجهات المختصة ، فيتعين البت فى الطلب خلال ثلاثة أيام عمل من تاريخ تقديم الطلب ، وفى حالة عدم الرد خلال هذه المدة ، يعتبر ذلك موافقة ضمنية على الطلب .
ويجوز للهيئة العامة للرقابة المالية ، بناءً على طلب من البنك المركزى ، الإعفاء من شروط الإفصاح المنصوص عليها فى قانون سوق رأس المال أو تأجيلها إذا كان الإفصاح سيؤثر سلباً على عملية تسوية أوضاع البنك المتعثر .$m259$,'a12c44d98d8f56c846fa58ab668b4019'),
(160,0,$m259$قانون البنك المركزى والجهاز المصرفى 194/2020 > الباب الثالث: تنظيم الجهاز المصرفى > الفصل الثانى عشر: تسوية أوضاع البنوك المتعثرة$m259$,$m259$يلتزم كل من يقدم خدمات لازمة لعمل البنك الخاضع للتسوية بالاستمرار فى تقديمها له أو لخلفه العام أو الخاص بذات الشروط والأحكام ، وذلك بناءً على طلب من البنك المركزى .
كما يجوز للبنك المركزى إلزام البنك الخاضع للتسوية بتقديم خدمات بصفة مؤقتة لأى بنك تنقل إليه بعض الأصول أو الالتزامات على النحو المبين بالمادة ( 165 ) من هذا القانون ، كما يجوز له أن يعهد بتقديم تلك الخدمات لأى طرف آخر .$m259$,'4d18539aa441cd0ce70231e60f0584ad'),
(161,0,$m259$قانون البنك المركزى والجهاز المصرفى 194/2020 > الباب الثالث: تنظيم الجهاز المصرفى > الفصل الثانى عشر: تسوية أوضاع البنوك المتعثرة$m259$,$m259$يضع البنك المركزى ، بالتنسيق مع المفوض حال وجوده ، خطة عمل تسوية أوضاع البنك المتعثر بناءً على التقييم المشار إليه فى المادة ( 156 ) من هذا القانون ، ويجوز أن تتضمن هذه الخطة واحداً أو أكثر من الإجراءات المنصوص عليها فى المادة ( 157 ) من هذا القانون .$m259$,'074d2d3957997be246e4abf58593bd7d'),
(162,0,$m259$قانون البنك المركزى والجهاز المصرفى 194/2020 > الباب الثالث: تنظيم الجهاز المصرفى > الفصل الثانى عشر: تسوية أوضاع البنوك المتعثرة$m259$,$m259$للبنك المركزى فى حالة تخفيض القيمة الاسمية للأسهم الحالية لتعكس الخسائر الفعلية زيادة رأسمال البنك بطرح أسهم جديدة على المساهمين الحاليين القادرين على تحمل التزاماتهم تجاه البنك وثبت عدم إخلالهم مسبقاً بأى إجراء تصحيحى ، أو بطرح أسهم جديدة على مستثمرين جدد دون عرضها على المساهمين الحاليين بعد تعهدهم بتنفيذ بعض الالتزامات .
ويتعين أن تتناسب الزيادة المطلوبة فى رأسمال البنك مع المتطلبات الرقابية بما يضمن قدرته على الاستمرار ، ويتعين سداد قيمة تلك الأسهم كاملة خلال المدة التى يحددها البنك المركزى بما لا يجاوز ثلاثين يوماً من تاريخ الموافقة .
وذلك كله طبقاً للقواعد والإجراءات التى يحددها مجلس الإدارة دون التقيد بأحكام الفصل الثانى من الباب الثالث من هذا القانون ، أو بأحكام أى قانون آخر .$m259$,'c64f3083577022745c8d701a62b633f5'),
(163,0,$m259$قانون البنك المركزى والجهاز المصرفى 194/2020 > الباب الثالث: تنظيم الجهاز المصرفى > الفصل الثانى عشر: تسوية أوضاع البنوك المتعثرة$m259$,$m259$للبنك المركزى وضع خطة لجدولة كل أو بعض التزامات البنك الخاضع للتسوية أو تخفيضها أو رسملتها بما يعزز قدرته على الاستمرار ، طبقاً للإجراءات الآتية :
( أ ) تخفيض حقوق الملكية بقيمة الخسائر .
( ب ) فى حالة عدم استيعاب حقوق الملكية للخسائر ، يتم تخفيض التزامات البنك غير المستثناة من تطبيق حكم هذه المادة بعكس الترتيب المبين فى المادة ( 175 ) من هذا القانون بباقى قيمة الخسائر .
( جـ ) يتم تحويل باقى التزامات البنك غير المستثناة من تطبيق حكم هذه المادة إلى مساهمة فى رأسمال للوصول للحد الذى يراه البنك المركزى مناسباً .
ويستبعد من تلك الخطة ما يأتى :
( أ ) ودائع العملاء ، دون ودائع الأطراف المرتبطة بالبنك الخاضع للتسوية .
( ب ) مستحقات الضرائب والتأمينات الاجتماعية والبنك المركزى .
( جـ ) أى التزام ناشئ عن الاحتفاظ بأصول العميل أو تجنيبها .
( د ) الديون المضمونة بكفالة أو أصول منقولة أو عقارية .
( هـ ) أجور العاملين بالبنك .
( و ) الالتزامات المستحقة لنظم الدفع والمقاصة والتسوية اللحظية خلال سبعة أيام .
وللبنك المركزى استبعاد أى التزامات أخرى من تطبيق أحكام هذه المادة فى حالات الضرورة حماية لاستقرار النظام المصرفى من انعكاس الآثار السلبية للبنك المتعثر على باقى البنوك أو لزيادة قيمة البنك الخاضع للتسوية لصالح جماعة الدائنين .
ويكون قرار البنك المركزى بجدولة كل أو بعض التزامات البنك أو تخفيضه أو رسملته نافذاً ومنتجاً لآثاره القانونية دون التقيد بأحكام أى قوانين أخرى أو أى التزامات تعاقدية .
وللبنك المركزى إلزام البنوك بالاحتفاظ بالتزامات غير المستثناة من تطبيق أحكام الفقرة الأولى من هذه المادة بما يتناسب مع مدى تعقد نموذج أعمال كل بنك وحجمه وطبيعة عملياته وأنشطته .
وذلك كله على النحو الذى يحدده مجلس الإدارة .$m259$,'57654f91a033f99acb56aafbc9b56ece'),
(164,0,$m259$قانون البنك المركزى والجهاز المصرفى 194/2020 > الباب الثالث: تنظيم الجهاز المصرفى > الفصل الثانى عشر: تسوية أوضاع البنوك المتعثرة$m259$,$m259$للبنك المركزى عند تسوية أوضاع أى من البنوك المتعثرة أن يقرر دمج البنك المتعثر مع بنك آخر ، أو نقل ملكية أسهمه أو بعضها إلى مستثمر آخر أو إلى بنك معبرى ، وذلك بشرط موافقة البنك الآخر أو البنك المعبرى ، وذلك كله طبقاً للقواعد والإجراءات التى يحددها مجلس الإدارة .
ويعد قراره فى هذا الشأن نافذاً ومنتجاً لآثاره القانونية دون التقيد بأحكام القوانين الأخرى .
ويجوز للبنك المركزى لأغراض تطبيق أحكام هذه المادة إصدار أسهم جديدة أو إلغاء الأسهم الحالية للبنك الخاضع للتسوية حال تلاشى كل حقوق الملكية أو بعضها .$m259$,'7f159962f275fbab39080c79c22e2c7d'),
(165,0,$m259$قانون البنك المركزى والجهاز المصرفى 194/2020 > الباب الثالث: تنظيم الجهاز المصرفى > الفصل الثانى عشر: تسوية أوضاع البنوك المتعثرة$m259$,$m259$يجوز للبنك المركزى نقل كل أصول والتزامات البنك الخاضع للتسوية أو بعضها إلى بنك آخر أو إلى البنك المعبرى بمراعاة ألا تزيد قيمة الالتزامات المنقولة للبنك المعبرى على إجمالى قيمة الأصول المنقولة إليه . ويعد قراره فى هذا الشأن نافذاً ومنتجاً لآثاره القانونية دون التقيد بأحكام أى قوانين أخرى أو التزامات تعاقدية ، وذلك بشرط موافقة البنك المنقول إليه تلك الأصول والالتزامات .
ويودع ذلك القرار مكتب الشهر العقارى المختص وبورصة الأوراق المالية وشركة الإيداع والقيد المركزى وغيرها من الجهات ذات الصلة ، كل فيما يخصه ، بدون سداد أى رسوم ، ويترتب على هذا الإيداع بالنسبة للعقارات الواردة به جميع الآثار القانونية المترتبة على الشهر .
ويئول ناتج تلك العملية إن وجد ، إلى البنك الخاضع للتسوية ، كما يصبح البنك المشترى أو المعبرى خلفاً له فى جميع الأصول والالتزامات التى تم نقلها .
وبالنسبة للالتزامات المكفولة بضمانات ، فللبنك المركزى إما أن يقرر نقلهما معاً أو الإبقاء عليهما بالبنك الخاضع للتسوية ، أو أن يقرر الفصل بين الالتزامات والضمانات التى تكفلها شريطة استبدالها بضمانات أخرى كافية .
وفى حالة وجود عقود مالية قابلة للانقضاء بالمقاصة بين البنك الخاضع للتسوية وطرف آخر ، فلا ينتقل أحدها دون الآخر ما لم يكن ذلك ضرورياً لتحقيق أهداف التسوية .
كما يجوز للبنك المركزى حال وجود فروق تقييم إعادة بعض تلك الحقوق أو الالتزامات إلى البنك الخاضع للتسوية مرة أخرى أو تسوية قيمة هذه الفروق ، بموافقة البنك المشترى ، وذلك خلال المدة التى يحددها مجلس الإدارة .
ولا يكون لمساهمى أو دائنى البنك الذين لم تنقل حقوقهم أو التزاماتهم الحق فى المطالبة بأى حقوق مرتبطة بالحقوق أو الالتزامات المنقولة للبنك المشترى أو المعبرى .
ويحدد مجلس الإدارة قواعد وضوابط وإجراءات طرح ونقل أصول والتزامات البنوك المتعثرة ، وذلك دون التقيد بأحكام أى قوانين أخرى ، وبمراعاة اعتبارات السرية وخطورة حالات التعثر على الاستقرار المصرفى .
ويلتزم مجلس الإدارة بإلغاء ترخيص البنك الخاضع للتسوية عقب إتمام عملية نقل الأصول والالتزامات على النحو المبين بهذه المادة ، ويترتب على هذا القرار تصفية البنك طبقاً لأحكام هذا القانون وذلك ما لم يقرر مجلس الإدارة ملاءمة استمرار البنك الخاضع للتسوية للقيام بمهامه الرئيسية للحفاظ على الاستقرار المصرفى .$m259$,'4bc30ee528218cb4738052819e0a6cee'),
(166,0,$m259$قانون البنك المركزى والجهاز المصرفى 194/2020 > الباب الثالث: تنظيم الجهاز المصرفى > الفصل الثانى عشر: تسوية أوضاع البنوك المتعثرة$m259$,$m259$مع مراعاة أحكام المادة ( 64 ) من هذا القانون ، يجوز لوزارة المالية بناءً على طلب البنك المركزى تأسيس بنك معبرى لإدارة الأصول والالتزامات المنقولة إليه من البنك الخاضع للتسوية .
وللبنك المركزى تحديد الأنشطة التى يجوز للبنك المعبرى مباشرتها . كما يجوز إعفاؤه من أى من المتطلبات الرقابية لمدة لا تجاوز سنة إذا اقتضى ذلك استقرار النظام المصرفى ، ويتولى البنك المركزى تعيين من يقوم بإدارة البنك المعبرى من غير العاملين به وتحديد مسئولياته ، ويخضع للتعليمات الصادرة له من البنك المركزى ، ويمارس البنك المعبرى نشاطه لفترة مؤقتة لحين نقل كل أو بعض أصوله والتزاماته لبنك آخر ، أو نقل ملكية أسهمه لمشتر أو مستثمر جديد ، أو دمجه فى بنك آخر فى أقرب وقت ممكن ، وذلك طبقاً لخطة التخارج التى يعدها البنك المعبرى ويعتمدها البنك المركزى .
ويلتزم البنك المركزى بإلغاء ترخيص البنك المعبرى والسير فى إجراءات تصفيته على النحو المبين فى هذا القانون عقب تنفيذ خطة التخارج .
وذلك كله على النحو الذى تنظمه القواعد الصادرة عن مجلس الإدارة .$m259$,'67abf1623a1a17579482fb3500ea29d9'),
(167,0,$m259$قانون البنك المركزى والجهاز المصرفى 194/2020 > الباب الثالث: تنظيم الجهاز المصرفى > الفصل الثانى عشر: تسوية أوضاع البنوك المتعثرة$m259$,$m259$يلتزم البنك المركزى عند اتخاذ إجراءات التسوية بمراعاة الآتى :
( أ ) ترتيب أولوية الدائنين المبين فى المادة ( 175 ) من هذا القانون ، وذلك دون الإخلال بسلطة البنك المركزى فى استبعاد أى التزامات على النحو المبين فى الفقرة الثانية من المادة ( 163 ) من هذا القانون .
( ب ) تطبيق مبدأ المعاملة بالمثل للدائنين من ذات المرتبة ، إلا إذا كان عدم التقيد بذلك ضرورياً لحماية استقرار النظام المصرفى من انعكاس الآثار السلبية للبنك المتعثر على باقى البنوك أو لزيادة قيمة البنك الخاضع للتسوية لصالح جماعة الدائنين .
وفى حالة تحمل أى من الدائنين أو المساهمين نتيجة لتسوية أوضاع البنك المتعثر خسائر أكبر مما كان سيتحملها لو تم تصفية البنك طبقاً لأحكام قانون تنظيم إعادة الهيكلة والصلح الواقى والإفلاس الصادر بالقانون رقم 11 لسنة 2018 بأولوية ترتيب الدائنين المنصوص عليها بالمادة ( 175 ) من هذا القانون ، يتم تعويضهم عن تلك الخسائر من صندوق تسوية أوضاع البنوك المتعثرة ، ويتم تقييم هذه الخسائر بواسطة خبير مستقل يعينه البنك المركزى ، مع مراعاة استبعاد ما تقدمه الحكومة من دعم مالى للبنك الخاضع للتسوية ، وذلك كله طبقاً للقواعد والإجراءات التى يصدر بتحديدها قرار من مجلس الإدارة .$m259$,'0afcde7aab823b09b3a10620d379d488'),
(168,0,$m259$قانون البنك المركزى والجهاز المصرفى 194/2020 > الباب الثالث: تنظيم الجهاز المصرفى > الفصل الثانى عشر: تسوية أوضاع البنوك المتعثرة$m259$,$m259$مع عدم الإخلال بحقوق الغير حسنى النية ، يجوز لذوى الشأن الطعن فى القرارات الصادرة من البنك المركزى أو المفوض أمام محكمة القضاء الإدارى خلال 30 يوماً من تاريخ الإخطار بالقرار أو العلم به .
فإذا تبين للمحكمة تعذر إعادة الحال إلى ما كان عليه فى ضوء عدد أو قيمة أو تعقد العمليات الناشئة عن القرار المطعون فيه ، أو كان يترتب على إلغائه ضرر جسيم بالنظام المالى والمصرفى فى الدولة أو حقوق المودعين فى البنك الخاضع للتسوية ، جاز لها الحكم بالتعويض النقدى .$m259$,'4cc8cab55cc0c8c71445c8a336012c62'),
(169,0,$m259$قانون البنك المركزى والجهاز المصرفى 194/2020 > الباب الثالث: تنظيم الجهاز المصرفى > الفصل الثانى عشر: تسوية أوضاع البنوك المتعثرة$m259$,$m259$ينشأ بقرار من مجلس الإدارة صندوق لتمويل إجراءات تسوية أوضاع البنوك المتعثرة ، ويتبع البنك المركزى ، وتكون له شخصية اعتبارية وميزانية مستقلة ، ويضم الصندوق فى عضويته جميع البنوك ، ويكون له مجلس إدارة يصدر بتشكيله قرار من مجلس الإدارة ، ويكون مقره محافظة القاهرة ، ويمثل الصندوق رئيس مجلس إدارته أمام القضاء والغير .
وتتكون موارد الصندوق من مساهمات البنوك وعائد استثمار أمواله وغيرها من مصادر التمويل ، ويكون المستهدف تكوينه كحصيلة للصندوق مبلغ يقابل نسبة نصف فى المائة من قيمة ودائع البنوك ، على أن يتم تكوين كامل المبلغ المستهدف خلال عشر سنوات من تاريخ العمل بأحكام هذا القانون ، وذلك كله طبقاً للضوابط والإجراءات التى يحددها مجلس الإدارة .
ويحدد مجلس الإدارة قواعد تحصيل المساهمات السنوية للبنوك ، لحين الوصول للمبلغ المستهدف ، بمراعاة الآتى :
( أ ) حصة كل بنك فى إجمالى ودائع الجهاز المصرفى .
( ب ) حجم مخاطر كل بنك .
( جـ ) قوة وسلامة المركز المالى للبنك .
( د ) مدى احتمالية اتخاذ أى من إجراءات التسوية فى شأن كل بنك .
( هـ ) درجة تعقد هيكل المساهمات بين البنك وشركاته التابعة .
( و ) مدى تأثير البنك فى النظام المصرفى .
( ز ) نسبة إجمالى الالتزامات لدى كل بنك إلى إجمالى الالتزامات بالجهاز المصرفى .
ويحظر استخدام موارد الصندوق فى تمويل إجراءات تسوية أى من البنوك المتعثرة إلا بعد تحمل المساهمين ، وحاملى أدوات الدين الداخلة فى القاعدة الرأسمالية ، والدائنين طبقاً للضوابط المقررة فى المادة ( 163 ) من هذا القانون ، بقيمة الخسائر .
وفى حالة عدم كفاية موارد الصندوق لتغطية التمويل اللازم لإتمام عملية التسوية ، يجوز للبنك المركزى طلب مساهمات إضافية من البنوك لا يتجاوز قيمتها مبلغ المساهمة السنوى لكل بنك وعلى أن يتم تسويتها لاحقاً .
ويصدر بالنظام الأساسى للصندوق قرار من مجلس الإدارة ، ويرحل فائض أموال الصندوق من سنة مالية لأخرى .$m259$,'cd0e926b10d0d57ede6f241efaa5410e'),
(170,0,$m259$قانون البنك المركزى والجهاز المصرفى 194/2020 > الباب الثالث: تنظيم الجهاز المصرفى > الفصل الثانى عشر: تسوية أوضاع البنوك المتعثرة$m259$,$m259$فى حالة عدم كفاية موارد الصندوق الأصلية والإضافية المشار إليها فى المادة ( 169 ) من هذا القانون لتحمل تكلفة التسوية ، يجوز لوزارة المالية بالتنسيق مع البنك المركزى أن تقدم قويلاً مؤقتاً للصندوق لاستكمال عملية التسوية إذا كان ذلك ضرورياً للحفاظ على استقرار النظام المالى والمصرفى فى مصر .
ويقدم التمويل المؤقت فى صورة زيادة أو مشاركة فى رأسمال البنك المعبرى أو أدوات دين أو تقديم ضمانات للبنك الخاضع لعملية التسوية أو أى نوع من أنواع الدعم المطلوبة لتنفيذ إجراءات التسوية المنصوص عليها فى هذا الفصل ، بعد التأكد من أن البنك المقدم له التمويل المؤقت ستتم إدارته بطريقة تجارية ومهنية .
ويعد البنك المركزى بالاتفاق مع وزارة المالية القواعد الخاصة بتقديم ذلك التمويل المؤقت واسترداده حال عدم كفاية موارد الصندوق ، وذلك بتحديد آلية الرجوع على البنوك طبقاً للضوابط المنصوص عليها فى الفقرة الثالثة من المادة ( 169 ) من هذا القانون على أن تتناول تلك القواعد أساس حساب المبالغ المطلوب استردادها .$m259$,'5c7fe20bb2bf03cb565ed4c270997533'),
(171,0,$m259$قانون البنك المركزى والجهاز المصرفى 194/2020 > الباب الثالث: تنظيم الجهاز المصرفى > الفصل الثانى عشر: تسوية أوضاع البنوك المتعثرة$m259$,$m259$تلتزم إدارة الإفلاس بالمحكمة الاقتصادية المختصة بنظر الدعاوى المتعلقة بإعادة الهيكلة أو الصلح الواقى من الإفلاس أو شهر إفلاس إحدى الشركات التابعة أو الشقيقة أو الشركة الأم لأى من البنوك ، بأن تخطر البنك المركزى بذلك ليقدم تقريراً برأيه فى الدعوى خلال ثلاثين يوماً من تاريخ إخطاره .$m259$,'f41c0c8242a4f3c0782be3edf2885c0b'),
(172,0,$m259$قانون البنك المركزى والجهاز المصرفى 194/2020 > الباب الثالث: تنظيم الجهاز المصرفى > الفصل الثالث عشر: إلغاء تراخيص البنوك$m259$,$m259$لا يجوز لأى بنك وقف عملياته جزئياً أو كلياً إلا بموافقة مسبقة من مجلس الإدارة .
وتصدر الموافقة فى حالات الوقف الكلى بعد التثبت من أن البنك قد قدم ضمانات كافية أو أبرأ ذمته نهائياً من التزاماته القانونية ، وعلى الأخص التزاماته قبل أصحاب الودائع وغيرهم من الدائنين وحقوق العاملين .
وذلك كله طبقاً للشروط والإجراءات التى يصدر بها قرار من مجلس الإدارة .
وينشر القرار الصادر فى هذا الشأن فى الوقائع المصرية وعلى الموقع الإلكترونى لكل من البنك المركزى والبنك المعنى .$m259$,'cfa86a2c69fa26a7c998fe3308dc63a7'),
(173,0,$m259$قانون البنك المركزى والجهاز المصرفى 194/2020 > الباب الثالث: تنظيم الجهاز المصرفى > الفصل الثالث عشر: إلغاء تراخيص البنوك$m259$,$m259$يجوز إلغاء ترخيص البنك وشطب تسجيله بقرار من مجلس الإدارة فى الأحوال الآتية :
( أ ) إذا ارتكب مخالفة جسيمة أو متكررة لأحكام هذا القانون أو القرارات الصادرة تنفيذاً له ، ولم يقم بإزالة المخالفة خلال المدة وبالشروط التى يحددها مجلس الإدارة .
( ب ) إذا اتبع سياسة من شأنها الإضرار بالمصلحة الاقتصادية العامة أو بالسياسة النقدية أو بالنظام المصرفى أو بمصالح المودعين .
( جـ ) إذا توقف عن مزاولة نشاطه أو تقدم بطلب لإيقاف نشاطه وتصفيته اختيارياً .
( د ) إذا تحققت أى من حالات اعتبار البنك متعثراً طبقاً للمادة ( 153 ) من هذا القانون وارتأى البنك المركزى عدم ملائمة تسوية أوضاع البنك المتعثر وقرر تصفيته .
( هـ ) إذا تبين أن الترخيص له تم بناء على بيانات خاطئة قدمها إلى البنك المركزى .
( و ) إذا فقد شرطاً من شروط الترخيص .
( ز ) إذا حدث تغيير جوهرى فى البيانات التى مُنح الترخيص بناءً عليها .
كما يجوز لمجلس الإدارة إلغاء ترخيص البنك الخاضع للتسوية وشطب تسجيله وذلك فى الأحوال الآتية :
( أ ) عدم قابلية البنك للإصلاح أو لإعادة الهيكلة .
( ب ) نقل أصول البنك أو التزاماته جزئياً أو كلياً إلى بنك آخر أو للبنك المعبرى .
ولا يصدر قرار الإلغاء والشطب إلا بعد إعلان البنك المعنى ليقدم أوجه دفاعه كتابة خلال خمسة عشر يوماً من تاريخ الإعلان .
ويُنشر قرار إلغاء الترخيص والشطب فى الوقائع المصرية خلال عشرة أيام من تاريخ صدوره وعلى الموقع الإلكترونى لكل من البنك المركزى والبنك المعنى طوال فترة التصفية .$m259$,'6dff6870665068b6250bee8cd5c5b086'),
(174,0,$m259$قانون البنك المركزى والجهاز المصرفى 194/2020 > الباب الثالث: تنظيم الجهاز المصرفى > الفصل الثالث عشر: إلغاء تراخيص البنوك$m259$,$m259$مع عدم الإخلال بمصالح المتعاملين مع البنك ، يترتب على إلغاء الترخيص وقف البنك عن مباشرة العمل وتصفيته ، وفى هذه الحالة لمجلس الإدارة إما أن يقرر تصفية أعمال البنك فوراً أو أن يرخص له مؤقتاً بمباشرة العمليات القائمة وقت الشطب بالشروط التى يحددها لذلك .$m259$,'7fd9bd10277047c27df81b7ad205e80e'),
(175,0,$m259$قانون البنك المركزى والجهاز المصرفى 194/2020 > الباب الثالث: تنظيم الجهاز المصرفى > الفصل الثالث عشر: إلغاء تراخيص البنوك$m259$,$m259$دون التقيد بأحكام أى قوانين أخرى ، تكون أولوية استيفاء الدائنين لديونهم من البنك الخاضع للتصفية فى حالة عدم كفاية أصوله لتغطية التزاماته ، وعقب تسوية وسداد الديون المضمونة برهون أو المقيدة بسجل الضمانات المنقولة أو بتسليم الدائنين للضمانات المرهونة ، طبقاً للترتيب الآتى :
( أ ) مصروفات المصفى والمفوض .
( ب ) ودائع العملاء ، باستثناء ودائع الأطراف المرتبطة بالبنك الخاضع للتصفية .
( جـ ) الأجور المستحقة للعاملين بالبنك الخاضع للتصفية خلال الستة أشهر السابقة على تعيين المصفى .
( د ) مستحقات الحكومة جراء تمويل عمليات التسوية أو التمويل الذى يقدمه البنك المركزى نيابة عن الحكومة .
( هـ ) مستحقات الضرائب والتأمينات للعامين السابقين على تعيين المصفى .
( و ) مستحقات صندوق تمويل إجراءات تسوية أوضاع البنوك المتعثرة .
( ز ) الديون الممنوحة للبنك من القطاع الخاص بعد إعلان تسوية أوضاعه أو تعيين مصف .
( ح ) الديون غير المضمونة .
على أن يعامل الدائنون من ذات المرتبة ذات المعاملة ، ولا يحق لدائنى المرتبة الأدنى المطالبة بمستحقاتهم إلا عقب تسوية مديونية المرتبة الأعلى .$m259$,'b6f841c9de83ae5d3d8be7730e1682d2'),
(176,0,$m259$قانون البنك المركزى والجهاز المصرفى 194/2020 > الباب الثالث: تنظيم الجهاز المصرفى > الفصل الرابع عشر: صندوقا التأمين على الودائع وتطوير الجهاز المصرفى$m259$,$m259$يتبع صندوق التأمين على الودائع البنك المركزى ، وتكون له شخصية اعتبارية وميزانية مستقلة ، ويضم الصندوق فى عضويته جميع البنوك ، ويكون له مجلس إدارة برئاسة المحافظ ، ويكون مقره محافظة القاهرة ، ويمثل الصندوق رئيس مجلس إدارته أمام القضاء والغير .
ويصدر بالنظام الأساسى للصندوق قرار من مجلس الإدارة بناء على اقتراح المحافظ ، ويجب أن يتضمن النظام الأساسى على الأخص ما يأتى :
( أ ) وسائل تحقيق أغراض الصندوق وتنظيم العلاقة بينه وبين البنوك .
( ب ) تشكيل مجلس إدارة الصندوق ونظام العمل به .
( جـ ) تحديد اشتراك العضوية والاشتراكات السنوية للبنوك .
( د ) نطاق ضمان الودائع وتحديد الحد الأقصى للضمان .
( هـ ) الموارد المالية للصندوق وقواعد وأوجه الصرف منها .
( و ) نظام مراجعة حسابات الصندوق .
ويرحل فائض أموال الصندوق من سنة لأخرى .$m259$,'bf380961b4662cb731523ca450b493e3'),
(177,0,$m259$قانون البنك المركزى والجهاز المصرفى 194/2020 > الباب الثالث: تنظيم الجهاز المصرفى > الفصل الرابع عشر: صندوقا التأمين على الودائع وتطوير الجهاز المصرفى$m259$,$m259$لمجلس الإدارة بناءً على اقتراح مجلس إدارة صندوق التأمين على الودائع اتخاذ أى من الإجراءات الآتية فى حالة مخالفة أى بنك لأحكام النظام الأساسى للصندوق أو القرارات الصادرة تنفيذاً له :
( أ ) توجيه تنبيه .
( ب ) إلزام البنك بسداد مبلغ لا يجاوز ( 5% ) من قيمة آخر اشتراك سنوى للبنك ، يزاد إلى ( 10% ) فى حالة تكرار المخالفة ، وتضاف حصيلة هذه المبالغ إلى موارد الصندوق .$m259$,'e73c09c7e0afd4bd2fb7013aee5f988e'),
(178,0,$m259$قانون البنك المركزى والجهاز المصرفى 194/2020 > الباب الثالث: تنظيم الجهاز المصرفى > الفصل الرابع عشر: صندوقا التأمين على الودائع وتطوير الجهاز المصرفى$m259$,$m259$ينشأ صندوق لدعم وتطوير الجهاز المصرفى ، تكون له شخصية اعتبارية وميزانية مستقلة ، ويتبع البنك المركزى ، ويكون مقره محافظة القاهرة ، ويضم فى عضويته جميع البنوك ، ويختص بالعمل على تطوير الجهاز المصرفى وتعزيز بنيته التحتية بهدف مسايرة التطور العالمى وترسيخ قواعد العمل المهنى السليم .
ويتكون مجلس إدارة الصندوق من أحد عشر عضواً برئاسة المحافظ وعضوية نائبى المحافظ وخمسة أعضاء من بين رؤساء مجالس إدارات البنوك تنتخبهم البنوك ، وثلاثة أعضاء مستقلين من ذوى الخبرة يختارهم مجلس الإدارة ، ويمثله رئيس مجلس إدارته أمام القضاء والغير ، ويراجع حسابات الصندوق اثنان من مراقبى الحسابات المقيدين فى سجل مراقبى الحسابات لدى البنك المركزى .
وتتكون موارد هذا الصندوق من :
( أ ) مبلغ يعادل نسبة لا تزيد على ( 1% ) من صافى الأرباح السنوية القابلة للتوزيع عن العام المالى السابق لكل بنك من البنوك .
( ب ) الهبات والتبرعات والمعونات التى يوافق مجلس إدارة الصندوق على قبولها لهذا الغرض .
ويصدر بالنظام الأساسى للصندوق قرار من مجلس الإدارة ، ويرحل فائض أمواله من سنة لأخرى .$m259$,'292f3296bc472017de8cf54daf544627'),
(179,0,$m259$قانون البنك المركزى والجهاز المصرفى 194/2020 > الباب الثالث: تنظيم الجهاز المصرفى > الفصل الخامس عشر: اتحاد البنوك ، والمعهد المصرفى$m259$,$m259$يعمل اتحاد البنوك على ترسيخ مفاهيم العمل المصرفى السليم ، وتوثيق أواصر التعاون بين البنوك ، وتكون له شخصية اعتبارية وميزانية مستقلة ، ويمثله رئيس مجلس إدارته أمام القضاء والغير ، ويصدر بنظامه الأساسى قرار من مجلس الإدارة ، يتضمن على الأخص :
( أ ) تشكيل مجلس إدارة الاتحاد ونظام العمل به .
( ب ) تحديد اشتراك العضوية والاشتراكات السنوية للبنوك .
( جـ ) الموارد المالية للاتحاد .
( د ) نظام مراجعة حسابات الاتحاد .
وعلى كل بنك أو فرع بنك أجنبى مسجل لدى البنك المركزى الانضمام إلى الاتحاد ويلتزم بمراعاة نظامه وبالمعايير التى يحددها .
ولا تسرى المعايير والقواعد المهنية التى يضعها الاتحاد إلا بعد اعتمادها من مجلس الإدارة .
ويعين المحافظ ممثلاً لدى الاتحاد ، يكون له الحق فى حضور جلساته والاشتراك فى مناقشاته دون أن يكون له صوت معدود فى المداولات .
وينشر النظام الأساسى وأى تعديل يطرأ عليه بعد موافقة مجلس الإدارة فى الوقائع المصرية على نفقة الاتحاد وعلى الموقع الإلكترونى له .$m259$,'858d26ce471a6b1299f320eecca78823'),
(180,0,$m259$قانون البنك المركزى والجهاز المصرفى 194/2020 > الباب الثالث: تنظيم الجهاز المصرفى > الفصل الخامس عشر: اتحاد البنوك ، والمعهد المصرفى$m259$,$m259$يتبع المعهد المصرفى البنك المركزى ، وتكون له شخصية اعتبارية وموازنة مستقلة ، وتصدر له قوائم مالية سنوية ، وتبدأ السنة المالية للمعهد فى بداية السنة المالية للدولة وتنتهى بنهايتها ، ويرحل الفائض أو العجز إلى ميزانية العام التالى ، ويكون مقره الرئيسى بمحافظة القاهرة ، ويجوز له إنشاء فروع خارجها .
ويعمل المعهد على تنمية المهارات فى الأعمال المصرفية والمالية والنقدية والقانونية ونظم وخدمات الدفع وتكنولوجيا وأمن المعلومات ومكافحة غسل الأموال وتمويل الإرهاب ، وذلك للعاملين بالبنك المركزى والبنوك والجهات العاملة فى هذه المجالات بهدف مسايرة التطور العالمى وترسيخ قواعد العمل المهنى السليم .
ويجوز للمعهد الاستعانة بالخبرات العالمية فى دعم قدراته ، كما يجوز له إيفاد بعثات للخارج للتعرف على المستحدثات فى مجال أعماله .
ويصدر بالنظام الأساسى للمعهد قرار من مجلس الإدارة .$m259$,'ba4459b3f24f643abbe492407d575195'),
(181,0,$m259$قانون البنك المركزى والجهاز المصرفى 194/2020 > الباب الثالث: تنظيم الجهاز المصرفى > الفصل الخامس عشر: اتحاد البنوك ، والمعهد المصرفى$m259$,$m259$يكون للمعهد المصرفى مجلس إدارة لا يزيد عدد أعضائه على تسعة ، وتكون مدة المجلس أربع سنوات قابلة للتجديد ، ويصدر بتشكيله قرار من مجلس الإدارة ، ويمثل المعهد رئيس مجلس إدارته أمام القضاء وفى صلاته بالغير .
ويكون للمعهد مدير تنفيذى ، يتم اختياره من ذوى الخبرة ، ويصدر بتعيينه قرار من مجلس إدارة المعهد .$m259$,'5627b07215aab6a347f00eee229d29c6'),
(182,0,$m259$قانون البنك المركزى والجهاز المصرفى 194/2020 > الباب الثالث: تنظيم الجهاز المصرفى > الفصل الخامس عشر: اتحاد البنوك ، والمعهد المصرفى$m259$,$m259$يضع مجلس إدارة المعهد المصرفى سياسته العامة ويتابع تنفيذها ، وله على الأخص ما يأتى :
( أ ) إصدار اللائحة المالية ولائحة تنظيم التعاقدات ولائحة شئون العاملين وأى لوائح أخرى تنظم عمل المعهد وكيفية إدارته ، وذلك دون التقيد بالقوانين واللوائح المعمول بها فى الجهاز الإدارى للدولة أو الهيئات العامة .
( ب ) إنشاء فروع للمعهد خارج محافظة القاهرة .
( جـ ) توثيق العلاقات والروابط بين المعهد وغيره من المعاهد والمراكز المناظرة له فى الداخل والخارج .
( د ) اعتماد برامج التدريب السنوية للمعهد وتقارير متابعة تنفيذها .
( هـ ) وضع قواعد اختيار هيئة التدريب والمحاضرين .
( و ) وضع قواعد المعاملة المالية للمدربين والفنيين والباحثين به .
( ز ) اعتماد الموازنة التقديرية والقوائم المالية والتقارير عن مركزه المالى ونتائج أعماله وإخطار مجلس الإدارة بنسخ منها .$m259$,'e2c1356af1365fff32ce427807f89dfe'),
(183,0,$m259$قانون البنك المركزى والجهاز المصرفى 194/2020 > الباب الثالث: تنظيم الجهاز المصرفى > الفصل الخامس عشر: اتحاد البنوك ، والمعهد المصرفى$m259$,$m259$تتكون موارد المعهد المصرفى من :
( أ ) الاعتمادات التى يخصصها له البنك المركزى .
( ب ) الإعانات التى ترد إلى المعهد من الجهات المختلفة ، ويقرر مجلس الإدارة قبولها .
( جـ ) الاشتراكات والمساهمات السنوية التى تؤديها البنوك والجهات المختلفة مقابل تدريب العاملين بها ويصدر بتحديدها قرار من مجلس الإدارة بناءً على اقتراح مجلس إدارة المعهد .
( د ) مقابل الخدمات التى يؤديها المعهد للغير ويعتمدها مجلس الإدارة .$m259$,'3bbf9b995d8530ea75e876258288fb47'),
(184,0,$m259$قانون البنك المركزى والجهاز المصرفى 194/2020 > الباب الرابع: نظم وخدمات الدفع والتكنولوجيا المالية > الفصل الأول: نظم وخدمات الدفع$m259$,$m259$يحظر على أى شخص طبيعى أو اعتبارى غير مرخص له طبقاً لأحكام هذا الفصل مزاولة أى نشاط يتضمن تشغيل نظم الدفع أو تقديم خدمات الدفع سواء كان ذلك من داخل جمهورية مصر العربية أو من خارجها للمقيمين فيها ويشمل ذلك الجهات المنشأة بموجب قوانين خاصة .
ويحظر على أى منشأة غير مُسجلة طبقاً لأحكام هذا الفصل أن تستعمل كلمة "مُشغل نظم دفع" أو "مقدم خدمات دفع" أو أى تعبير يماثلها فى أى لغة ، سواء فى تسميتها الخاصة أو فى عنوانها التجارى أو فى دعايتها إذا كان من شأن ذلك أن يثير اللبس لدى الجمهور .
ويجوز للبنك المركزى إنشاء نظم الدفع وتشغيلها دون التقيد بأحكام هذا الفصل .
وفى تطبيق أحكام هذا القانون ، لا يعد من نظم الدفع أو خدمات الدفع كل من :
بورصات الأوراق والأدوات المالية ، وبورصات العقود الآجلة ، ونظم تسوية الأوراق والأدوات المالية ، والشركات المرخص لها بمباشرة عمليات الإيداع والقيد المركزى للأوراق والأدوات المالية ، وأمناء الحفظ ، والنظم الداخلية لوزارة المالية التى لا تتضمن سداد أو تحصيل أموال من المتعاملين معها من موظفى الدولة أو من الأشخاص الطبيعية أو الاعتبارية الأخرى وما يترتب عليها من مقاصة أو تسوية أموال .$m259$,'74725414b07a4e200c25b042cbc1d52b'),
(185,0,$m259$قانون البنك المركزى والجهاز المصرفى 194/2020 > الباب الرابع: نظم وخدمات الدفع والتكنولوجيا المالية > الفصل الأول: نظم وخدمات الدفع$m259$,$m259$يصدر بتحديد شروط وإجراءات منح تراخيص تشغيل نظم الدفع أو تقديم خدمات الدفع قرار من مجلس الإدارة يتضمن على الأخص الحد الأدنى لرأس المال ، والشكل القانونى ، ومتطلبات الكفاءة الفنية والملاءة المالية وحسن السمعة لطالب الترخيص ، والإفصاح عن هيكل الملكية ، والتكنولوجيا المستخدمة ، ومقاييس جودة تقديم الخدمة ، والقواعد اللازمة للتشغيل ، ورسوم فحص طلب الترخيص بما لا يجاوز خمسمائة ألف جنيه لمشغل نظام الدفع ، ومائة ألف جنيه لمقدم خدمات الدفع .
ويتم البت فى طلب الترخيص خلال تسعين يوماً من تاريخ تقديمه مستوفياً المستندات المطلوبة ، ويجوز لمجلس الإدارة مد هذه المهلة لمدة أخرى مماثلة .
وينشر القرار الصادر من مجلس الإدارة بقبول طلب الترخيص على الموقع الإلكترونى للبنك المركزى على أن يتضمن الأنشطة والخدمات التى يجوز مزاولتها وما إذا كان محدد المدة أو مشروطاً .
ويرفض طلب الترخيص بقرار من مجلس الإدارة ، ويخطر به الطالب خلال ثلاثين يوماً من تاريخ صدوره .
ويتم تسجيل مشغلى نظم الدفع ومقدمى خدمات الدفع المرخص لهم فى سجل خاص يعد لهذا الغرض بالبنك المركزى وذلك بعد أداء رسم معاينة لا يزيد على خمسمائة ألف جنيه بالنسبة لمشغلى نظم الدفع ، ومائتى ألف جنيه بالنسبة لمقدمى خدمات الدفع .$m259$,'adde301e4a14f0b1e72f7ae3c0bed4b7'),
(186,0,$m259$قانون البنك المركزى والجهاز المصرفى 194/2020 > الباب الرابع: نظم وخدمات الدفع والتكنولوجيا المالية > الفصل الأول: نظم وخدمات الدفع$m259$,$m259$يضع مجلس الإدارة قواعد للرقابة والإشراف على كل من مشغلى نظم الدفع ومقدمى خدمات الدفع ، وله فرض معايير أو ضوابط أو قواعد محددة على أى مشغل نظام دفع أو مقدم خدمة دفع حال توافر ظروف تستدعى ذلك ، وتشمل على الأخص :
( أ ) قواعد التشغيل البينى بين نظم الدفع .
( ب ) شروط ومواصفات الهيكل التنظيمى . وإجراءات الحوكمة ، وإدارة المخاطر .
( جـ ) متطلبات الرقابة المكتبية والتفتيش المبدانى .
( د ) آلية إصدار معايير أداء الخدمة ومؤشرات الأداء الرئيسية ونشرها .
( هـ ) قواعد تقديم خدمات الدفع .
( و ) ضوابط التعاقد مع شركات التعهيد ، ونطاق الخدمات التى تقدمها ، وآلية اعتمادها من البنك المركزى ، ورقابته عليها .
( ز ) قواعد ضمان وحماية أموال العملاء .
( ح ) قواعد وشروط أوامر الدفع .
( ط ) قواعد الإفصاح والشفافية .
( ى ) قواعد تحديد أسعار الخدمات .$m259$,'5171097acb4336f0f9244773da121795'),
(187,0,$m259$قانون البنك المركزى والجهاز المصرفى 194/2020 > الباب الرابع: نظم وخدمات الدفع والتكنولوجيا المالية > الفصل الأول: نظم وخدمات الدفع$m259$,$m259$للبنك المركزى إلزام مشغل نظام الدفع بإنشاء صندوق لضمان المخاطر التشغيلية المرتبطة به والمخاطر التجارية الناشئة عن إخلال أى من مشاركيه بالتزاماتهم بمراعاة أهميته النظامية وحجم أعماله وذلك طبقاً للقواعد والشروط والإجراءات التى يصدر بتحديدها قرار من مجلس الإدارة ، يتضمن على الأخص تحديد قواعد مساهمة المشاركين فيه والصرف منه .$m259$,'22cd2edb196be8179d6552c9de308d4f'),
(188,0,$m259$قانون البنك المركزى والجهاز المصرفى 194/2020 > الباب الرابع: نظم وخدمات الدفع والتكنولوجيا المالية > الفصل الأول: نظم وخدمات الدفع$m259$,$m259$يلتزم مشغل نظام الدفع أو مقدم خدمات الدفع بأداء ضمان مالى لتنفيذ شروط الترخيص والوفاء بالالتزامات المنصوص عليها فى هذا القانون ، وذلك طبقاً للقواعد التى يصدر بتحديدها قرار من مجلس الإدارة ، يتضمن على الأخص قواعد تحديد قيمة هذا الضمان ونوعه ، وقواعد الخصم منه .$m259$,'631acf34a2566e736bbaa6b4a67b11d5'),
(189,0,$m259$قانون البنك المركزى والجهاز المصرفى 194/2020 > الباب الرابع: نظم وخدمات الدفع والتكنولوجيا المالية > الفصل الأول: نظم وخدمات الدفع$m259$,$m259$يجوز لمقدمى خدمات الدفع الاستعانة بوكلاء عنهم فى ممارسة الأنشطة المرخص لهم بها وذلك طبقاً للضوابط والشروط والإجراءات التى يحددها مجلس الإدارة .
ويتم تسجيل الوكلاء فى سجل خاص بالبنك المركزى ، وذلك دون الإخلال بحق البنك المركزى فى رفض تسجيلهم أو شطبهم إذا ارتأى ضرورة لذلك .
ويظل مقدم خدمات الدفع مسئولاً فى جميع الأحوال عن الأعمال التى يمارسها الوكيل نيابة عنه ، وعليه أن يتحقق من التزام الوكيل بجميع القوانين والقرارات المنظمة لممارسة النشاط .$m259$,'39e89bf42daf08eea629b9cad66b8ae7'),
(190,0,$m259$قانون البنك المركزى والجهاز المصرفى 194/2020 > الباب الرابع: نظم وخدمات الدفع والتكنولوجيا المالية > الفصل الأول: نظم وخدمات الدفع$m259$,$m259$يعتمد مجلس الإدارة القواعد الرئيسية لتشغيل نظم الدفع ، وتشمل على الأخص ما يأتى :
( أ ) قواعد إصدار أوامر التحويل ، وتحديد اللحظة التى لا يجوز بعدها للمشارك العدول عن تنفيذها .
( ب ) لحظة تسوية أوامر التحويل ، وآلية إتمام التسوية ، سواء تمت التسوية مباشرة أو عن طريق مقاصة ثنائية أو متعددة الأطراف .
( جـ ) أسس استخدام الأوراق أو الأدوات المالية كضمانة ، وطرق استخدامها للوفاء بمستحقات المشاركين بالنظام .
( د ) الإجراءات التى يمكن أن يتخذها فى حالة عدم قدرة أحد المشاركين فى النظام على الوفاء بالتزاماته .
( هـ ) لحظة نهائية التسوية والتى لا يجوز بعدها الرجوع فيها .
وللبنك المركزى إلزام مُشغل نظام الدفع بإجراء أى تعديل على تلك القواعد كلما ارتأى ذلك .
وتكون لأوامر التحويل التى تتم طبقاً لقواعد تشغيل نظم الدفع جميع الآثار القانونية ، وتكون نهائية وملزمة لأطرافها ، وواجبة النفاذ .$m259$,'1017cd729351857271b7b7a0d3511eb2'),
(191,0,$m259$قانون البنك المركزى والجهاز المصرفى 194/2020 > الباب الرابع: نظم وخدمات الدفع والتكنولوجيا المالية > الفصل الأول: نظم وخدمات الدفع$m259$,$m259$يحدد مجلس الإدارة اللحظة التى يتم فيها تسوية أمر الدفع والتى لا يجوز بعدها العدول عن تنفيذه ، وذلك بالنسبة لحسابات الدفع المفتوحة لكل من الدافع والمستفيد لدى ذات البنك أو مقدم خدمات الدفع .$m259$,'6daa09d3b4f81864d876723d5fff5bf8'),
(192,0,$m259$قانون البنك المركزى والجهاز المصرفى 194/2020 > الباب الرابع: نظم وخدمات الدفع والتكنولوجيا المالية > الفصل الأول: نظم وخدمات الدفع$m259$,$m259$لمجلس الإدارة إصدار قرار بتصنيف أى نظام دفع بأنه ذو أهمية نظامية ، سواء من تلقاء ذاته أو بناء على طلب من مشغل نظام الدفع ، وذلك فى ضوء الغرض منه ونطاق أعماله وقيمة معاملاته وعدد المشاركين فيه وتأثيره على استقرار النظام المالى فى الدولة ومدى قابليته لمتطلبات هذا التصنيف .
ويتضمن هذا القرار الواجبات الإضافية التى يتعين على مشغل نظام الدفع الالتزام بها ، وتحديد الفترة التى يتعين عليه توفيق أوضاعه خلالها .
ودون التقيد بأحكام أى قانون آخر ، تبقى سارية جميع القيود والتحويلات والمدفوعات التى تمت وأصبحت نهائية طبقاً للقواعد المعتمدة من مجلس الإدارة لنظام الدفع ذى الأهمية النظامية ، ولا يجوز المساس بها سواء عن طريق وقفها أو إبطالها أو الحجز عليها .
ومع عدم الإخلال بنهائية العملية ، يجوز استرداد المبالغ المحولة فى حالة ثبوت تحويلها بناءً على غش أو تدليس أو نتيجة لخطأ أو إهمال من مشغل نظام الدفع ذى الأهمية النظامية أو أحد مُشاركيه .
وذلك كله طبقاً للقواعد والإجراءات التى يحددها مجلس الإدارة .$m259$,'cc9ed4267774a82ad28dc28081d7892f'),
(193,0,$m259$قانون البنك المركزى والجهاز المصرفى 194/2020 > الباب الرابع: نظم وخدمات الدفع والتكنولوجيا المالية > الفصل الأول: نظم وخدمات الدفع$m259$,$m259$فى حالة تعرض أحد مشغلى نظم الدفع ذوى الأهمية النظامية أو أحد مشاركيه لإجراءات إنهاء الأعمال أو تسوية أوضاعه أو الإفلاس ، سواء تمت هذه الإجراءات داخل أو خارج جمهورية مصر العربية ، يتعين على المشغل القيام بالآتى :
( أ ) إخطار البنك المركزى فى اليوم الأول من بدء إجراءات إنهاء أعماله أو تسوية أوضاعه أو إفلاسه .
( ب ) إتمام المقاصة والتسوية لأوامر التحويل الصادرة قبل إخطاره ببدء إجراءات إنهاء الأعمال أو التسوية أو الإفلاس والتى أصبحت غير قابلة للرجوع فيها طبقاً لقواعد النظام ونافذة فى مواجهة الغير .
ودون التقيد بأحكام أى قانون آخر ، تكون لمطالبات المشاركين بنظام الدفع ذى الأهمية النظامية أو أى طرف آخر ينوب عنهم ، من ضمانات أو أوراق أو أدوات مالية أولوية عن أى مطالبات أخرى طبقاً لأولوية ترتيب المشاركين المبينة بقواعد النظام .$m259$,'e44e15775ddee3dccb13fa925d3067e2'),
(194,0,$m259$قانون البنك المركزى والجهاز المصرفى 194/2020 > الباب الرابع: نظم وخدمات الدفع والتكنولوجيا المالية > الفصل الأول: نظم وخدمات الدفع$m259$,$m259$يلتزم مشغلو نظم الدفع بالسماح للبنوك ومقدمى خدمات الدفع بالمشاركة فى نظم الدفع التى يديرونها على أساس موضوعى دون تمييز بشرط ألا يترتب على ذلك التأثير سلباً على الاستقرار المالى والتشغيلى للنظام .
كما تلتزم البنوك بالسماح لمشغلى نظم الدفع ومقدمى خدمات الدفع بفتح حساب مصرفى يمكنها من ممارسة أعمالها بفاعلية طبقاً لذات الضوابط المنصوص عليها فى الفقرة الأولى من هذه المادة .$m259$,'58f867fb3de3430579b51e90eba4458a'),
(195,0,$m259$قانون البنك المركزى والجهاز المصرفى 194/2020 > الباب الرابع: نظم وخدمات الدفع والتكنولوجيا المالية > الفصل الأول: نظم وخدمات الدفع$m259$,$m259$لمجلس الإدارة حماية للاستقرار المصرفى أو لحقوق العملاء أن يصدر قراراً بمنع أو تقييد أو تعديل أو إضافة أو وقف أى من الأنشطة أو العمليات التى يمارسها مشغلو نظم الدفع أو مقدمو خدمات الدفع ، كما يجوز له اتخاذ جميع الإجراءات اللازمة لتسوية العمليات السابقة على اتخاذ تلك القرارات .$m259$,'604d033376fef4630f00ad733b56d192'),
(196,0,$m259$قانون البنك المركزى والجهاز المصرفى 194/2020 > الباب الرابع: نظم وخدمات الدفع والتكنولوجيا المالية > الفصل الأول: نظم وخدمات الدفع$m259$,$m259$لمجلس الإدارة ، حال ثبوت مخالفة أى من مقدمى خدمات الدفع ، لأحكام هذا القانون أو اللوائح أو القرارات الصادرة تنفيذاً له ، اتخاذ واحد أو أكثر من الإجراءات أو الجزاءات التالية بما يتناسب مع طبيعته :
( أ ) توجيه تنبيه .
( ب ) إلزامه بإزالة المخالفة واتخاذ إجراءات تصحيحية خلال مدة محددة .
( جـ ) تقييد أو تعليق أو منع مقدمى خدمات الدفع من ممارسة أى من الأنشطة أو العمليات المرخص لهم بمزاولتها .
( د ) توقيع جزاءات مالية على مقدمى خدمات الدفع طبقاً للضوابط المنصوص عليها فى المادة ( 145 ) من هذا القانون .
( هـ ) تنحية واحد أو أكثر من المسئولين الرئيسيين .
( و ) إلزامه بتقديم خطة لإعادة الهيكلة .
( ز ) حل مجلس إدارته ، وتعيين مدير مؤقت لإدارته لمدة لا تجاوز ستة أشهر يجوز مدها لمدة مماثلة ، ويعرض المدير المؤقت قبل انتهاء مدة تعيينه الأمر على الجمعية العامة لاختيار مجلس إدارة جديد ، أو اتخاذ ما تراه لازماً .
( ح ) إلزامه بزيادة رأسماله .
( ط ) إلغاء الترخيص .
ويجوز للبنك المركزى نشر أى من الإجراءات أو الجزاءات المشار إليها .$m259$,'d5e70e8fc12bd07ca013404ffea685b6'),
(197,0,$m259$قانون البنك المركزى والجهاز المصرفى 194/2020 > الباب الرابع: نظم وخدمات الدفع والتكنولوجيا المالية > الفصل الأول: نظم وخدمات الدفع$m259$,$m259$لا يجوز لمشغل نظام الدفع أو لمقدم خدمات الدفع اتخاذ أى إجراء يترتب عليه إنهاء أو إيقاف أو التأثير على نشاطه أو تقديم خدمة جديدة دون الحصول على موافقة مسبقة من البنك المركزى ، ويتعين عليه إخطار البنك المركزى بأى حادث من شأنه أن يؤثر على استمرارية الخدمة أو عمل النظام ، وذلك كله طبقاً للقواعد والإجراءات التى يحددها مجلس الإدارة .
ويصدر مجلس الإدارة القواعد والإجراءات المنظمة لإنهاء أعمال مشغلى نظم الدفع ومقدمى خدمات الدفع ، تتضمن على الأخص تنظيم كيفية التصرف فى أصولهم وآلية الاحتفاظ والأرشفة الإلكترونية للمستندات والسجلات الخاصة بهم .$m259$,'ca3f46a409eb49a3922a34fb09ec6f2a'),
(198,0,$m259$قانون البنك المركزى والجهاز المصرفى 194/2020 > الباب الرابع: نظم وخدمات الدفع والتكنولوجيا المالية > الفصل الأول: نظم وخدمات الدفع$m259$,$m259$يلتزم مشغلو نظم الدفع ومقدمو خدمات الدفع حال ممارستهم للأنشطة المرخص بها بضمان التالى كحد أدنى :
( أ ) استمرارية تقديم الأنشطة المرخص بها .
( ب ) عدم التمييز بين المستفيدين منها .
( جـ ) توفير الحماية اللازمة للنظم الإلكترونية المستخدمة ضد أى محاولة لاختراق إلكترونى أو ولوج غير مصرح به إلى النظام ، أو تلاعب فى البيانات أو مساس بسريتها وخصوصيتها .$m259$,'f5862a78008c2a4daba6e73c3e974117'),
(199,0,$m259$قانون البنك المركزى والجهاز المصرفى 194/2020 > الباب الرابع: نظم وخدمات الدفع والتكنولوجيا المالية > الفصل الأول: نظم وخدمات الدفع$m259$,$m259$يسرى فى شأن مُشغلى نظم الدفع أحكام المواد ( 94 ، 124 ، 126 ، 144 ، 145 ، 146 ، 147 ، 148 ) من هذا القانون .
ويسرى فى شأن مشغلى نظم الدفع ذوى الأهمية النظامية أحكام الفصل الثانى عشر من الباب الثالث من هذا القانون .
ويسرى فى شأن مشغلى نظم الدفع ومقدمى خدمات الدفع أحكام المواد ( 83 ، 92 ، 93 ، 96 ، 97 ، 120 ، 121 ، 130 ، 131 ، 172 ، 173 ) وأحكام الفصل الثانى من الباب الثالث من هذا القانون .
وتسرى أحكام الفصل التاسع من الباب الثالث من هذا القانون على جميع عمليات الدفع .
وذلك كله طبقاً للشروط والقواعد والإجراءات التى يحددها مجلس الإدارة بما يتناسب مع طبيعتها .$m259$,'cf102766257e0c1086d147e7a14fce14'),
(200,0,$m259$قانون البنك المركزى والجهاز المصرفى 194/2020 > الباب الرابع: نظم وخدمات الدفع والتكنولوجيا المالية > الفصل الأول: نظم وخدمات الدفع$m259$,$m259$يجوز لأى شخص إصدار تفويض بالخصم مباشر وفاءً لمدفوعات مستقبلية .
ويضمن من أصدر تفويض الخصم المباشر الوفاء بقيمة أوامر الخصم المباشر الواردة به طبقاً للتعليمات المبينة به ، ويبطل كل اتفاق يخالف ذلك .
ولا يجوز الامتناع عن الوفاء بقيمة أمر الخصم المباشر متى كان لدى الجهة المسحوب عليها مقابل وفاء ولو انقضى ميعاد تقديمه ، وفى حالة امتناع الجهة المسحوب عليها عن الوفاء بقيمة أمر الخصم المباشر يجب عليها إثبات الامتناع عن الدفع وسببه ببيان مكتوب يصدر عنها يتضمن قيمته وتوقيت تقديمه .
وتسرى على أمر الخصم المباشر فيما لم يرد فى شأنه حكم خاص فى هذه المادة ، أحكام الفصل الثالث من الباب الرابع من قانون التجارة الصادر بالقانون رقم 17 لسنة 1999 بالقدر الذى لا تتعارض فيه مع طبيعته .
وذلك كله طبقاً للضوابط والإجراءات التى يحددها مجلس الإدارة .$m259$,'35f8917be3ada435dbd019060ca29c73'),
(201,0,$m259$قانون البنك المركزى والجهاز المصرفى 194/2020 > الباب الرابع: نظم وخدمات الدفع والتكنولوجيا المالية > الفصل الثانى: التكنولوجيا المالية$m259$,$m259$مع عدم الإخلال بأحكام القانون رقم 10 لسنة 2009 بتنظيم الرقابة على الأسواق والأدوات المالية غير المصرفية ، يكون للبنك المركزى اتخاذ جميع الإجراءات اللازمة لتعزيز تنمية استخدام التكنولوجيا الحديثة فى أى من مجالات تقديم الخدمات المالية أو المصرفية أو الرقابية على الجهات المرخص لها أو ما تستخدمه تلك الجهات للامتثال للقواعد الحاكمة ، وله على الأخص ما يأتى :
( أ ) إنشاء بيئة اختبار رقابية لتطبيقات التكنولوجيا المالية والتكنولوجيا الرقابية .
( ب ) الإعفاء بصفة مؤقتة من بعض متطلبات الترخيص المنصوص عليها فى هذا القانون للشركات الناشئة وغيرها من الجهات التى تختبر التكنولوجيا المالية والتكنولوجيا الرقابية لتقديم الخدمات المالية المبتكرة .
وذلك طبقاً للقواعد والإجراءات التى يحددها مجلس الإدارة .$m259$,'960363c727b0055b06f7f9e0f8f36ac3'),
(202,0,$m259$قانون البنك المركزى والجهاز المصرفى 194/2020 > الباب الرابع: نظم وخدمات الدفع والتكنولوجيا المالية > الفصل الثانى: التكنولوجيا المالية$m259$,$m259$يضع مجلس الإدارة معايير ومتطلبات وصلاحيات التطبيقات الإلكترونية التى تتيح الولوج إلى حسابات العملاء لدى البنوك أو مقدمى خدمات الدفع وكذا تنفيذ المعاملات عليها .
وتلتزم البنوك ومقدمو خدمات الدفع بإتاحة هذا الولوج إذا تم من خلال تطبيقات إلكترونية يتوافر فيها المعايير والمتطلبات المشار إليها .$m259$,'b057db63016bed14c88245ef7d31d7c6'),
(203,0,$m259$قانون البنك المركزى والجهاز المصرفى 194/2020 > الباب الرابع: نظم وخدمات الدفع والتكنولوجيا المالية > الفصل الثانى: التكنولوجيا المالية$m259$,$m259$مع عدم الإخلال بأحكام القانون رقم 15 لسنة 2004 بتنظيم التوقيع الإلكترونى وبإنشاء هيئة تنمية صناعة تكنولوجيا المعلومات ، يتعين على الجهات المرخص لها ومكاتب تمثيل البنوك الأجنبية المُسجلة لدى البنك المركزى الاحتفاظ بصور إلكترونية من السجلات والعقود والمراسلات والأوراق التجارية والوثائق المتعلقة بالمعاملات البنكية وخدمات الدفع ، وذلك للمدد المحددة قانوناً للاحتفاظ بأصولها .
ويكون لهذه الصور ذات حجية أصل المحررات فى الإثبات متى كان الاحتفاظ بها وتداولها واسترجاعها قد تم طبقاً للقواعد والمعايير الفنية التى يحددها مجلس الإدارة .$m259$,'633a4ea6888424b0d08d7d6801944c59'),
(204,0,$m259$قانون البنك المركزى والجهاز المصرفى 194/2020 > الباب الرابع: نظم وخدمات الدفع والتكنولوجيا المالية > الفصل الثانى: التكنولوجيا المالية$m259$,$m259$مع عدم الإخلال بأحكام القانون رقم 15 لسنة 2004 المشار إليه ، لمجلس الإدارة إصدار أو اعتماد القواعد والإجراءات المنظمة لكل من :
( أ ) إصدار أى من الجهات المرخص لها شروط وأحكام تقديم خدماتها إلكترونياً .
( ب ) المصادقة الإلكترونية على المعاملات البنكية وأوامر الدفع وأوامر التحويل ، وقبول الشروط والأحكام الخاصة بها .
( جـ ) التسوية الإلكترونية للشيكات .
( د ) إصدار وتداول الشيكات الإلكترونية بمراعاة الأحكام المنظمة للشيك الواردة بقانون التجارة الصادر بالقانون رقم 17 لسنة 1999
( هـ ) تفويض وأمر الخصم المباشر فى الصورة الإلكترونية .
ويكون لهذه الوسائل الإلكترونية ذات حجية أصل المحررات فى الإثبات ، متى كان تنفيذها وتداولها والاحتفاظ بها واسترجاعها قد تم طبقاً للقواعد والمعايير الفنية التى يحددها مجلس الإدارة .$m259$,'fc5e6508b610116eaa9669aa7e3a8bc2'),
(205,0,$m259$قانون البنك المركزى والجهاز المصرفى 194/2020 > الباب الرابع: نظم وخدمات الدفع والتكنولوجيا المالية > الفصل الثانى: التكنولوجيا المالية$m259$,$m259$يلتزم مقدمو التمويل الرقمى المقترن بتقديم خدمة دفع أو تحصيل إلكترونى بالحصول على موافقة البنك المركزى قبل تقديم هذه الخدمات ، وذلك طبقاً للقواعد والإجراءات التى يصدر بتحديدها قرار من مجلس الإدارة .$m259$,'28ab90ee17809629924edfc772b8a835'),
(206,0,$m259$قانون البنك المركزى والجهاز المصرفى 194/2020 > الباب الرابع: نظم وخدمات الدفع والتكنولوجيا المالية > الفصل الثانى: التكنولوجيا المالية$m259$,$m259$يحظر إصدار العملات المشفرة أو النقود الإلكترونية أو الاتجار فيها أو الترويج لها أو إنشاء أو تشغيل منصات لتداولها أو تنفيذ الأنشطة المتعلقة بها بدون الحصول على ترخيص من مجلس الإدارة طبقاً للقواعد والإجراءات التى يحددها .$m259$,'47982c05f941e069207f05e370b5d1d8'),
(207,0,$m259$قانون البنك المركزى والجهاز المصرفى 194/2020 > الباب الخامس: تنظيم التعامل فى النقد الأجنبى$m259$,$m259$لمجلس الإدارة أن يرخص لشركات الصرافة وبعض الجهات الأخرى بالتعامل فى النقد الأجنبى طبقاً لأحكام هذا القانون .
ويحدد مجلس الإدارة شروط الترخيص ونظام العمل فى تلك الشركات والجهات وكذلك نظام رقابة البنك المركزى عليها .
ويتم تسجيل شركات الصرافة والجهات الأخرى المرخص لها وفروعها فى سجل خاص يعد لهذا الغرض لدى البنك المركزى ، وذلك بعد أداء رسم معاينة مقداره مائة ألف جنيه عن المركز الرئيسى ، وخمسون ألف جنيه عن كل فرع .
ويتعين الحصول على موافقة المحافظ قبل إنشاء أى فرع جديد وقبل افتتاحه للتعامل .
ويسرى فى شأن تلك الشركات والجهات أحكام المادة ( 92 ) من هذا القانون .
وللمحافظ ، فى حالة مخالفة أى من هذه الشركات أو الجهات لشروط الترخيص أو لنظام العمل المشار إليه توجيه تنبيه أو إيقاف النشاط لمدة لا تجاوز سنة أو توقيع جزاء مالى طبقاً للضوابط المنصوص عليها فى المادة ( 145 ) من هذا القانون أو إلغاء الترخيص وشطب القيد من السجل .
ويجب إلغاء الترخيص وشطب التسجيل فى حالة التوقف عن مزاولة النشاط أو الاندماج دون الحصول على موافقة البنك المركزى ، أو فى حالة إشهار الإفلاس أو التصفية ، أو فى حالة اتباع سياسة من شأنها الإضرار بالمصلحة الاقتصادية العامة أو بتنظيم سوق الصرف الأجنبى .$m259$,'c557e761aa4b6db2e629c7b9947f2d30'),
(208,0,$m259$قانون البنك المركزى والجهاز المصرفى 194/2020 > الباب الخامس: تنظيم التعامل فى النقد الأجنبى$m259$,$m259$يلزم أن تتخذ شركة الصرافة شكل شركة مساهمة مصرية ، وأن يكون غرضها الوحيد مزاولة عمليات الصرافة ، وألا يقل رأسمالها المصدر والمدفوع عن خمسة وعشرين مليون جنيه .
ويتولى مراجعة حسابات شركة الصرافة مراقب حسابات من بين المقيدين فى سجل مراقبى الحسابات بالبنك المركزى ، ولا يجوز للمراقب الواحد أن يراجع حسابات أكثر من ثلاث شركات فى وقت واحد ، وتلتزم الشركة بإخطار البنك المركزى بتعيين مراقب الحسابات خلال ثلاثين يوماً من تاريخ التعيين .$m259$,'a3290e636e1d518b947612182bc4a631'),
(209,0,$m259$قانون البنك المركزى والجهاز المصرفى 194/2020 > الباب الخامس: تنظيم التعامل فى النقد الأجنبى$m259$,$m259$لمجلس الإدارة أن يرخص للشركات بتقديم خدمات تحويل الأموال ، ويجب أن تتخذ شركة تحويل الأموال شكل شركة مساهمة مصرية ، وألا يقل رأسمالها المصدر والمدفوع عن خمسة وعشرين مليون جنيه .
ويحدد مجلس الإدارة بقرار منه قواعد وشروط وإجراءات الترخيص ونظام العمل فى شركات تحويل الأموال ونظام رقابة البنك المركزى عليها .
كما يجوز الترخيص للشركات الأجنبية بإنشاء فروع لها فى جمهورية مصر العربية لمزاولة نشاط تحويل الأموال بشرط ألا يقل رأس المال المخصص لعمل الفرع عن مليون دولار أمريكى .
ويعد فى البنك المركزى سجل لقيد تلك الشركات وذلك بعد أداء رسم معاينة مقداره مائة ألف جنيه عن المركز الرئيسى ، وخمسون ألف جنيه عن كل فرع .
ويتولى مراجعة حسابات شركة تحويل الأموال مراقب حسابات من بين المقيدين فى سجل مراقبى الحسابات بالبنك المركزى ، ولا يجوز للمراقب الواحد أن يراجع حسابات أكثر من ثلاث شركات فى وقت واحد ، وعلى الشركة أن تخطر البنك المركزى بتعيين مراقب الحسابات خلال ثلاثين يوماً من تاريخ التعيين .
ويسرى فى شأن شركات تحويل الأموال أحكام المادتين ( 144 ، 145 ) من هذا القانون بما يتناسب مع طبيعتها .$m259$,'270feca3d4a60169e4a238200c8ab212'),
(210,0,$m259$قانون البنك المركزى والجهاز المصرفى 194/2020 > الباب الخامس: تنظيم التعامل فى النقد الأجنبى$m259$,$m259$يحدد مجلس الإدارة رسم رقابة سنوى على شركات الصرافة وغيرها من الجهات التى رخص لها بالتعامل فى النقد الأجنبى وشركات تحويل الأموال المسجلة لديه ، يسدد خلال شهر يناير من كل عام بما لا يجاوز عشرين ألف جنيه عن مركزها الرئيسى ، وعشرة آلاف جنيه عن كل فرع .$m259$,'d6e4b4657ab62c359de8a9490f0b2414'),
(211,0,$m259$قانون البنك المركزى والجهاز المصرفى 194/2020 > الباب الخامس: تنظيم التعامل فى النقد الأجنبى$m259$,$m259$يصدر بالقواعد والأسس المتعلقة بتنظيم سوق النقد الأجنبى قرار من مجلس الإدارة .
ويتحدد سعر الصرف للجنيه المصرى مقابل العملات الأجنبية بتفاعل قوى العرض والطلب فى سوق النقد الأجنبى .$m259$,'15eec90d2733c23822775842b68ea3e0'),
(212,0,$m259$قانون البنك المركزى والجهاز المصرفى 194/2020 > الباب الخامس: تنظيم التعامل فى النقد الأجنبى$m259$,$m259$لكل شخص طبيعى أو اعتبارى أن يحتفظ بكل ما يئول إليه أو يملكه أو يحوزه من نقد أجنبى ، وله الحق فى التعامل أو القيام بأى عملية من عمليات النقد الأجنبى بما فى ذلك التحويل للداخل والخارج .
وتتم هذه العمليات عن طريق البنوك أو عن طريق الجهات التى رخص لها بذلك طبقاً لأحكام هذا القانون ، طبقاً للقواعد والإجراءات التى يحددها مجلس الإدارة .
ويكون التعامل داخل جمهورية مصر العربية بالجنيه المصرى ، وذلك ما لم ينص على خلاف ذلك فى اتفاقية دولية أو فى قانون آخر أو فى الحالات التى يصدر بتحديدها قرار من مجلس الإدارة .$m259$,'4ff0309532e92bac30fcbbc188ac8dc6'),
(213,0,$m259$قانون البنك المركزى والجهاز المصرفى 194/2020 > الباب الخامس: تنظيم التعامل فى النقد الأجنبى$m259$,$m259$إدخال النقد الأجنبى إلى البلاد مكفول لجميع القادمين للبلاد ، على أن يتم الإفصاح عنه فى الإقرار المعد لهذا الغرض إذا جاوز عشرة آلاف دولار أمريكى أو ما يعادلها بالعملات الأجنبية الأخرى .
وإخراج النقد الأجنبى من البلاد مكفول لجميع المسافرين بشرط ألا يزيد على عشرة آلاف دولار أمريكى أو ما يعادلها بالعملات الأجنبية الأخرى ، مع السماح عند المغادرة لجميع المسافرين بحمل ما تبقى من المبالغ السابق الإفصاح عنها عند الوصول إذا زاد على عشرة آلاف دولار أمريكى أو ما يعادلها بالعملات الأجنبية الأخرى .
ويجوز للقادمين للبلاد أو المسافرين منها حمل أوراق النقد المصرى فى حدود المبلغ الذى يحدده مجلس الإدارة .
ويحظر إدخال النقد المصرى أو الأجنبى أو إخراجه من خلال الرسائل والطرود البريدية .
واستثناء من الحد المنصوص عليه فى الفقرة الثانية من هذه المادة ، يجوز إخراج النقد الأجنبى المحول من الخارج لحساب السفن الراسية بالموانئ المصرية متى تم ذلك طبقاً للقواعد والإجراءات التى يحددها مجلس الإدارة .$m259$,'95fb1384d0f1ce48c9a078cb8cd29f45'),
(214,0,$m259$قانون البنك المركزى والجهاز المصرفى 194/2020 > الباب الخامس: تنظيم التعامل فى النقد الأجنبى$m259$,$m259$للبنوك القيام بجميع عمليات النقد الأجنبى ، بما فى ذلك قبول الودائع والتعامل والتحويل للداخل والخارج والتشغيل والتغطية فيما تحوزه من أرصدة بالنقد الأجنبى .
ويجوز للبنوك تصدير واستيراد العملات الأجنبية بعد موافقة البنك المركزى .
وللمحافظ فى حالة مخالفة البنك لقواعد وإجراءات هذا التعامل أن يتخذ ما يراه مناسباً من إجراءات بما فى ذلك إيقاف البنك عن التعامل فى النقد الأجنبى لمدة لا تجاوز سنة .$m259$,'9431d857d56afeac02168ff7d4bbfa70'),
(215,0,$m259$قانون البنك المركزى والجهاز المصرفى 194/2020 > الباب الخامس: تنظيم التعامل فى النقد الأجنبى$m259$,$m259$على البنوك وشركات الصرافة والجهات التى رخص لها بالتعامل فى النقد الأجنبى أن تقدم للبنك المركزى بيانات عما تباشره من عمليات النقد الأجنبى سواء تمت لحسابها أو لحساب الغير ، ويحدد مجلس الإدارة محتوى البيانات وأسلوب ومواعيد تقديمها .
ويقوم البنك المركزى بمراقبة تنفيذ عمليات النقد الأجنبى طبقاً لأحكام هذا القانون واللوائح والقرارات الصادرة تنفيذاً له .$m259$,'be8b8986597778925e951eff322563ba'),
(216,0,$m259$قانون البنك المركزى والجهاز المصرفى 194/2020 > الباب السادس: حماية العملاء ، وحماية المنافسة ، وتسوية المنازعات$m259$,$m259$لا تسرى أحكام قانون حماية المستهلك الصادر بالقانون رقم 181 لسنة 2018 على الجهات المرخص لها بموجب أحكام هذا القانون ، ويختص البنك المركزى بحماية حقوق العملاء . وله فى سبيل ذلك على الأخص ما يأتى :
( أ ) وضع الخطط وبرامج العمل لحماية حقوق العملاء .
( ب ) نشر الثقافة المصرفية والمالية بين المواطنين .
( جـ ) تلقى الشكاوى من عملاء الجهات المرخص لها وفحصها .$m259$,'bfe8be289e587ec0867465253efa19f4'),
(217,0,$m259$قانون البنك المركزى والجهاز المصرفى 194/2020 > الباب السادس: حماية العملاء ، وحماية المنافسة ، وتسوية المنازعات$m259$,$m259$يصدر مجلس الإدارة لائحة تنظم حقوق العملاء ، تشمل على الأخص التزام الجهات المرخص لها بما يأتى :
( أ ) الإفصاح بشفافية ومصداقية عن البيانات والمعلومات الجوهرية للخدمات التى تقدمها .
( ب ) صياغة شروط وأحكام عقود تقديم الخدمات بشكل واضح ومفهوم لجميع فئات العملاء .
( جـ ) التعامل مع العملاء دون تمييز طبقاً لمبادئ العدالة والإنصاف والمصداقية .
( د ) التأكد من التزام الشركات التى تؤدى خدمات للعملاء بالنيابة عن الجهات المرخص لها بقواعد حماية حقوق العملاء ، وذلك مع عدم الإخلال بمسئولية الجهات المرخص لها عن أى أضرار تلحق بالعملاء جراء ذلك .
( هـ ) توفير آلية سريعة ومجانية للتعامل مع شكاوى العملاء بشكل عادل وبشفافية وفعالية .
( و ) توفير نظم آمنة تضمن سلامة بيانات وحسابات العملاء وسريتها .
( ز ) نشر قائمة بأسعار الخدمات التى تقدمها والبيانات الأساسية عنها .$m259$,'1bf749532dbf56007d96c2822ea42025'),
(218,0,$m259$قانون البنك المركزى والجهاز المصرفى 194/2020 > الباب السادس: حماية العملاء ، وحماية المنافسة ، وتسوية المنازعات$m259$,$m259$تنشأ بالبنك المركزى وحدة ذات طابع خاص لحماية حقوق عملاء الجهات المرخص لها ، تتولى فحص الشكاوى المقدمة منهم ضد هذه الجهات ، وذلك خلال ثلاثين يوماً من تاريخ تقديمها مستوفية المستندات المطلوبة .
فإذا تبين للوحدة عدم صحة الشكوى يتم حفظها وإبلاغ مقدم الشكوى بذلك ، أما إذا تبين صحة الشكوى ولم يتم حلها وديا ، تحال إلى لجنة فض المنازعات المنصوص عليها فى المادة ( 219 ) من هذا القانون مرفقاً بها تقرير بنتائج الفحص .
ويصدر بتشكيل الوحدة ونظام العمل بها قرار من مجلس الإدارة .$m259$,'c37703f605f45238c2a18807f6a462cd'),
(219,0,$m259$قانون البنك المركزى والجهاز المصرفى 194/2020 > الباب السادس: حماية العملاء ، وحماية المنافسة ، وتسوية المنازعات$m259$,$m259$تشكل بقرار من مجلس الإدارة لجنة أو أكثر تتولى فض المنازعات التى ينشأ فيها خلاف بين أى من الجهات المرخص لها وعملائها .
ويكون تشكيل اللجنة برئاسة أحد أعضاء الجهات القضائية . وعضوية أحد العاملين بالبنك المركزى وأحد ذوى الخبرة المستقلين من غير العاملين بالبنك المركزى .
وللجنة أن تستعين فى أداء عملها بمن تراه دون أن يكون لهم صوت معدود فى التصويت ، كما يجوز لها ندب خبير أو أكثر فى مجال الخدمة محل الشكوى .
ويصدر مجلس الإدارة القرارات المنظمة لعمل اللجنة وتشكيل أمانتها الفنية .$m259$,'4b3766234e03d3c60a38331e62d95de6'),
(220,0,$m259$قانون البنك المركزى والجهاز المصرفى 194/2020 > الباب السادس: حماية العملاء ، وحماية المنافسة ، وتسوية المنازعات$m259$,$m259$تفصل لجنة فض المنازعات فى الشكوى خلال ستين يوماً بموجب قرار نهائى مسبب ، ويجوز لذوى الشأن الطعن فى هذا القرار أمام محكمة القضاء الإدارى خلال ثلاثين يوماً .
ويجوز للجنة أثناء نظر الشكوى التوصية بإصدار قرار بوقف تقديم الخدمة إلى حين انتهاء الفحص .
وفى حالة ثبوت مخالفة أى من الجهات المرخص لها ، يجوز للجنة إلزام الجهة المخالفة بتصويب الوضع وإزالة المخالفة فوراً أو خلال الفترة الزمنية التى تحددها ، وذلك دون الإخلال بسلطة مجلس الإدارة فى اتخاذ أى من الإجراءات أو توقيع أى من الجزاءات المنصوص عليها فى هذا القانون أو بأحكام المسئولية الناشئة عن هذه المخالفات .$m259$,'5e1dc63a5254bddc79d3b3f386fd5339'),
(221,0,$m259$قانون البنك المركزى والجهاز المصرفى 194/2020 > الباب السادس: حماية العملاء ، وحماية المنافسة ، وتسوية المنازعات$m259$,$m259$لا تسرى أحكام قانون حماية المنافسة ومنع الممارسات الاحتكارية الصادر بالقانون رقم 3 لسنة 2005 على الجهات المرخص لها ، ويحظر عليها القيام بأى ممارسات احتكارية أو ضارة بالمنافسة ، ويشمل ذلك على الأخص ما يأتى :
( أ ) الاتفاق على تحديد أسعار الخدمات محل التعامل أو شروط التعاقد عليها أو اقتسام الأسواق أو التقدم للمناقصات والمزايدات .
( ب ) تقييد إتاحة الخدمات بهدف الإضرار بالعملاء .
( جـ ) تقديم خدمات بسعر يقل عن تكلفتها يترتب عليه الإضرار بالمنافسة .
( د ) إلزام العملاء أو مقدمى الخدمات أو الموردين بعدم التعامل مع جهات منافسة دون أسباب معقولة .
وذلك كله طبقاً للضوابط والإجراءات التى يحددها مجلس الإدارة .$m259$,'a451553118408f96569fd2fd160ccb47'),
(222,0,$m259$قانون البنك المركزى والجهاز المصرفى 194/2020 > الباب السادس: حماية العملاء ، وحماية المنافسة ، وتسوية المنازعات$m259$,$m259$ينشأ بالبنك المركزى وحدة ذات طابع خاص ، تختص بتلقى البلاغات عن أى ممارسات احتكارية أو ضارة بالمنافسة تتعلق بأى من الجهات المرخص لها ، واتخاذ إجراءات التقصى والبحث وجمع الاستدلالات فى شأنها .
كما يسرى ذلك على الأفعال التى ترتكب فى الخارج إذا ترتب عليها منع حرية المنافسة أو تقييدها أو الإضرار بها فى مصر .
وفى حالة ثبوت الإخلال بحرية المنافسة أو القيام بممارسات احتكارية ، يجوز لمجلس الإدارة تكليف الجهة المخالفة بتعديل أوضاعها وإزالة المخالفة فوراً أو خلال فترة زمنية محددة ، وإلا وقع الاتفاق أو التعاقد المخالف باطلاً ، وذلك دون الإخلال بسلطة مجلس الإدارة فى اتخاذ أى من الإجراءات المنصوص عليها فى المادة ( 144 ) من هذا القانون .
وذلك كله طبقاً للضوابط والإجراءات التى يحددها مجلس الإدارة .$m259$,'c922decedf7d6c60d704501a450bdc34'),
(223,0,$m259$قانون البنك المركزى والجهاز المصرفى 194/2020 > الباب السادس: حماية العملاء ، وحماية المنافسة ، وتسوية المنازعات$m259$,$m259$ينشأ مركز مستقل للتحكيم والتسوية فى المنازعات التى تنشأ بسبب تطبيق أحكام هذا القانون والقوانين ذات الصلة بالمعاملات المصرفية وغيرها من الأنشطة التى تباشرها الجهات المرخص لها ، وتكون لهذا المركز شخصية اعتبارية وميزانية مستقلة ، ويكون مقره محافظة القاهرة ، ويمثل المركز رئيس مجلس إدارته أمام القضاء والغير .
ويتولى إدارة المركز مجلس إدارة لا يزيد عدد أعضائه على تسعة أعضاء من ذوى الخبرة يصدر بتعيينهم وتحديد معاملتهم المالية قرار من مجلس الإدارة لمدة أربع سنوات قابلة للتجديد .
ويكون للمركز مدير تنفيذى يتم اختياره من ذوى الخبرة ، ويصدر بتعيينه قرار من مجلس إدارة المركز .
وتتكون الموارد المالية للمركز من مقابل الخدمات التى يقدمها ، والاعتمادات التى يخصصها له البنك المركزى ، والمنح والإعانات التى يوافق عليها مجلس الإدارة .
ويجوز لأطراف المنازعة اللجوء إلى هذا المركز إذا ما اتفقوا ابتداءً أو لاحقاً على تسوية النزاع عن طريق التحكيم أو التسوية ، ويصدر بالنظام الأساسى لهذا المركز ونظام العمل فيه والإجراءات المنظمة له ومقابل الخدمات التى يقدمها وقوائم المحكمين والوسطاء وأتعابهم قرار من مجلس إدارة المركز ، وذلك مع مراعاة أحكام القوانين المصرية المنظمة للتحكيم وتسوية المنازعات .$m259$,'b5c7134e32615fd8414b09d5f2f944e2'),
(224,0,$m259$قانون البنك المركزى والجهاز المصرفى 194/2020 > الباب السابع: العقوبات$m259$,$m259$مع عدم الإخلال بأى عقوبة أشد منصوص عليها فى قانون العقوبات أو أى قانون آخر ، يعاقب على الجرائم المبينة فى المواد التالية بالعقوبات المنصوص عليها فيها .$m259$,'c39609256e4cf99b92f4039fa85e1b80'),
(225,0,$m259$قانون البنك المركزى والجهاز المصرفى 194/2020 > الباب السابع: العقوبات$m259$,$m259$يعاقب بالحبس وبغرامة لا تقل عن مليون جنيه ولا تجاوز عشرة ملايين جنيه ، أو بإحدى هاتين العقوبتين ، كل من خالف أياً من أحكام المواد ( 63 ، 184 ، 205 ، 206 ) من هذا القانون .
وفى حالة العود يحكم بالحبس والغرامة معاً .$m259$,'bf23dcbc8e09aa0e60c81208f0e4a2fa'),
(226,0,$m259$قانون البنك المركزى والجهاز المصرفى 194/2020 > الباب السابع: العقوبات$m259$,$m259$يعاقب بالحبس وبغرامة لا تقل عن مائة ألف جنيه ولا تجاوز مليون جنيه ، أو بإحدى هاتين العقوبتين ، كل من خالف حكم الفقرة الثانية من المادة ( 104 ) من هذا القانون .
ويعاقب بغرامة لا تقل عن عشرة آلاف جنيه ولا تجاوز مائة ألف جنيه كل من خالف حكم المادة ( 59 ) من هذا القانون فيما يتعلق بإهانة أو تشويه النقد .$m259$,'76bc0316e187f68d0c02cf0091502fd8'),
(227,0,$m259$قانون البنك المركزى والجهاز المصرفى 194/2020 > الباب السابع: العقوبات$m259$,$m259$يعاقب بغرامة لا تقل عن خمسمائة ألف جنيه ولا تجاوز مليون جنيه كل من خالف أياً من أحكام المواد ( 81 ، 87 ، 92 ، 114 ، 126 ، 172 ، 197 ) من هذا القانون .$m259$,'38c913e899a4947ccf7c12aa4b2f3cc9'),
(228,0,$m259$قانون البنك المركزى والجهاز المصرفى 194/2020 > الباب السابع: العقوبات$m259$,$m259$يعاقب بغرامة لا تقل عن مليون جنيه ولا تجاوز مليونى جنيه كل من خالف أياً من أحكام التملك فى رءوس أموال البنوك المنصوص عليها فى المواد ( 74 ، 76 ، 78 ) من هذا القانون .$m259$,'49c2b0ae12c41871c4994ee51252cd3a'),
(229,0,$m259$قانون البنك المركزى والجهاز المصرفى 194/2020 > الباب السابع: العقوبات$m259$,$m259$يعاقب بغرامة لا تقل عن مائتى ألف جنيه ولا تجاوز خمسمائة ألف جنيه كل من امتنع عن تقديم البيانات أو التقارير أو المعلومات المشار إليها فى المواد ( 129 ، 130 ، 132 ) من هذا القانون .
ويعاقب بذات العقوبة كل من امتنع عن تقديم السجلات أو الأوراق أو المستندات لمن لهم حق الاطلاع عليها فضلاً عن الحكم بالتمكين من الاطلاع .$m259$,'d6d5bad041c2c8fae81aadb2727208b2'),
(230,0,$m259$قانون البنك المركزى والجهاز المصرفى 194/2020 > الباب السابع: العقوبات$m259$,$m259$يعاقب بالحبس وبغرامة لا تقل عن خمسمائة ألف جنيه ولا تجاوز مليون جنيه ، أو بإحدى هاتين العقوبتين . كل من تعمد بقصد الغش ذكر وقائع غير صحيحة أو أخفى بعض الوقائع فى البيانات أو فى المحاضر أو فى الأوراق الأخرى التى تقدم من الجهات المرخص لها إلى البنك المركزى بالتطبيق لأحكام هذا القانون .
ويعاقب بغرامة لا تقل عن مائة ألف جنيه ولا تجاوز مليون جنيه كل من ارتكب غشاً أو تدليساً فى تقديم خدمات الاستعلام أو التصنيف الائتمانى بقصد تيسير الحصول على الائتمان ، وذلك فضلاً عن الحكم عليه لصالح مانح الائتمان بمبلغ يعادل قيمة مالم يتم الوفاء به من الائتمان الممنوح بناءً على ما أصاب مانح الائتمان من ضرر بسبب ما ارتكبه من غش أو تدليس .$m259$,'f7909a72cc6bf92f60aed73e66ea7566'),
(231,0,$m259$قانون البنك المركزى والجهاز المصرفى 194/2020 > الباب السابع: العقوبات$m259$,$m259$يعاقب بالحبس مدة لا تقل عن سنة وبغرامة لا تقل عن مائتى ألف جنيه ولا تجاوز خمسمائة ألف جنيه ، أو بإحدى هاتين العقوبتين ، كل من خالف أياً من أحكام المادتين ( 140 ، 142 ) من هذا القانون ، وتتعدد الغرامات بتعدد المجنى عليهم .$m259$,'fb6ad1e53e596818eaed0511f8d9eedd'),
(232,0,$m259$قانون البنك المركزى والجهاز المصرفى 194/2020 > الباب السابع: العقوبات$m259$,$m259$مع عدم الإخلال بحكم المادة ( 231 ) من هذا القانون ، يعاقب بالحبس مدة لا تجاوز سنتين وبغرامة لا تقل عن خمسين ألف جنيه ولا تجاوز مائة ألف جنيه ، أو بإحدى هاتين العقوبتين . كل من أفشى من العاملين المكلفين بتنفيذ أحكام هذا القانون أو من العاملين بالجهات المرخص لها أى معلومات تتعلق بشئون الجهات التى يعملون بها أو أى معلومات حصلوا عليها بسبب وظيفتهم ، وتتعدد الغرامات بتعدد المجنى عليهم .$m259$,'3e28e46df099b0617fd56d47045edcfc'),
(233,0,$m259$قانون البنك المركزى والجهاز المصرفى 194/2020 > الباب السابع: العقوبات$m259$,$m259$يعاقب بالسجن مدة لا تقل عن ثلاث سنوات ولا تزيد على عشر سنوات وبغرامة لا تقل عن مليون جنيه ولا تجاوز خمسة ملايين جنيه أو المبلغ المالى محل الجريمة أيهما أكبر ، كل من تعامل فى النقد الأجنبى خارج البنوك المعتمدة أو الجهات التى رخص لها فى ذلك ، أو مارس نشاط تحويل الأموال دون الحصول على الترخيص طبقاً لنص المادة ( 209 ) من هذا القانون .
ويعاقب بالحبس مدة لا تقل عن ستة أشهر ولا تزيد على ثلاث سنوات وبغرامة لا تقل عن مليون جنيه ولا تجاوز خمسة ملايين جنيه ، أو بإحدى هاتين العقوبتين ، كل من خالف أياً من أحكام المادتين ( 214 ، 215 ) من هذا القانون .
ويعاقب بالحبس مدة لا تقل عن ثلاثة أشهر وبغرامة لا تقل عن المبلغ المالى محل الجريمة ولا تزيد على أربعة أمثال ذلك المبلغ ، أو بإحدى هاتين العقوبتين ، كل من خالف أياً من أحكام المادة ( 213 ) من هذا القانون .
وفى جميع الأحوال تضبط المبالغ والأشياء محل الدعوى ويحكم بمصادرتها ، فإن لم تضبط حكم بغرامة إضافية تعادل قيمتها .$m259$,'42100a5b1e7212db8c17b14189c0e23e'),
(234,0,$m259$قانون البنك المركزى والجهاز المصرفى 194/2020 > الباب السابع: العقوبات$m259$,$m259$تعتبر أموال البنك المركزى وأموال البنوك أموالاً عامة فى تطبيق أحكام قانون العقوبات .$m259$,'7c47edbb54812e0c4f31178cef30ac8c'),
(235,0,$m259$قانون البنك المركزى والجهاز المصرفى 194/2020 > الباب السابع: العقوبات$m259$,$m259$فى الأحوال التى ترتكب فيها الجريمة بواسطة شخص اعتبارى يعاقب المسئول عن الإدارة الفعلية للشخص الاعتبارى المخالف بذات العقوبات المقررة على الأفعال التى ترتكب بالمخالفة لأحكام هذا القانون ، متى ثبت علمه بها ، وكانت الجريمة قد وقعت بسبب إخلاله بواجبات الوظيفة .
ويكون الشخص الاعتبارى مسئولاً بالتضامن معه عن الوفاء بما يحكم به من عقوبات مالية وتعويضات ، إذا كانت الجريمة قد ارتكبت من أحد العاملين به باسمه نيابة عنه .$m259$,'62de836d73ebbde46e25fc9cbd5e4d75'),
(236,0,$m259$قانون البنك المركزى والجهاز المصرفى 194/2020 > الباب السابع: العقوبات$m259$,$m259$يجوز بالنسبة للجرائم المنصوص عليها فى هذا الباب أن تأمر المحكمة بنشر ملخص الحكم الصادر بالإدانة فى صحيفة أو أكثر أو بنشره بأى طريق آخر على نفقة المحكوم عليه .$m259$,'e705913016c879043f9b7001cac0fc33'),
(237,0,$m259$قانون البنك المركزى والجهاز المصرفى 194/2020 > الباب السابع: العقوبات$m259$,$m259$يكون لموظفى البنك المركزى الذين يصدر بتحديدهم قرار من وزير العدل بالاتفاق مع المحافظ صفة مأمورى الضبط القضائى بالنسبة إلى الجرائم التى تقع بالمخالفة لأحكام هذا القانون واللوائح والقرارات الصادرة تنفيذاً له وتكون متعلقة بأعمال وظائفهم .$m259$,'4c47bd7f33a25b4fc2ea6e6e710788dc'),
(238,0,$m259$قانون البنك المركزى والجهاز المصرفى 194/2020 > الباب السابع: العقوبات$m259$,$m259$فى غير حالات التلبس ، لا يجوز رفع الدعوى الجنائية أو اتخاذ أى إجراء من إجراءات التحقيق فى الجرائم المنصوص عليها فى هذا القانون ، والقرارات الصادرة تنفيذاً له ، وفى الجرائم المنصوص عليها فى الباب الرابع من الكتاب الثانى من قانون العقوبات فى نطاق تطبيق أحكام هذا القانون ، إلا بناءً على طلب كتابى من المحافظ .$m259$,'a79fa236aa6a39ee92630b5fa0899196'),
(239,0,$m259$قانون البنك المركزى والجهاز المصرفى 194/2020 > الباب السابع: العقوبات$m259$,$m259$يتلقى المحافظ ما يرد من النيابة العامة إعمالاً لحكم المادة ( 238 ) من هذا القانون وكذلك ما يرد إليه من تقارير الجهات الرقابية والأمنية عن المخالفات المصرفية بما فيها ما يتعلق بالتمويل والتسهيلات الائتمانية .
وتتولى إدارة متخصصة بالبنك المركزى تضم خبراء فى الشئون المصرفية والاقتصادية والقانونية فحص ودراسة ما يحيله إليها المحافظ مما يتلقاه تطبيقاً لأحكام الفقرة الأولى من هذه المادة .
وعلى البنوك أن توافى هذه الإدارة بما تطلبه من المستندات والبيانات والمعلومات اللازمة لإتمام الفحص والدراسة .
وتعد الإدارة المشار إليها خلال مدة لا تجاوز ثلاثين يوماً من تاريخ الإحالة تقريراً بنتائج الفحص والدراسة مشفوعاً بالرأى ، ويعرض التقرير فور إعداده على المحافظ لاتخاذ الإجراءات اللازمة فى ضوئه طبقاً لأحكام القانون .$m259$,'54eb6d073669dea04aa88d60b85712d7'),
(240,0,$m259$قانون البنك المركزى والجهاز المصرفى 194/2020 > الباب السابع: العقوبات$m259$,$m259$للبنوك الخاضعة لأحكام هذا القانون التصالح فى الجرائم المشار إليها فى المادة ( 238 ) منه ولو كان قد صدر فى شأنها الطلب المنصوص عليه فى هذه المادة ، وذلك فى أى حالة تكون عليها الدعوى ، فإذا تم التصالح قبل صدور حكم بات فيها ، يشترط لنفاذه إتمام الوفاء بحقوق البنك طبقاً لشروط التصالح ، وفى حالة صيرورة الحكم باتاً لا يكون التصالح نافذاً إلا إذا قام المحكوم عليه بالوفاء المسبق بمستحقات البنك .
وفى جميع الأحوال ، يشترط موافقة مجلس إدارة البنك الدائن على التصالح ، ويحرر عنه محضر يوقعه أطرافه ، ويعرض على المحافظ مؤيداً بالمستندات للنظر فى اعتماده ، ولا يكون التصالح نافذاً إلا بهذا الاعتماد وتوثيقه ، ويكون التوثيق بدون رسوم .
فإذا لم يوافق مجلس إدارة البنك الدائن على التصالح رغم الوفاء بمستحقات البنك طبقاً لشروط التصالح يعرض الأمر بناءً على طلب ذى الشأن على مجلس الإدارة لاتخاذ ما يراه مناسباً .
ويكون لمحضر التصالح فى هذه الحالة قوة السند التنفيذى ، ويتولى المحافظ إخطار النائب العام به .
ويعتبر ذلك الإخطار بمثابة تنازل عن الطلب المشار إليه فى المادة ( 238 ) ويترتب عليه انقضاء الدعوى الجنائية عن الواقعة محل التصالح بجميع أوصافها .
وتأمر النيابة العامة بوقف تنفيذ العقوبات المحكوم بها على المتهمين فى الواقعة إذا تم التصالح قبل صيرورة الحكم باتاً .
وإذا تم التصالح بعد صيرورة الحكم باتاً ، وكان المحكوم عليه محبوساً نفاذاً لهذا الحكم ، جاز له أن يتقدم إلى النائب العام بطلب لوقف التنفيذ مشفوعاً بالمستندات المؤيدة له .
ويرفع النائب العام الطلب إلى محكمة النقض مشفوعاً بهذه المستندات وبمذكرة برأى النيابة العامة فيه وذلك خلال عشرة أيام من تاريخ تقديمه .
ويعرض الطلب على إحدى الدوائر الجنائية بالمحكمة منعقدة فى غرفة مشورة لنظره لتأمر بقرار مسبب بوقف تنفيذ العقوبات نهائياً إذا تحققت من إتمام التصالح واستيفائه جميع الشروط والإجراءات المنصوص عليها فى هذه المادة .
ويكون الفصل فى الطلب خلال خمسة عشر يوماً من تاريخ عرضه ، وبعد سماع أقوال النيابة العامة والمحكوم عليه ، وفى جميع الأحوال ، يمتد أثر التصالح من حيث انقضاء الدعوى الجنائية أو وقف تنفيذ العقوبات إلى جميع المتهمين أو المحكوم عليهم فى ذات الواقعة .$m259$,'d922fe3ad2ffb7cdb2532872e8a05575'),
(241,0,$m259$قانون البنك المركزى والجهاز المصرفى 194/2020 > الباب السابع: العقوبات$m259$,$m259$للمحافظ حق تخصيص نسبة لا تجاوز ( 10٪ ) من المبالغ المصادرة والغرامات الإضافية توزع على كل من أرشد أو عاون فى ضبط إحدى الجرائم المرتكبة بالمخالفة لأحكام الباب السابع من هذا القانون أو اكتشافها أو فى استيفاء الإجراءات المتصلة بها ، وذلك طبقاً للقواعد التى يضعها مجلس الإدارة .$m259$,'9adf566c8fa2fa2e410d7971f9e6f11e');

DO $m259$
DECLARE
  v_law uuid;
  v_title text;
  v_new_law boolean := false;
  v_ins_art int;
  v_ins_ver int;
  v_cnt int;
  v_nover int;
BEGIN
  IF (SELECT count(*) FROM m259_art WHERE md5(body) <> body_md5) <> 0 THEN
    RAISE EXCEPTION '[259] تلف فى نص أحد الصفوف داخل الملف';
  END IF;
  IF (SELECT count(*) FROM m259_art) <> 250 OR (SELECT sum(char_length(body)) FROM m259_art) <> 148433 THEN
    RAISE EXCEPTION '[259] عدد الصفوف أو طول النص داخل الملف غير مطابق';
  END IF;

  SELECT id, title INTO v_law, v_title FROM laws WHERE country_code='EG' AND law_no=194 AND law_year=2020 AND kind='law';
  IF v_law IS NOT NULL AND v_title NOT LIKE '%البنك المركزى%' THEN
    RAISE EXCEPTION '[259] يوجد مستند آخر برقم 194 لسنة 2020 من نوع law (%): لا يُدمج هذا القانون فيه', v_title;
  END IF;
  IF v_law IS NULL THEN
    INSERT INTO laws (law_no, law_year, title, short_title, category, status, official_url, enacted_at, last_amended_at, country_code, kind, governance_scope)
    VALUES (194, 2020, $t259$القانون رقم 194 لسنة 2020 بإصدار قانون البنك المركزى والجهاز المصرفى (النص الأصلى المنشور فى 15/9/2020 قبل أى تعديلات)$t259$, $t259$قانون البنك المركزى والجهاز المصرفى 194/2020$t259$, 'other', 'in_force', NULL, DATE '2020-09-15', NULL, 'EG', 'law', false)
    RETURNING id INTO v_law;
    v_new_law := true;
  END IF;

  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, body)
  SELECT v_law, article_no, suffix, loc, body FROM m259_art
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING;
  GET DIAGNOSTICS v_ins_art = ROW_COUNT;

  INSERT INTO article_versions (article_id, version_no, body, effective_from, status, change_note)
  SELECT a.id, 1, a.body, DATE '2020-09-16', 'active',
         $n259$النص الأصلى كما نشر فى الجريدة الرسمية العدد 37 مكرر (و) فى 15/9/2020 (قانون الإصدار والمواد 1 إلى 241 من القانون المرافق)؛ لم تُراجع التعديلات اللاحقة إن وجدت، فقد لا يطابق هذا النص الصيغة النافذة$n259$ || CASE WHEN a.article_suffix_order = -1 AND a.article_no = 7 THEN $x259$ - المادة 7 من قانون الإصدار تلغى القانون 88 لسنة 2003 والمواد المذكورة فيها؛ ولم تُحدَّث حالة تلك السجلات فى هذه الهجرة$x259$ ELSE '' END
    FROM articles a JOIN m259_art m ON m.article_no = a.article_no AND m.suffix = a.article_suffix_order
   WHERE a.law_id = v_law
     AND NOT EXISTS (SELECT 1 FROM article_versions v WHERE v.article_id = a.id)
  ON CONFLICT (article_id, version_no) DO NOTHING;
  GET DIAGNOSTICS v_ins_ver = ROW_COUNT;

  SELECT count(*) INTO v_cnt FROM articles a JOIN m259_art m ON m.article_no=a.article_no AND m.suffix=a.article_suffix_order
   WHERE a.law_id=v_law;
  IF v_cnt <> 250 THEN
    RAISE EXCEPTION '[259] عدد صفوف القانون % بدل 250', v_cnt;
  END IF;
  SELECT count(*) INTO v_nover FROM articles a
   WHERE a.law_id=v_law AND NOT EXISTS (SELECT 1 FROM article_versions v WHERE v.article_id=a.id);
  IF v_nover <> 0 THEN
    RAISE EXCEPTION '[259] % صف بلا نسخة', v_nover;
  END IF;
  RAISE NOTICE '[259] قانون 194/2020: جديد=%، صفوف مضافة=%، نسخ مضافة=%', v_new_law, v_ins_art, v_ins_ver;
END
$m259$;
